  %iota = "stablehlo.iota"() {iota_dimension = 0 : i64} : () -> tensor<8xi32>

  // Broadcast idx from [5] to [5x8]
  %idx_bcast = "stablehlo.broadcast_in_dim"(%idx) {broadcast_dimensions = array<i64: 0>} : (tensor<5xi32>) -> tensor<5x8xi32>

  // Broadcast iota from [8] to [5x8]
  %iota_bcast = "stablehlo.broadcast_in_dim"(%iota) {broadcast_dimensions = array<i64: 1>} : (tensor<8xi32>) -> tensor<5x8xi32>

  // Compare idx_bcast == iota_bcast
  %eq = "stablehlo.compare"(%idx_bcast, %iota_bcast) {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5x8xi32>, tensor<5x8xi32>) -> tensor<5x8xi1>

  // Check idx in [0,7]: idx >= 0 and idx < 8
  %zero = stablehlo.constant dense<0> : tensor<i32>
  %ge0 = "stablehlo.compare"(%idx, %zero) {comparison_direction = #stablehlo<comparison_direction GE>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<5xi32>, tensor<5xi32>) -> tensor<5xi1>
