  %const_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<f32> to tensor<6x7xf32> broadcast_dimensions = []

  %min_out = stablehlo.minimum %linear_out_bias, %const_broadcast : tensor<6x7xf32>

  // Subtract constant scalar (broadcasted)
  %result = stablehlo.subtract %min_out, %const_broadcast : tensor<6x7xf32>

  func.return %result : tensor<6x7xf32>
}

