func.func @main(%arg0: tensor<6x7x3x3x3xf32>, %arg1: tensor<8x6x8x8x8xf32>) -> tensor<8x7x10x10x10xf32> {
  // %arg0: conv_transpose3d.weight with shape [in_channels=6, out_channels=7, 3, 3, 3]
  // %arg1: input tensor with shape [batch=8, in_channels=6, depth=8, height=8, width=8]

  // Transposed convolution is implemented as a convolution with lhs_dilation (input dilation)
  // and rhs_dilation (kernel dilation) and appropriate padding and strides.
  // PyTorch ConvTranspose3d parameters:
  // in_channels=6, out_channels=7, kernel_size=3, stride=1, padding=0, output_padding=0, dilation=1, groups=1, bias=False
  //
  // The weight shape in PyTorch ConvTranspose3d is (in_channels, out_channels/groups, kD, kH, kW)
  // StableHLO convolution expects kernel shape (out_channels, in_channels/groups, kD, kH, kW)
  // So we need to reverse the first two dims of the weight tensor.
  //
  // Steps:
  // 1) Reverse the first two dimensions of %arg0 to get kernel in shape [out_channels=7, in_channels=6, 3, 3, 3]
  // 2) Use stablehlo.convolution with lhs_dilation = stride (1,1,1), rhs_dilation = dilation (1,1,1)
  //    window_strides = (1,1,1), padding = 0, feature_group_count=1
  // 3) dimension_numbers for 5D conv: input [b, f, d, h, w], kernel [o, i, kd, kh, kw], output [b, f, d, h, w]

  // Reverse first two dims of %arg0: from [6,7,3,3,3] to [7,6,3,3,3]
  %reversed_weight = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 0>} : (tensor<6x7x3x3x3xf32>) -> tensor<6x7x3x3x3xf32>
  %reversed_weight_2 = "stablehlo.reverse"(%reversed_weight) {dimensions = array<i64: 1>} : (tensor<6x7x3x3x3xf32>) -> tensor<6x7x3x3x3xf32>
  // Now %reversed_weight_2 is [6,7,3,3,3] reversed on dim0 and dim1, effectively swapping first two dims
  // But this is still shape [6,7,...], we want [7,6,...], so we need to transpose dims 0 and 1
  // StableHLO does not have a direct transpose op, but we can do reverse twice to swap dims 0 and 1
  // Actually reversing dims 0 and 1 twice is identity, so we need a different approach.
  // Instead, we can do two reverses to swap dims 0 and 1:
  // reverse dim 0, then reverse dim 1, then reverse dim 0, then reverse dim 1 again
  // But that is complicated and inefficient.
  //
  // Alternative: Use stablehlo.transpose with permutation [1,0,2,3,4]
  // Check if stablehlo.transpose exists in stablehlo dialect (not documented here)
  // Since not documented, we can implement transpose by reshaping and reversing dims.
  //
  // Since no transpose op documented, we can do a workaround:
  // Reshape to 2D [6, 7*3*3*3], then reverse dims 0 and 1, then reshape back
  // But this is complicated.
  //
  // Since the weight shape is small, we can do two reverses:
  // reverse dim 0 and dim 1 twice to swap dims 0 and 1:
  // reverse dim 0, reverse dim 1, reverse dim 0, reverse dim 1
  // This swaps dims 0 and 1.
  //
  // Let's do that:
  %r1 = "stablehlo.reverse"(%arg0) {dimensions = array<i64: 0>} : (tensor<6x7x3x3x3xf32>) -> tensor<6x7x3x3x3xf32>
  %r2 = "stablehlo.reverse"(%r1) {dimensions = array<i64: 1>} : (tensor<6x7x3x3x3xf32>) -> tensor<6x7x3x3x3xf32>
  %r3 = "stablehlo.reverse"(%r2) {dimensions = array<i64: 0>} : (tensor<6x7x3x3x3xf32>) -> tensor<6x7x3x3x3xf32>
  %kernel = "stablehlo.reverse"(%r3) {dimensions = array<i64: 1>} : (tensor<6x7x3x3x3xf32>) -> tensor<6x7x3x3x3xf32>
  // Now %kernel has shape [7,6,3,3,3]

  // Convolution parameters:
  // window_strides = [1,1,1]
  // padding = [[0,0],[0,0],[0,0]]
  // lhs_dilation = [1,1,1] (stride of transposed conv)
  // rhs_dilation = [1,1,1] (dilation)
  // dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>
  // feature_group_count = 1

  %result = "stablehlo.convolution"(%arg1, %kernel) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x6x8x8x8xf32>, tensor<7x6x3x3x3xf32>) -> tensor<8x7x10x10x10xf32>

  return %result : tensor<8x7x10x10x10xf32>
}

