func.func @main(%arg0: tensor<6x7x3x3x3xf32>, %arg1: tensor<8x6x8x8x8xf32>) -> tensor<8x7x10x10x10xf32> {
  // %arg0: weight tensor of shape [in_channels=6, out_channels=7, kernel_d=3, kernel_h=3, kernel_w=3]
  // %arg1: input tensor of shape [batch=8, in_channels=6, depth=8, height=8, width=8]
  // We want to compute ConvTranspose3d with:
  // stride=1, padding=0, output_padding=0, dilation=1, groups=1, bias=False
  // Output shape: [8, 7, 10, 10, 10]

  // StableHLO ConvTranspose3d is done by Conv with reversed roles and reversed kernel spatial dims.
  // Steps:
  // 1) Reverse kernel spatial dims (D,H,W)
  // 2) Transpose kernel from [in_c, out_c, kD, kH, kW] to [out_c, in_c, kD, kH, kW]
  // 3) Perform Conv with:
  //    input: %arg1 [N, C_in, D, H, W]
  //    kernel: reversed and transposed kernel [C_out, C_in, kD, kH, kW]
  //    window strides = [1,1,1]
  //    padding = [0,0,0,0,0,0]
  //    lhs_dilation = [1,1,1]
  //    rhs_dilation = [1,1,1]
  //    dimension_numbers = NCDHW for input, OIDHW for kernel, NCDHW for output
  //    feature_group_count = 1

  // Reverse kernel spatial dims (dims 2,3,4)
  %reversed_kernel = stablehlo.reverse %arg0 : tensor<6x7x3x3x3xf32> {dimensions = [2,3,4]}

  // Transpose kernel from [in_c=6, out_c=7, kD=3, kH=3, kW=3] to [out_c=7, in_c=6, kD=3, kH=3, kW=3]
  %permuted_kernel = stablehlo.transpose %reversed_kernel [1,0,2,3,4] : tensor<6x7x3x3x3xf32> to tensor<7x6x3x3x3xf32>

  // Prepare convolution dimension numbers attribute
  // input: NCDHW = [batch, channels, depth, height, width] = [0,1,2,3,4]
  // kernel: OIDHW = [out_channels, in_channels, depth, height, width] = [0,1,2,3,4]
  // output: NCDHW = [batch, channels, depth, height, width] = [0,1,2,3,4]
  %dim_numbers = {
    input_batch_dimension = 0,
    input_feature_dimension = 1,
    input_spatial_dimensions = [2, 3, 4],
    kernel_output_feature_dimension = 0,
    kernel_input_feature_dimension = 1,
    kernel_spatial_dimensions = [2, 3, 4],
    output_batch_dimension = 0,
    output_feature_dimension = 1,
    output_spatial_dimensions = [2, 3, 4]
  }

  // Perform convolution
  %conv = stablehlo.convolution %arg1, %permuted_kernel {
    window_strides = [1, 1, 1],
    padding = [0, 0, 0, 0, 0, 0], // no padding
    lhs_dilation = [1, 1, 1],
    rhs_dilation = [1, 1, 1],
    feature_group_count = 1,
    batch_group_count = 1,
    dimension_numbers = %dim_numbers,
    precision_config = {operand_precision = [0, 0]}
