  %neg_inf = stablehlo.constant -inf : f32
  %init_max = stablehlo.broadcast_in_dim %neg_inf : tensor<f32> to tensor<6xf32> {broadcast_dimensions = dense<[0]>}
  %max = stablehlo.reduce %scaled_out, %init_max (
