  ) {dimensions = dense<[1]>} : (tensor<6x7xf32>, tensor<6xf32>) -> tensor<6xf32>

  // Broadcast max to (6x7)
  %max_bcast = stablehlo.broadcast_in_dim %max : tensor<6xf32> to tensor<6x7xf32> {broadcast_dimensions = dense<[0,1]>}

  // x - max
  %shifted = stablehlo.subtract %scaled_out, %max_bcast : tensor<6x7xf32>

  // exp(x - max)
  %exp_shifted = stablehlo.exponential %shifted : tensor<6x7xf32>

  // sum exp along dim=1
  %zero_exp = stablehlo.constant 0.0 : f32
  %init_sum = stablehlo.broadcast_in_dim %zero_exp : tensor<f32> to tensor<6xf32> {broadcast_dimensions = dense<[0]>}
  %sum_exp = stablehlo.reduce %exp_shifted, %init_sum

