func.func @main(%scale: tensor<1xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Linear layer: x @ weight^T + bias
  // weight shape: [7,7], input: [6,7]
  // We want to do dot_general with contracting dims: input last dim (1), weight last dim (1)
  // but weight needs to be transposed to [7,7] (actually square, so transpose is identity shape)
  // Actually, PyTorch Linear does x @ weight^T + bias, so we transpose weight
  %weight_t = "stablehlo.transpose"(%weight) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  %linear = "stablehlo.dot_general"(%input, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %linear_bias = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_out = stablehlo.add %linear, %linear_bias : tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // y = (x - mean) / sqrt(var + eps) * bn_weight + bn_bias
  // mean and var computed per feature (dim=0)
  // input shape: [6,7], reduce over dim 0 -> mean: [7]
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%linear_out, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean = sum / 6
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_bcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<7xf32>
  %mean_div = stablehlo.divide %mean, %six_bcast : tensor<7xf32>

  // Compute variance: var = mean((x - mean)^2)
  // First broadcast mean to [6,7]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 1} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %linear_out, %mean_bcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var = stablehlo.divide %var_sum, %six_bcast : tensor<7xf32>

  // Add eps=1e-5 to var
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<7xf32>
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<7xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) / stddev
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 1} : (tensor<7xf32>) -> tensor<6x7xf32>
  %norm = stablehlo.divide %diff, %stddev_bcast : tensor<6x7xf32>

  // Scale and shift: norm * bn_weight + bn_bias
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %norm, %bn_weight_bcast : tensor<6x7xf32>
  %shifted = stablehlo.add %scaled, %bn_bias_bcast : tensor<6x7xf32>

  // Multiply by scale parameter (broadcast scale from [1] to [6,7])
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 0} : (tensor<1xf32>) -> tensor<6x7xf32>
  %scaled_out = stablehlo.multiply %shifted, %scale_bcast : tensor<6x7xf32>

