  %max_per_row = "stablehlo.reduce"(%scaled_out, %init_min) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %max : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // Broadcast max_per_row to [6,7]
  %max_bcast = "stablehlo.broadcast_in_dim"(%max_per_row) {broadcast_dimensions = array<i64: 0} : (tensor<6xf32>) -> tensor<6x7xf32>
  // Subtract max for numerical stability
  %shifted_logits = stablehlo.subtract %scaled_out, %max_bcast : tensor<6x7xf32>
  // exp(shifted_logits)
  %exp_logits = stablehlo.exponential %shifted_logits : tensor<6x7xf32>
  // sum exp along dim=1
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_logits, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // Broadcast sum_exp to [6,7]
  %sum_exp_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0} : (tensor<6xf32>) -> tensor<6x7xf32>
  // Divide exp_logits by sum_exp to get softmax
  %softmax = stablehlo.divide %exp_logits, %sum_exp_bcast : tensor<6x7xf32>

  return %softmax : tensor<6x7xf32>
}

