    feature_group_count = 1,
    batch_group_count = 1
  } : (tensor<6x16x8x8xf32>, tensor<7x16x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: broadcast bias from [7] to [6x7x6x6]
  // Broadcast bias on feature dimension (dim=1)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = [1]} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  %bias_broadcast_6x7x6x6 = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = [0,1,2,3]} : (tensor<1x7x1x1xf32>) -> tensor<6x7x6x6xf32>
  %conv_bias = "stablehlo.add"(%conv, %bias_broadcast_6x7x6x6) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Compute minimum along channel dimension (dim=1), keepdim=True
  // Reduce min over dim=1, output shape: [6x1x6x6]
  %init_val = "stablehlo.constant"() {value = dense<inf> : tensor<f32>} : () -> tensor<f32>

  %reduce = "stablehlo.reduce"(%conv_bias, %init_val) ( {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %min = "stablehlo.minimum"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%min) : (tensor<f32>) -> ()
  }) {dimensions = [1]} : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x1x6x6xf32>

