  %tanh1 = "stablehlo.tanh"(%reduce) : (tensor<6x1x6x6xf32>) -> tensor<6x1x6x6xf32>
  %tanh2 = "stablehlo.tanh"(%tanh1) : (tensor<6x1x6x6xf32>) -> tensor<6x1x6x6xf32>

