func.func @main(%scale: tensor<1xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %x = input @ gemm: x * weight^T + bias
  // weight shape: 7x7, input: 6x7, want output 6x7
  // dot_general with contracting dims: input dim 1 and weight dim 1 (weight^T)
  // So lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]
  // lhs_batching_dimensions = [], rhs_batching_dimensions = []
  %x = "stablehlo.dot_general"(%input, %weight) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // add bias: bias shape 7, broadcast to 6x7 on dim 1
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_bias = stablehlo.add %x, %bias_broadcast : tensor<6x7xf32>

  // batch norm forward (training mode):
  // batch mean: mean over batch dim 0
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x_bias, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // divide by batch size 6
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean_scaled = stablehlo.divide %mean, %six_broadcast : tensor<7xf32>

  // x_centered = x_bias - mean
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_centered = stablehlo.subtract %x_bias, %mean_broadcast : tensor<6x7xf32>

  // variance: mean of squared centered
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x7xf32>
  %var_sum = "stablehlo.reduce"(%x_centered_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  %var = stablehlo.divide %var_sum, %six_broadcast : tensor<7xf32>

  // epsilon constant for numerical stability
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>

  // var + eps
  %var_eps = stablehlo.add %var, %eps_broadcast : tensor<7xf32>

  // rsqrt(var + eps)
  %rsqrt_var_eps = stablehlo.rsqrt %var_eps : tensor<7xf32>

  // normalize: x_centered * rsqrt_var_eps
  %rsqrt_broadcast = "stablehlo.broadcast_in_dim"(%rsqrt_var_eps) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_norm = stablehlo.multiply %x_centered, %rsqrt_broadcast : tensor<6x7xf32>

  // scale and shift: bn_weight * x_norm + bn_bias
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %x_norm, %bn_weight_broadcast : tensor<6x7xf32>
  %shifted = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7xf32>

  // multiply by scale parameter (shape 1), broadcast to 6x7
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 0>} : (tensor<1xf32>) -> tensor<6x1xf32>
  %scale_broadcast2 = "stablehlo.broadcast_in_dim"(%scale_broadcast) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x1xf32>) -> tensor<6x7xf32>
  %scaled2 = stablehlo.multiply %shifted, %scale_broadcast2 : tensor<6x7xf32>

  // softmax along dim 1 (features)
  // softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))
  // max along dim 1
  %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %max = "stablehlo.reduce"(%scaled2, %neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // broadcast max to 6x7
  %max_broadcast = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // x - max
  %x_shifted = stablehlo.subtract %scaled2, %max_broadcast : tensor<6x7xf32>
  // exp(x - max)
  %exp = stablehlo.exponential %x_shifted : tensor<6x7xf32>
  // sum exp along dim 1
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  // broadcast sum_exp to 6x7
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6xf32>) -> tensor<6x7xf32>
  // divide exp by sum_exp
  %softmax = stablehlo.divide %exp, %sum_exp_broadcast : tensor<6x7xf32>

  "stablehlo.return"(%softmax) : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<1xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0: scale (1,)
  // %arg1: gemm.weight (7x7)
  // %arg2: gemm.bias (7)
  // %arg3: bn.weight (7)
  // %arg4: bn.bias (7)
  // %arg5: input x (6x7)

  // Step 1: gemm: x @ weight^T + bias
  // gemm.weight shape: (7,7) but PyTorch Linear weight is (out_features, in_features)
  // input shape: (6,7)
  // So gemm.weight is (7,7) = (out_features, in_features)
  // We do dot_general with contracting dims: input (6,7), weight (7,7)
  // Contract input dim 1 with weight dim 1 (the in_features dimension)
  // Result shape: (6,7) (batch_size, out_features)
  %c0 = constant {i32 1} : tensor<1xi32>
  %c1 = constant {i32 1} : tensor<1xi32>
  %c2 = constant {i32 0} : tensor<1xi32>
  %c3 = constant {i32 0} : tensor<1xi32>

  %dot = stablehlo.dot_general %arg5, %arg1 {
    lhs_batching_dimensions = [0],
    rhs_batching_dimensions = [0],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [1]
  } : tensor<6x7xf32>, tensor<7x7xf32> -> tensor<6x7xf32>

  // Add gemm.bias (7) to each row of dot result (6x7)
  %bias_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %gemm_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // Step 2: BatchNorm1d on gemm_out (6x7)
  // BatchNorm1d normalizes over batch dimension (0) for each feature (1)
  // Compute mean over batch dim 0: result shape (7)
  %reduce_dims = constant dense<0> : tensor<i64>
  %one = constant dense<1> : tensor<i64>
  %batch_dim = constant dense<0> : tensor<i64>
  %feature_dim = constant dense<1> : tensor<i64>

  // Compute mean: sum over batch dim 0, then divide by batch size (6)
  %sum = stablehlo.reduce %gemm_out, %c0 {
    dimensions = [0],
    body = {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : tensor<6x7xf32>, tensor<1xf32> -> tensor<7xf32>

  %batch_size_f32 = constant dense<6.0> : tensor<f32>
  %mean = stablehlo.divide %sum, %batch_size_f32 : tensor<7xf32>

  // Compute variance: mean of squared differences
  // (x - mean)^2
  %mean_broadcast = stablehlo.broadcast_in_dim %mean : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %diff = stablehlo.subtract %gemm_out, %mean_broadcast : tensor<6x7xf32>
  %sq_diff = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  %var_sum = stablehlo.reduce %sq_diff, %c0 {
    dimensions = [0],
    body = {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : tensor<6x7xf32>, tensor<1xf32> -> tensor<7xf32>

  %variance = stablehlo.divide %var_sum, %batch_size_f32 : tensor<7xf32>

  // Add epsilon to variance
  %epsilon = constant dense<0.00001> : tensor<f32>
  %epsilon_broadcast = stablehlo.broadcast_in_dim %epsilon : tensor<f32> to tensor<7xf32> broadcast_dimensions = []
  %var_eps = stablehlo.add %variance, %epsilon_broadcast : tensor<7xf32>

  // Compute rsqrt(variance + eps)
  %rsqrt = stablehlo.rsqrt %var_eps : tensor<7xf32>

  // Normalize: (x - mean) * rsqrt
  %rsqrt_broadcast = stablehlo.broadcast_in_dim %rsqrt : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %norm = stablehlo.multiply %diff, %rsqrt_broadcast : tensor<6x7xf32>

  // Scale and shift: norm * bn.weight + bn.bias
  %bn_weight_broadcast = stablehlo.broadcast_in_dim %arg3 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]
  %bn_bias_broadcast = stablehlo.broadcast_in_dim %arg4 : tensor<7xf32> to tensor<6x7xf32> broadcast_dimensions = [1]

  %scaled = stablehlo.multiply %norm, %bn_weight_broadcast : tensor<6x7xf32>
  %bn_out = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7xf32>

  // Step 3: multiply by scale (shape (1,))
  %scale_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<1xf32> to tensor<6x7xf32> broadcast_dimensions = []
  %scaled_out = stablehlo.multiply %bn_out, %scale_broadcast : tensor<6x7xf32>

  // Step 4: softmax along dim=1 (features)
  // softmax(x) = exp(x) / sum(exp(x), dim=1)

  // Compute max for numerical stability
  %max = stablehlo.reduce %scaled_out, %c0 {
    dimensions = [1],
    body = {
      %a = stablehlo.maximum %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : tensor<6x7xf32>, tensor<1xf32> -> tensor<6xf32>

  %max_broadcast = stablehlo.broadcast_in_dim %max : tensor<6xf32> to tensor<6x7xf32> broadcast_dimensions = [0]

  // Subtract max
  %shifted = stablehlo.subtract %scaled_out, %max_broadcast : tensor<6x7xf32>

  // exp(shifted)
  %exp = stablehlo.exp %shifted : tensor<6x7xf32>

  // sum exp along dim=1
  %sum_exp = stablehlo.reduce %exp, %c0 {
    dimensions = [1],
    body = {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : tensor<6x7xf32>, tensor<1xf32> -> tensor<6xf32>

  %sum_exp_broadcast = stablehlo.broadcast_in_dim %sum_exp : tensor<6xf32> to tensor<6x7xf32> broadcast_dimensions = [0]

  // Divide exp by sum_exp
  %softmax = stablehlo.divide %exp, %sum_exp_broadcast : tensor<6x7xf32>

  // Return softmax output
  stablehlo.return %softmax : tensor<6x7xf32>
}

func.func @main(%arg0: tensor<1xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0: scale (1,)
  // %arg1: gemm.weight (7x7)
  // %arg2: gemm.bias (7)
  // %arg3: bn.weight (7)
  // %arg4: bn.bias (7)
  // %arg5: input x (6x7)

  // Step 1: gemm: x @ weight^T + bias
  // gemm.weight shape: (7,7) but PyTorch Linear weight is (out_features, in_features)
  // input shape: (6,7)
  // So gemm.weight is (7,7) = (out_features, in_features)
  // We do dot_general with contracting dims: input (6,7), weight (7,7)
  // Contract input dim 1 with weight dim 1 (the in_features dimension)
  // Result shape: (6,7) (batch_size, out_features)
  %dot = stablehlo.dot_general %arg5, %arg1 {
    lhs_batching_dimensions = [0],
    rhs_batching_dimensions = [0],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [1]
  } : tensor<6x7xf32>, tensor<7x7xf32> -> tensor<6x7xf32>

  // Add gemm.bias (7) to each row of dot result (6x7)
