func.func @main(%arg0: tensor<7x16x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x16x8x8xf32>) -> tensor<6x1x6x6xf32> {
  // Perform convolution: input %arg2 (6x16x8x8), weight %arg0 (7x16x3x3), bias %arg1 (7)
  // dimension_numbers = [b, c, h, w] x [o, i, kh, kw] -> [b, o, oh, ow]
  // window_strides = [1,1], padding = 0, dilation = 1
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, c, h, w]x[o, i, kh, kw]->[b, o, h, w]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x16x8x8xf32>, tensor<7x16x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add bias: broadcast bias %arg1 (7) to conv output shape (6x7x6x6)
  // Broadcast bias on dimension 1 (channels)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<1x7x1x1xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x6x6xf32>

  // Compute minimum along channel dimension (dim=1), keepdim=True
  // stablehlo.reduce with min operation over dimension 1
  %init_min = stablehlo.constant dense<9.999999e+36> : tensor<f32>
  %min = "stablehlo.reduce"(%conv_bias, %init_min) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %min_val = stablehlo.minimum %a, %b : tensor<f32>
      "stablehlo.return"(%min_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x1x6x6xf32>

  // Apply tanh twice
  %tanh1 = stablehlo.tanh %min : tensor<6x1x6x6xf32>
  %tanh2 = stablehlo.tanh %tanh1 : tensor<6x1x6x6xf32>

  return %tanh2 : tensor<6x1x6x6xf32>
}

// conv dimension_numbers attribute
#stablehlo.conv = {
  dimension_numbers = #stablehlo.conv<[b, c, h, w]x[o, i, kh, kw]->[b, o, h, w]>
}

func.func @main(%scale: tensor<1xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %x = gemm(input, weight) + bias
  // dot_general: batch dims empty, contract input feature dim 1 with weight dim 0
  %x = "stablehlo.dot_general"(%input, %weight) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  %x_bias = stablehlo.add %x, %bias : tensor<6x7xf32>

  // BatchNorm1d forward training mode:
  // mean = reduce mean over batch dim 0 -> shape (7)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %sum = "stablehlo.reduce"(%x_bias, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>
  // mean = sum / 6
  %six_f32 = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = stablehlo.broadcast_in_dim %six_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean = stablehlo.divide %sum, %six_broadcast : tensor<7xf32>

  // Compute variance: var = mean((x - mean)^2) over batch dim 0
  // Broadcast mean to (6x7)
  %mean_broadcast = stablehlo.broadcast_in_dim %mean {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %x_bias, %mean_broadcast : tensor<6x7xf32>
  %sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %init_var = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var_sum = "stablehlo.reduce"(%sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add2 = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add2) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>
  %var = stablehlo.divide %var_sum, %six_broadcast : tensor<7xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_broadcast = stablehlo.broadcast_in_dim %eps {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var_eps = stablehlo.add %var, %eps_broadcast : tensor<7xf32>
  %stddev = stablehlo.sqrt %var_eps : tensor<7xf32>
  %stddev_broadcast = stablehlo.broadcast_in_dim %stddev {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %normalized = stablehlo.divide %diff, %stddev_broadcast : tensor<6x7xf32>

  // Scale and shift: normalized * bn_weight + bn_bias
  %bn_weight_broadcast = stablehlo.broadcast_in_dim %bn_weight {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_broadcast = stablehlo.broadcast_in_dim %bn_bias {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %normalized, %bn_weight_broadcast : tensor<6x7xf32>
  %shifted = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7xf32>

  // Multiply by scale parameter (broadcast scale from (1) to (6x7))
  %scale_broadcast = stablehlo.broadcast_in_dim %scale {broadcast_dimensions = array<i64: 0, 1>} : (tensor<1xf32>) -> tensor<6x7xf32>
  %scaled_final = stablehlo.multiply %shifted, %scale_broadcast : tensor<6x7xf32>

  // Softmax along dim=1 (features)
  // softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))
  // Compute max per row (dim=1)
  %init_min = stablehlo.constant dense<-inf> : tensor<f32>
  %init_max = stablehlo.broadcast_in_dim %init_min {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6xf32>
  %max_per_row = "stablehlo.reduce"(%scaled_final, %init_max) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%max) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<6xf32>) -> tensor<6xf32>
  // Broadcast max_per_row to (6x7)
  %max_broadcast = stablehlo.broadcast_in_dim %max_per_row {broadcast_dimensions = array<i64: 0} : (tensor<6xf32>) -> tensor<6x7xf32>
  // x - max
  %shifted_x = stablehlo.subtract %scaled_final, %max_broadcast : tensor<6x7xf32>
  // exp(x - max)
  %exp_shifted = stablehlo.exponential %shifted_x : tensor<6x7xf32>
  // sum exp per row
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %init_sum = stablehlo.broadcast_in_dim %init_zero {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6xf32>
  %sum_exp = "stablehlo.reduce"(%exp_shifted, %init_sum) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<6xf32>) -> tensor<6xf32>
  // Broadcast sum_exp to (6x7)
  %sum_exp_broadcast = stablehlo.broadcast_in_dim %sum_exp {broadcast_dimensions = array<i64: 0} : (tensor<6xf32>) -> tensor<6x7xf32>
  // Divide exp by sum_exp
  %softmax = stablehlo.divide %exp_shifted, %sum_exp_broadcast : tensor<6x7xf32>

  "stablehlo.return"(%softmax) : tensor<6x7xf32>
}

func.func @main(%scale: tensor<1xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
