  %diff = stablehlo.subtract %x_bias, %mean_broadcast : tensor<6x7xf32>
  %sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %init_var = stablehlo.broadcast_in_dim %zero_f32 {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %var_sum = "stablehlo.reduce"(%sq, %init_var) ({
