  %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %hard_swish = stablehlo.divide %x_mul_sigmoid, %six_broadcast : tensor<6x1x31x13x13xf32>

  // Subtract bias (shape [1x1x1x1]) broadcasted to output shape
  %bias_broadcast_out = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1, 2, 3, 4>} : (tensor<1x1x1x1xf32>) -> tensor<6x1x31x13x13xf32>
  %sub_bias = stablehlo.subtract %hard_swish, %bias_broadcast_out : tensor<6x1x31x13x13xf32>

  // Clamp between -1 and 1
  %neg_one = stablehlo.constant dense<-1.0> : tensor<f32>
  %neg_one_broadcast = "stablehlo.broadcast_in_dim"(%neg_one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %max_clamped = stablehlo.maximum %sub_bias, %neg_one_broadcast : tensor<6x1x31x13x13xf32>
  %clamped = stablehlo.minimum %max_clamped, %one_broadcast : tensor<6x1x31x13x13xf32>

  // Return final result
  return %clamped : tensor<6x

func.func @main(%bias: tensor<1x1x1x1xf32>, %conv_transpose_weight: tensor<3x16x3x3x3xf32>, %conv_transpose_bias: tensor<16xf32>, %input: tensor<6x3x16x7x7xf32>) -> tensor<6x1x31x13x13xf32> {
  // Transpose conv_transpose_weight from (in_channels=3, out_channels=16, kD=3, kH=3, kW=3)
  // to (out_channels=16, in_channels=3, kD=3, kH=3, kW=3) for convolution rhs
  %weight_transposed = "stablehlo.transpose"(%conv_transpose_weight) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<3x16x3x3x3xf32>) -> tensor<16x3x3x3x3xf32>

  // Convolution parameters for transposed convolution:
  // lhs = input: [6, 3, 16, 7, 7]
  // rhs = weight_transposed: [16, 3, 3, 3, 3]
  // dimension_numbers = [b, f, 0, 1, 2] x [o, i, 0, 1, 2] -> [b, f, 0, 1, 2]
  // window_strides = [1,1,1] (for transposed conv, stride is handled by lhs_dilation)
  // lhs_dilation = stride = [2,2,2]
  // rhs_dilation = [1,1,1]
  // padding = padding = 1 on each spatial dim: [[1,1],[1,1],[1,1]]
  %conv = "stablehlo.convolution"(%input, %weight_transposed) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 2, 2, 2>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x31x13x13xf32>

  // Add conv_transpose_bias (shape [16]) to conv output (broadcast over batch and spatial dims)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_transpose_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<1x16x1x1x1xf32>
  %conv_bias_added = stablehlo.add %conv, %bias_broadcast : tensor<6x16x31x13x13xf32>

  // Compute logsumexp over dim=1 (feature dimension), keepdim=True
  // Steps:
  // 1) max over dim=1 for numerical stability
  %init_neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %max_reduce = "stablehlo.reduce"(%conv_bias_added, %init_neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x16x31x13x13xf32>, tensor<f32>) -> tensor<6x1x31x13x13xf32>

  // 2) subtract max, exp, sum over dim=1, then log, then add max back
  // Broadcast max_reduce to shape of conv_bias_added for subtraction
  %max_broadcast_expanded = "stablehlo.broadcast_in_dim"(%max_reduce) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<6x1x31x13x13xf32>) -> tensor<6x16x31x13x13xf32>
  %sub_max = stablehlo.subtract %conv_bias_added, %max_broadcast_expanded : tensor<6x16x31x13x13xf32>
  %exp_sub = stablehlo.exponential %sub_max : tensor<6x16x31x13x13xf32>
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_sub, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x16x31x13x13xf32>, tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6x1x31x13x13xf32>
  %lse = stablehlo.add %log_sum_exp, %max_reduce : tensor<6x1x31x13x13xf32>

  // HardSwish: x * sigmoid(x + 3) / 6
  %three = stablehlo.constant dense<3.0> : tensor<f32>
  %three_broadcast = "stablehlo.broadcast_in_dim"(%three) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %x_plus_3 = stablehlo.add %lse, %three_broadcast : tensor<6x1x31x13x13xf32>
  %sigmoid = stablehlo.logistic %x_plus_3 : tensor<6x1x31x13x13xf32>
  %x_mul_sigmoid = stablehlo.multiply %lse, %sigmoid : tensor<6x1x31x13x13xf32>
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %hard_swish = stablehlo.divide %x_mul_sigmoid, %six_broadcast : tensor<6x1x31x13x13xf32>

  // Subtract bias (shape [1x1x1x1]) broadcasted to output shape
  %bias_broadcast_out = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1, 2, 3, 4>} : (tensor<1x1x1x1xf32>) -> tensor<6x1x31x13x13xf32>
  %sub_bias = stablehlo.subtract %hard_swish, %bias_broadcast_out : tensor<6x1x31x13x13xf32>

  // Clamp between -1 and 1
  %neg_one = stablehlo.constant dense<-1.0> : tensor<f32>
  %neg_one_broadcast = "stablehlo.broadcast_in_dim"(%neg_one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %max_clamped = stablehlo.maximum %sub_bias, %neg_one_broadcast : tensor<6x1x31x13x13xf32>
  %clamped = stablehlo.minimum %max_clamped, %one_broadcast : tensor<6x1x31x13x13xf32>

  return %clamped : tensor<6x1x31x13x13xf32>
}

func.func @main(%bias: tensor<1x1x1x1xf32>, %conv_transpose_weight: tensor<3x16x3x3x3xf32>, %conv_transpose_bias: tensor<16xf32>, %input: tensor<6x3x16x7x7xf32>) -> tensor<6x1x31x13x13xf32> {
  // Transpose conv_transpose_weight from (in_channels=3, out_channels=16, kD=3, kH=3, kW=3)
  // to (out_channels=16, in_channels=3, kD=3, kH=3, kW=3) for convolution rhs
  %weight_transposed = "stablehlo.transpose"(%conv_transpose_weight) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<3x16x3x3x3xf32>) -> tensor<16x3x3x3x3xf32>

  // Convolution parameters for transposed convolution:
  // lhs = input: [6, 3, 16, 7, 7]
  // rhs = weight_transposed: [16, 3, 3, 3, 3]
  // dimension_numbers = [b, f, 0, 1, 2] x [o, i, 0, 1, 2] -> [b, f, 0, 1, 2]
  // window_strides = [1,1,1] (for transposed conv, stride is handled by lhs_dilation)
  // lhs_dilation = stride = [2,2,2]
  // rhs_dilation = [1,1,1]
  // padding = padding = 1 on each spatial dim: [[1,1],[1,1],[1,1]]
  %conv = "stablehlo.convolution"(%input, %weight_transposed) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 2, 2, 2>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x31x13x13xf32>

  // Add conv_transpose_bias (shape [16]) to conv output (broadcast over batch and spatial dims)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_transpose_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<1x16x1x1x1xf32>
  %conv_bias_added = stablehlo.add %conv, %bias_broadcast : tensor<6x16x31x13x13xf32>

  // Compute logsumexp over dim=1 (feature dimension), keepdim=True
  // Steps:
  // 1) max over dim=1 for numerical stability
  %init_neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %max_reduce = "stablehlo.reduce"(%conv_bias_added, %init_neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x16x31x13x13xf32>, tensor<f32>) -> tensor<6x1x31x13x13xf32>

  // 2) subtract max, exp, sum over dim=1, then log, then add max back
  // Broadcast max_reduce to shape of conv_bias_added for subtraction
  %max_broadcast_expanded = "stablehlo.broadcast_in_dim"(%max_reduce) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<6x1x31x13x13xf32>) -> tensor<6x16x31x13x13xf32>
  %sub_max = stablehlo.subtract %conv_bias_added, %max_broadcast_expanded : tensor<6x16x31x13x13xf32>
  %exp_sub = stablehlo.exponential %sub_max : tensor<6x16x31x13x13xf32>
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_sub, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x16x31x13x13xf32>, tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6x1x31x13x13xf32>
  %lse = stablehlo.add %log_sum_exp, %max_reduce : tensor<6x1x31x13x13xf32>

  // HardSwish: x * sigmoid(x + 3) / 6
  %three = stablehlo.constant dense<3.0> : tensor<f32>
  %three_broadcast = "stablehlo.broadcast_in_dim"(%three) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %x_plus_3 = stablehlo.add %lse, %three_broadcast : tensor<6x1x31x13x13xf32>
  %sigmoid = stablehlo.logistic %x_plus_3 : tensor<6x1x31x13x13xf32>
  %x_mul_sigmoid = stablehlo.multiply %lse, %sigmoid : tensor<6x1x31x13x13xf32>
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %hard_swish = stablehlo.divide %x_mul_sigmoid, %six_broadcast : tensor<6x1x31x13x13xf32>

  // Subtract bias (shape [1x1x1x1]) broadcasted to output shape
  %bias_broadcast_out = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x1x1x1xf32>) -> tensor<6x1x31x13x13xf32>
  %sub_bias = stablehlo.subtract %hard_swish, %bias_broadcast_out : tensor<6x1x31x13x13xf32>

  // Clamp between -1 and 1
  %neg_one = stablehlo.constant dense<-1.0> : tensor<f32>
  %neg_one_broadcast = "stablehlo.broadcast_in_dim"(%neg_one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  %max_clamped = stablehlo.maximum %sub_bias, %neg_one_broadcast : tensor<6x1x31x13x13xf32>
  %clamped = stablehlo.minimum %max_clamped, %one_broadcast : tensor<6x1x31x13x13xf32>

  return %clamped : tensor<6x1x31x13x13xf32>
}

