func.func @main(%arg0: tensor<1x1x1x1xf32>, %arg1: tensor<3x16x3x3x3xf32>, %arg2: tensor<16xf32>, %arg3: tensor<6x3x16x7x7xf32>) -> tensor<6x1x31x13x13xf32> {
  // %arg0: bias tensor<1x1x1x1xf32>
  // %arg1: conv_transpose.weight tensor<3x16x3x3x3xf32> (in_channels=3, out_channels=16)
  // %arg2: conv_transpose.bias tensor<16xf32> (not used in forward, but present)
  // %arg3: input tensor<6x3x16x7x7xf32>

  // Step 1: Perform ConvTranspose3d (transposed convolution)
  // ConvTranspose3d parameters:
  // in_channels=3, out_channels=16, kernel=3x3x3, stride=2, padding=1
  // StableHLO convolution dimension_numbers for ConvTranspose:
  // Input: [batch, feature, depth, height, width] = [6,3,16,7,7]
  // Kernel: [in_feature, out_feature, kd, kh, kw] = [3,16,3,3,3]
  // Output: [batch, feature, depth_out, height_out, width_out] = [6,16,31,13,13]
  //
  // For ConvTranspose, we use stablehlo.convolution with rhs_dilation=stride and lhs_dilation=1,
  // swapping lhs and rhs roles compared to forward conv.
  //
  // But StableHLO convolution is forward conv only.
  // To implement ConvTranspose3d, we use convolution with:
  // lhs = input
  // rhs = weight
  // rhs_dilation = stride (2,2,2)
  // padding = computed to get output shape 31x13x13
  //
  // Dimension numbers:
  // input dims: [b, f, d, h, w]
  // kernel dims: [o, i, kd, kh, kw]
  // output dims: [b, f, d, h, w]
  //
  // Here, input feature dimension is 1, kernel input feature dimension is 1,
  // kernel output feature dimension is 0, output feature dimension is 1.
  //
  // So dimension_numbers = #stablehlo.conv<[b, f, 2, 3, 4]x[o, i, 2, 3, 4]->[b, f, 2, 3, 4]>
  //
  // But weight shape is [3,16,3,3,3], so kernel dims are [i,o,kd,kh,kw].
  // We must transpose weight to [o,i,kd,kh,kw] = [16,3,3,3,3].
  //
  // So first reshape and transpose weight from [3,16,3,3,3] to [16,3,3,3,3].

  // Transpose weight from [3,16,3,3,3] to [16,3,3,3,3]
  %weight_transposed = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<3x16x3x3x3xf32>) -> tensor<16x3x3x3x3xf32>

  // Convolution parameters
  // window_strides = [1,1,1]
  // padding = [[kernel_d - 1 - padding, kernel_d - 1 - padding], ...] for ConvTranspose
  // For ConvTranspose3d with stride=2, padding=1, kernel=3:
  // output_size = (input_size - 1) * stride - 2*padding + kernel_size
  // So padding for convolution = kernel_size - 1 - padding = 3 - 1 - 1 = 1
  // So padding = [[1,1],[1,1],[1,1]]

  // rhs_dilation = stride = [2,2,2]
  // lhs_dilation = [1,1,1]

  // dimension_numbers = #stablehlo.conv<[b, f, 2, 3, 4]x[o, i, 2, 3, 4]->[b, f, 2, 3, 4]>
  // input feature dim = 1, kernel input feature dim = 1, kernel output feature dim = 0, output feature dim = 1

  %conv = "stablehlo.convolution"(%arg3, %weight_transposed) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 2, 2, 2>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3, 4]x[o, i, 2, 3, 4]->[b, f, 2, 3, 4]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x31x13x13xf32>

  // Step 2: logsumexp over dim=1 (feature dimension), keepdim=True
  // logsumexp(x) = log(sum(exp(x), dim=1))
  // Compute exp(x)
  %exp_conv = stablehlo.exponential %conv : tensor<6x16x31x13x13xf32>

  // Reduce sum over dim=1 (feature dimension)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_conv, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x16x31x13x13xf32>, tensor<f32>) -> tensor<6x1x31x13x13xf32>

  // Compute log(sum_exp)
  %log_sum_exp = stablehlo.log %sum_exp : tensor<6x1x31x13x13xf32>

  // Step 3: HardSwish(x) = x * sigmoid(x + 3) / 6
  // Compute x + 3
  %three = stablehlo.constant dense<3.0> : tensor<f32>
  %three_broadcast = "stablehlo.broadcast_in_dim"(%three) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
  // Actually, stablehlo.broadcast_in_dim requires rank match, so broadcast 3 to shape of log_sum_exp
  %three_broadcast = "stablehlo.broadcast_in_dim"(%three) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>

  // Add x + 3
  %x_plus_3 = stablehlo.add %log_sum_exp, %three_broadcast : tensor<6x1x31x13x13xf32>

  // Compute sigmoid(x + 3) = 1 / (1 + exp(-x_plus_3))
  %neg_x_plus_3 = stablehlo.negate %x_plus_3 : tensor<6x1x31x13x13xf32>
  %exp_neg = stablehlo.exponential %neg_x_plus_3 : tensor<6x1x31x13x13xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1x31x13x13xf32>
