  // stride = [1,1]
  // padding = [0,0,0,0]
  // feature_group_count = 8

  %conv = "stablehlo.convolution"(%arg4, %weight_transposed) {
    window_strides = dense<[1,1]> : tensor<2xi64>,
    padding = dense<[[0,0],[0,0]]> : tensor<2x2xi64>,
