  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %const_sqrt2 = "stablehlo.constant"() {value = dense<1.4142135623730951> : tensor<f32>} : () -> tensor<f32>
  %const_sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%const_sqrt2) {broadcast_dimensions = dense<> : tensor<0xi64>} : (tensor<f32>) -> tensor

