func.func @main(%arg0: tensor<8x8x3x3xf32>, %arg1: tensor<8xf32>, %arg2: tensor<8xf32>, %arg3: tensor<8xf32>, %arg4: tensor<8x8x8x8xf32>) -> tensor<8x8x10x10xf32> {
