  // Apply GELU elementwise
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  %sqrt2 = stablehlo.constant 1.4142135623730951 : f32
  %sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = dense<[]>} : (tensor<f32>) -> tensor<f32>
