  // %arg0: weight matrix (16x16)
  // %arg1: bias vector (16)

  // 1) Linear layer: matmul + bias
  // dot_general with batch dims = [0], contracting dims = [1]
  %0 = "stablehlo.dot_general"(%arg2, %arg0) {dot_dimension_numbers = {lhs_batching_dimensions = [0], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]}} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = [1], output_shape = dense<[16,16]> : tensor<2xi64>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %2 = "stablehlo.add"(%0, %1) : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // 2) AvgPool1d with kernel_size=16, stride=16 (default stride=kernel_size)
  // Input shape for avg_pool: (batch_size, channels=1, width=16)
  // So we need to reshape %2 from (16,16) to (16,1,16)
  %3 = "stablehlo.reshape"(%2) : (tensor<16x16xf32>) -> tensor<16x1x16xf32>

  // reduce_window with window size 16 on dimension 2, stride 16, no padding
  // This computes sum over the window, then we divide by kernel size to get average
  %4 = "stablehlo.reduce_window"(%3) ( {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {window_dimensions = dense<[1,1,16]> : tensor<3xi64>, window_strides = dense<[1,1,16]> : tensor<3xi64>, padding = dense<[[0,0],[0,0],[0,0]]> : tensor<3x2xi64>} : (tensor<16x1x16xf32>) -> tensor<16x1x1xf32>

  // divide by kernel size (16) to get average
  %c16 = "stablehlo.constant"() {value = dense<16.0> : tensor<f32>} : () -> tensor<f32>
  %5 = "stablehlo.divide"(%4, %c16) : (tensor<16x1x1xf32>, tensor<f32>) -> tensor<16x1x1xf32>

  // squeeze dimension 1 and 2: reshape (16,1,1) -> (16, )
  %6 = "stablehlo.reshape"(%5) : (tensor<16x1x1xf32>) -> tensor<16xf32>

  // 3) GELU activation: x * 0.5 * (1 + erf(x / sqrt(2)))
  // constants
  %c0_5 = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  %c1 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %c_sqrt2 = "stablehlo.constant"() {value = dense<1.4142135381698608> : tensor<f32>} : () -> tensor<f32>  // sqrt(2)

  // x / sqrt(2)
  %7 = "stablehlo.divide"(%6, %c_sqrt2) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
  // erf(x / sqrt(2))
  %8 = "stablehlo.erf"(%7) : (tensor<16xf32>) -> tensor<16xf32>
  // 1 + erf(...)
  %9 = "stablehlo.add"(%c1, %8) : (tensor<f32>, tensor<16xf32>) -> tensor<16xf32>
  // x * 0.5
  %10 = "stablehlo.multiply"(%6, %c0_5) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>
  // x * 0.5 * (1 + erf(...))
  %11 = "stablehlo.multiply"(%10, %9) : (tensor<16xf32>, tensor<16xf32>) -> tensor<16xf32>

  // 4) Multiply by scale_factor = 2.0
  %c2 = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
  %12 = "stablehlo.multiply"(%11, %c2) : (tensor<16xf32>, tensor<f32>) -> tensor<16xf32>

  // 5) torch.max(x, dim=1).values
  // Here x shape is (16,), max over dim=1 means max over the feature dimension
  // But tensor is 1D (16,), so max over dim=1 is invalid.
  // Actually, after avgpool and squeeze, shape is (16,), so max over dim=1 means max over batch dimension?
  // The original code: x = torch.max(x, dim=1).values
  // But x shape is (batch_size=16, features=16) before max, after max it is (batch_size,)
  // We must check carefully:
  // The original forward:
  // x = self.matmul(x) -> (batch_size, out_features) = (16,16)
  // x = avg_pool(x.unsqueeze(1)) -> (16,1,1)
  // squeeze(1) -> (16,1)
  // Actually, in PyTorch avg_pool1d with kernel=16 on (16,16) input with unsqueeze(1) gives (16,1,1)
  // squeeze(1) -> (16,1)
  // So x shape after avg_pool and squeeze is (16,1)
  // Then gelu and scale keep shape (16,1)
  // Then max over dim=1 gives (16,)
  // So we need to keep shape (16,1) before max, but our reshape squeezed to (16,)
  // We must fix that: after avg_pool, reshape to (16,1) not (16,)
  // Let's fix step 6 to reshape to (16,1) instead of (16,)

  // Fix: reshape %5 (16x1x1) -> (16x1)
  %6_fixed = "stablehlo.reshape"(%5) : (tensor<16x1x1xf32>) -> tensor<16x1xf32>

  // Repeat GELU steps on %6_fixed instead of %6
  %7_f = "stablehlo.divide"(%6_fixed, %c_sqrt2) : (tensor<16x1xf32>, tensor<f32>) -> tensor<16x1xf32>
  %8_f = "stablehlo.erf"(%7_f) : (tensor<16x1xf32>) -> tensor<16x1xf32>
  %9_f = "stablehlo.add"(%c1, %8_f) : (tensor<f32>, tensor<16x1xf32>) -> tensor<16x1xf32>
  %10_f = "stablehlo.multiply"(%6_fixed, %c0_5) : (tensor<16x1xf32>, tensor<f32>) -> tensor<16x1xf32>
  %11_f = "stablehlo.multiply"(%10_f, %9_f) : (tensor<16x1xf32>, tensor<16x1xf32>) -> tensor<16x1xf32>

  %12_f = "stablehlo.multiply"(%11_f, %c2) : (tensor<16x1xf32>, tensor<f32>) -> tensor<16x1xf32>

  // Now max over dim=1 (the second dimension)
  // reduce with max over dim=1
  %13 = "stablehlo.reduce"(%12_f) ( {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = "stablehlo.maximum"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%max) : (tensor<f32>) -> ()
  }) {dimensions = dense<[1]> : tensor<1xi64>} : (tensor<16x1xf32>) -> tensor<16xf32>

  return %13 : tensor<16xf32>
}

