  // constants
  %c0_5 = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  %c1 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %c_sqrt2 = "stablehlo.constant"() {value = dense<1.4142135381698608> : tensor<f32>} : () -> tensor<f32>  // sqrt(2)

  // x / sqrt(2)
  %7 = "stablehlo.divide"(%6, %c_sqrt2) : (tensor<16x1xf32>, tensor<f32>) -> tensor<16x1xf32>
  // erf(x / sqrt(2))
  %8 = "stablehlo.erf"(%7) : (tensor<16x1xf32>) -> tensor<16x1xf32>
