  %c2 = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
  %12 = "stablehlo.multiply"(%11, %c2) : (tensor<16x1xf32>, tensor<f32>) -> tensor<16x1xf32>

