func.func @main(%matmul_weight: tensor<16x16xf32>, %matmul_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16xf32> {
  // %matmul_weight: [16,16] (out_features, in_features)
  // %matmul_bias: [16] (out_features)
  // %input: [16,16] (batch_size, in_features)

  // Perform matmul: output = input @ weight^T + bias
  // weight^T shape: [16,16] -> transpose to [16,16] (same shape, but transpose dims)
  %weight_t = "stablehlo.transpose"(%matmul_weight) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  // dot_general with contracting dims: input dims 1 and weight_t dims 0
  %matmul = "stablehlo.dot_general"(%input, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // add bias: broadcast bias [16] to [16x16] on dim 1
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%matmul_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %matmul_bias_add = stablehlo.add %matmul, %bias_broadcast : tensor<16x16xf32>

  // AvgPool1d with kernel_size=16 on dim=1
  // AvgPool1d is a reduce_window with window_dimensions=[1,16], strides=[1,16], padding=0
  // input shape: [16,16], window dims: [1,16], strides: [1,16], padding: [[0,0],[0,0]]
  // init value for average pooling sum: 0.0
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_pool = "stablehlo.reduce_window"(%matmul_bias_add, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %add : tensor<f32>
  }) {window_dimensions = array<i64: 1, 16>, window_strides = array<i64: 1, 16>, padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16x1xf32>

  // Compute average by dividing by kernel size 16.0
  %kernel_size = stablehlo.constant dense<16.0> : tensor<f32>
  %kernel_size_broadcast = "stablehlo.broadcast_in_dim"(%kernel_size) {broadcast_dimensions = array<i64: 1>} : (tensor<f32>) -> tensor<16x1xf32>
  %avg_pool = stablehlo.divide %sum_pool, %kernel_size_broadcast : tensor<16x1xf32>

  // Remove dimension 1 (squeeze)
  // reshape from [16x1] to [16]
  %avg_pool_squeezed = stablehlo.reshape %avg_pool : (tensor<16x1xf32>) -> tensor<16xf32>

  // GELU activation: x * 0.5 * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %sqrt2 = stablehlo.constant dense<1.4142135381698608> : tensor<f32>  // sqrt(2)
  %sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16xf32>
  %inv_sqrt2 = stablehlo.divide (stablehlo.constant dense<1.0> : tensor<f32>), %sqrt2 : tensor<f32>
  %inv_sqrt2_broadcast = "stablehlo.broadcast_in_dim"(stablehlo.constant dense<0.7071067690849304> : tensor<f32>) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16xf32>
  // Use precomputed 1/sqrt(2) = 0.7071067690849304 for better precision
  %x_div_sqrt2 = stablehlo.multiply %avg_pool_squeezed, %inv_sqrt2_broadcast : tensor<16xf32>

  // erf(x / sqrt(2))
  %erf_val = chlo.erf %x_div_sqrt2 : tensor<16xf32> -> tensor<16xf32>

  // 1 + erf(...)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16xf32>
  %one_plus_erf = stablehlo.add %one_broadcast, %erf_val : tensor<16xf32>

  // x * 0.5 * (1 + erf(...))
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_broadcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16xf32>
  %gelu_intermediate = stablehlo.multiply %avg_pool_squeezed, %half_broadcast : tensor<16xf32>
  %gelu = stablehlo.multiply %gelu_intermediate, %one_plus_erf : tensor<16xf32>

  // Scale by scale_factor = 2.0
  %scale_factor = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_factor_broadcast = "stablehlo.broadcast_in_dim"(%scale_factor) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16xf32>
  %scaled = stablehlo.multiply %gelu, %scale_factor_broadcast : tensor<16xf32>

  // Max over dim=1 (only one dim here, so max over batch dimension 16)
  // Actually, input shape is [16], max over dim=1 is invalid, so max over dim=0 (the only dim)
  // The original code does max over dim=1 of shape [batch_size, out_features], but here output is [16] (batch_size)
  // So max over dim=1 means max over features dimension, but after avgpool and squeeze, shape is [16] (batch_size)
  // So max over dim=1 means max over features dimension, but features dimension is gone after avgpool
  // The original PyTorch code: after avgpool squeeze, shape is [batch_size, out_features] = [16,16]
  // But here avgpool output shape is [16], so we must fix avgpool to keep out_features dimension

  // Correction: The avgpool is applied on the output of matmul which is [16,16] (batch_size, out_features)
  // The avgpool is 1D with kernel size 16 on dim=1, so output shape is [16,1]
  // Then squeeze dim=1 -> [16]
  // Then gelu, scale, then max over dim=1 (features dimension) -> max over dim=1 of [16] is invalid
  // So the max is over features dimension, but after squeeze, features dimension is gone
  // So the max must be applied before squeeze

  // So redo avgpool without squeeze, keep shape [16,1]
  // Then apply gelu, scale, then max over dim=1 (dim=1 size=1), max over dim=1 returns shape [16]

  // Redo from avg_pool:
  // avg_pool shape: [16,1]
  // gelu on [16,1]
  // scale on [16,1]
  // max over dim=1 -> output [16]

  // So redo gelu and scale on [16,1]

  // GELU on [16,1]
  %x_div_sqrt2_2d = stablehlo.multiply %avg_pool, %inv_sqrt2_broadcast : tensor<16x1xf32>
  %erf_val_2d = chlo.erf %x_div_sqrt2_2d : tensor<16x1xf32> -> tensor<16x1xf32>
  %one_broadcast_2d = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16x1xf32>
