      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>
  // mean = sum / 6
  %six_f32 = stablehlo.constant dense<6.0> : tensor<f32>
  %six_bcast = "stablehlo.broadcast_in_dim"(%six_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
