func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg0: multiply_weight (16)
  // %arg1: gemm.weight (16x16)
  // %arg2: gemm.bias (16)
  // %arg3: group_norm.weight (16)
  // %arg4: group_norm.bias (16)
  // %arg5: input (16x16)

  // GEMM: x = %arg5 * %arg1^T + %arg2
  // dot_general with batch dims = [0], contracting dims = [1]
  %0 = "stablehlo.dot_general"(%arg5, %arg1) {
    lhs_batch_dims = [0],
    rhs_batch_dims = [1],
    lhs_contracting_dims = [1],
    rhs_contracting_dims = [0]
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  %1 = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %2 = stablehlo.add %0, %1 : tensor<16x16xf32>

  // GroupNorm:
  // input shape: (16,16), num_groups=16 => group size = 1
  // Reshape to (batch=16, groups=16, group_size=1)
  %3 = stablehlo.reshape %2 : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over group_size dim (dim=2)
  %4 = stablehlo.reduce %3, %cst0 = stablehlo.constant 0.0 : tensor<f32> {
    ^bb0(%argA: tensor<f32>, %argB: tensor<f32>):
      %add = stablehlo.add %argA, %argB : tensor<f32>
      stablehlo.return %add : tensor<f32>
  } : tensor<16x16x1xf32>, tensor<f32> -> tensor<16x16xf32>

  // mean = sum / group_size (1)
  %5 = stablehlo.div %4, stablehlo.constant 1.0 : tensor<16x16xf32>

  // Broadcast mean to shape (16,16,1)
  %6 = stablehlo.broadcast_in_dim %5 : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]

  // Compute variance: mean((x - mean)^2)
  %7 = stablehlo.subtract %3, %6 : tensor<16x16x1xf32>
  %8 = stablehlo.multiply %7, %7 : tensor<16x16x1xf32>

  %9 = stablehlo.reduce %8, %cst0 : tensor<f32> {
    ^bb0(%argA: tensor<f32>, %argB: tensor<f32>):
      %add = stablehlo.add %argA, %argB : tensor<f32>
      stablehlo.return %add : tensor<f32>
  } : tensor<16x16x1xf32>, tensor<f32> -> tensor<16x16xf32>

  %10 = stablehlo.div %9, stablehlo.constant 1.0 : tensor<16x16xf32>

  // Broadcast variance to (16,16,1)
  %11 = stablehlo.broadcast_in_dim %10 : tensor<16x16xf32> to tensor<16x16x1xf32> broadcast_dimensions = [0,1]

  // epsilon = 1e-5
  %eps = stablehlo.constant 1.000000e-05 : f32

  // variance + epsilon
  %12 = stablehlo.add %11, %eps : tensor<16x16x1xf32>

  // rsqrt(variance + epsilon)
  %13 = stablehlo.rsqrt %12 : tensor<16x16x1xf32>

  // Normalize: (x - mean) * rsqrt(var + eps)
  %14 = stablehlo.multiply %7, %13 : tensor<16x16x1xf32>

  // Reshape normalized back to (16,16)
  %15 = stablehlo.reshape %14 : tensor<16x16x1xf32> to tensor<16x16xf32>

  // Apply group_norm.weight and group_norm.bias
  // Broadcast weight and bias to (16,16)
  %16 = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %17 = stablehlo.multiply %15, %16 : tensor<16x16xf32>
  %18 = stablehlo.broadcast_in_dim %arg4 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %19 = stablehlo.add %17, %18 : tensor<16x16xf32>

  // Swish: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %19 : tensor<16x16xf32>
  %exp = stablehlo.exponential %neg : tensor<16x16xf32>
  %one = stablehlo.constant 1.0 : f32
  %one_tensor = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<16x16xf32> broadcast_dimensions = []
  %denom = stablehlo.add %one_tensor, %exp : tensor<16x16xf32>
  %sigmoid = stablehlo.div %one_tensor, %denom : tensor<16x16xf32>
  %20 = stablehlo.multiply %19, %sigmoid : tensor<16x16xf32>

  // Multiply by multiply_weight (broadcast multiply_weight over batch dim)
  %21 = stablehlo.broadcast_in_dim %arg0 : tensor<16xf32> to tensor<16x16xf32> broadcast_dimensions = [1]
  %22 = stablehlo.multiply %20, %21 : tensor<16x16xf32>

