  // %arg1: gemm.weight, shape [16,16]
  // %arg2: gemm.bias, shape [16]
  // %arg3: group_norm.weight, shape [16]
  // %arg4: group_norm.bias, shape [16]
  // %arg0: multiply_weight, shape [16]

  // GEMM: x @ W^T + bias
  // Transpose %arg1 from [16x16] to [16x16] swapping dims 0 and 1.
