      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias: broadcast bias [16] to [16x16] on dim 1
  %bias_bcast = stablehlo.broadcast_in_dim %arg2 {broadcast_dimensions = dense<[1]>} : tensor<16xf32> -> tensor<16x16xf32>
  %gemm_bias = stablehlo.add %gemm, %bias_bcast : tensor<16x16xf32>

  // GroupNorm:
  // Reshape to [16,16,1]
  %reshape1 = stablehlo.reshape %gemm_bias : tensor<16x16xf32> -> tensor<16x16x1xf32>

  // Compute mean over C_per_group dim=2
  %zero = stablehlo.constant 0.0 : tensor<f32>
  %mean = stablehlo.reduce %reshape1, %zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = dense<[2]>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Broadcast mean from [16,16] to [16,16,1]
  %mean_bcast = stablehlo.broadcast_in_dim %mean {broadcast_dimensions = dense<[0,1]>} : tensor<16x16xf32> -> tensor<16x16x1xf32>
  %x_centered = stablehlo.subtract %reshape1, %mean_bcast : tensor<16x16x1xf32>

