  %const_16_bcast = "stablehlo.broadcast_in_dim"(%const_16) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16xf32>
  %mean = stablehlo.divide %sum, %const_16_bcast : tensor<16xf32>

  // Broadcast mean to [16x16]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>

