  %bias_bcast = "stablehlo.broadcast_in_dim"(%group_norm_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x_scaled = stablehlo.multiply %x_norm, %weight_bcast : tensor<16x16xf32>
  %x_gn = stablehlo.add %x_scaled, %bias_bcast : tensor<16x16xf32>

  // Swish: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  %neg_x = stablehlo.negate %x_gn : tensor<16x16xf32>
  %exp_neg_x = stablehlo.exponential %neg_x : tensor<16x16xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
  %denom = stablehlo.add %one_bcast, %exp_neg_x : tensor<16x16xf32>
  %sigmoid = stablehlo.divide %one_bcast, %denom : tensor<16x16xf32>
  %x_swish = stablehlo.multiply %x_gn, %sigmoid : tensor<16x16xf32>

  // Multiply by multiply_weight (shape [16]), broadcast on dim=1
  %multiply_weight_bcast = "stablehlo.broadcast_in_dim"(%multiply_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x_mul = stablehlo.multiply %x_swish, %multiply_weight_bcast : tensor<16x16xf32>

  // Swish again: x * sigmoid(x)
  %neg_x2 = stablehlo.negate %x_mul : tensor<16x16xf32>
  %exp_neg_x2 = stablehlo.exponential %neg_x2 : tensor<16x16xf32>
  %denom2 = stablehlo.add %one_bcast, %exp_neg_x2 : tensor<16x16xf32>
  %sigmoid2 = stablehlo.divide %one_bcast, %denom2 : tensor<16x16xf32>
  %x_out = stablehlo.multiply %x_mul, %sigmoid2 : tensor<16x16xf32>

  return %x_out : tensor<16x16xf32>
}

func.func @main(%multiply_weight: tensor<16xf32>, %gemm_weight: tensor<16x16xf32>, %gemm_bias: tensor<16xf32>, %group_norm_weight: tensor<16xf32>, %group_norm_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
