  %three_b = "stablehlo.broadcast_in_dim"(%three) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %six_b = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %zero_b = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x7x4x4xf32>

  %tmp1 = stablehlo.add %conv_plus_bias, %three_b : tensor<6x7x4x4xf32>
  %tmp2 = stablehlo.maximum %tmp1, %zero_b : tensor<6x7x4x4xf32>
  %tmp3 = stablehlo.minimum %tmp2, %six_b : tensor<6x7x4x4xf32>
  %tmp4 = stablehlo.multiply %conv_plus_bias, %tmp3 : tensor<6x7x4x4xf32>
  %hardswish = stablehlo.divide %tmp4, %six_b : tensor<6x7x4x4xf32>

  // ReLU: max(x, 0)
  %relu = stablehlo.maximum %hardswish, %zero_b : tensor<6x7x4x4xf32>

  return %relu : tensor<6x7x4x4xf32>
}

