  // Compute mean over dims [2,3,4]
  %mean = stablehlo.reduce(%mul1, %c0f) ( {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = dense<array<i64:2,3,4>>} : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x16xf32>

  // mean = sum / 350
  %mean_f = stablehlo.divide %mean, %c350 : tensor<6x16xf32>

  // Broadcast mean to [6,16,14,5,5]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_f) {
    broadcast_dimensions = dense<array<i64:0,1>>
  } : (tensor<6x16xf32>) -> tensor<6x16x14x5x5xf32>

  // x_centered = x - mean
  %x_centered = stablehlo.subtract %mul1, %mean_bcast : tensor<6x16x14x5x5xf32>

  // Compute variance: mean of squared differences
  %sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x16x14x5x5xf32>
  %var_sum = stablehlo.reduce(%sq, %c0f) ( {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = dense<array<i64:2,3,4>>} : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x16xf32>

  // variance = var_sum / 350
  %var = stablehlo.divide %var_sum, %c350 : tensor<6x16xf32>

  // variance + epsilon
  %var_eps = stablehlo.add %var, %c_eps : tensor<6x16xf32>

  // stddev = sqrt(variance + epsilon)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x16xf32>

  // Broadcast stddev to [6,16,14,5,5]
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {
    broadcast_dimensions = dense<array<i64:0,1>>
  } : (tensor<6x16xf32>) -> tensor<6x16x14x5x5xf32>

  // Normalize: (x - mean) / stddev
  %norm = stablehlo.divide %x_centered, %stddev_bcast : tensor<6x16x14x5x5xf32>

  // Broadcast bias %arg2 [16] to [6,16,14,5,5]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
    broadcast_dimensions = dense<array<i64:1>>
  } : (tensor<16xf32>) -> tensor<6x16x14x5x5xf32>

  // Add bias
  %norm_bias = stablehlo.add %norm, %bias_bcast : tensor<6x16x14x5x5xf32>

  // Clamp between -1.0 and 1.0
  %clamp_min_bcast = "stablehlo.broadcast_in_dim"(%c_clamp_min) {broadcast_dimensions = dense<array<i64:>()}} : (tensor<f32>) -> tensor<f32>
  %clamp_max_bcast = "stablehlo.broadcast_in_dim"(%c_clamp_max) {broadcast_dimensions = dense<array<i64:>()}} : (tensor<f32>) -> tensor<f32>

  %clamped_min = stablehlo.maximum %norm_bias, %clamp_min_bcast : tensor<6x16x14x5x5xf32>
  %clamped = stablehlo.minimum %clamped_min, %clamp_max_bcast : tensor<6x16x14x5x5xf32>

  // Multiply again by multiplier
  %mul2 = stablehlo.multiply %clamped, %mult_bcast : tensor<6x16x14x5x5xf32>

  // Max over channel dimension (dim=1)
  %max = stablehlo.reduce(%mul2, %c_neg_inf) ( {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  }) {dimensions = dense<array<i64:1>>} : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x14x5x5xf32>

  func.return %max : tensor<6x14x5x5xf32>
}

