func.func @main(%arg0: tensor<16xf32>, %arg1: tensor<16x16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16xf32>, %arg5: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %arg5: input x, shape (16,16)
  // %arg1: matmul.weight, shape (16,16)
  // %arg0: bias (for group norm), shape (16)
  // %arg3: group_norm.weight, shape (16)
  // %arg4: group_norm.bias, shape (16)
  // %arg2: matmul.bias, shape (16) -- not used in the PyTorch code since bias is separate param

  // Step 1: matmul: x @ weight^T
  // PyTorch Linear: y = x @ weight^T + bias
  // Here weight shape is (16,16), assume it is weight matrix (out_features, in_features)
  // So to do x @ weight^T, we do dot_general with contracting dims (1) of x and (1) of weight, but weight needs to be transposed
  // But weight is (16,16), so we transpose it to (16,16) (same shape)
  // Actually, in PyTorch Linear, weight shape is (out_features, in_features)
  // Input x shape (batch, in_features)
  // Output shape (batch, out_features)
  // So dot_general contracting dims: lhs_contracting = [1], rhs_contracting = [1]
  // lhs_batching = [0], rhs_batching = [0]
  // But rhs has no batch dim, so no batching dims
  // So dot_general lhs_batching = [], rhs_batching = [], lhs_contracting = [1], rhs_contracting = [1]
  // Result shape: (16,16)

  // So we do dot_general(%arg5, %arg1) with contracting dims 1 and 1, no batching dims

  %matmul = "stablehlo.dot_general"(%arg5, %arg1) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 2: Swish activation: x * sigmoid(x)
  // sigmoid(x) = 1 / (1 + exp(-x))
  // Compute -x
  %neg = stablehlo.negate %matmul : tensor<16x16xf32>
  // exp(-x)
  %exp = stablehlo.exponential %neg : tensor<16x16xf32>
  // 1 + exp(-x)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = []} : (tensor<f32>) -> tensor<16x16xf32>
  %one_plus_exp = stablehlo.add %one_broadcast, %exp : tensor<16x16xf32>
  // reciprocal = 1 / (1 + exp(-x))
  %sigmoid = stablehlo.divide %one_broadcast, %one_plus_exp : tensor<16x16xf32>
  // swish = x * sigmoid(x)
  %swish = stablehlo.multiply %matmul, %sigmoid : tensor<16x16xf32>

  // Step 3: add bias (broadcast bias of shape (16) to (16,16))
  // %arg0 is bias of shape (16)
  // Broadcast bias to (16,16) along dimension 1
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = [1]} : (tensor<16xf32>) -> tensor<16x16xf32>
  %biased = stablehlo.add %swish, %bias_broadcast : tensor<16x16xf32>

  // Step 4: GroupNorm with num_groups=16, out_features=16
  // GroupNorm with num_groups=16 means each channel is its own group (since out_features=16)
  // Input shape: (N=16, C=16)
  // Reshape to (N=16, G=16, C_per_group=1)
  %reshape1 = stablehlo.reshape %biased : tensor<16x16xf32> to tensor<16x16x1xf32>

  // Compute mean over axis=2 (C_per_group=1), so mean is the same as the value itself
  // But we do it for generality
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%reshape1, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = [2]} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean shape: (16,16)

  // Compute variance: mean of (x - mean)^2 over axis=2
  // Broadcast mean to shape (16,16,1)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = [0,1]} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  // x - mean
  %diff = stablehlo.subtract %reshape1, %mean_broadcast : tensor<16x16x1xf32>
  // square (diff * diff)
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  // reduce mean of diff_sq over axis=2
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = [2]} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance shape: (16,16)

  // Since C_per_group=1, mean and variance are just the element itself, but we keep generality

  // Add epsilon for numerical stability
  %epsilon = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %var_eps = stablehlo.add %var, %epsilon : tensor<16x16xf32>

  // rsqrt(variance + epsilon)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // Normalize: (x - mean) * inv_std
  %normalized = stablehlo.multiply %diff, %inv_std : tensor<16x16x1xf32>

  // Reshape normalized back to (16,16)
  %normalized_reshaped = stablehlo.reshape %normalized : tensor<16x16x1xf32> to tensor<16x16xf32>

  // Apply affine transform: normalized * weight + bias
  // %arg3: group_norm.weight (16)
  // %arg4: group_norm.bias (16)
  // Broadcast weight and bias to (16,16) along dimension 1
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = [1]} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_gn_broadcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = [1]} : (tensor<16xf32>) -> tensor<16x16xf32>

  %scaled = stablehlo.multiply %normalized_reshaped, %weight_broadcast : tensor<16x16xf32>
  %out = stablehlo.add %scaled, %bias_gn_broadcast : tensor<16x16xf32>

  func.return %out : tensor<16x16xf32>
}

