func.func @main(%arg0: tensor<16x1x1x1xf32>, %arg1: tensor<16x3x3x3x3xf32>, %arg2: tensor<16xf32>, %arg3: tensor<6x3x16x7x7xf32>) -> tensor<6x14x5x5xf32> {
  // %arg0: multiplier (16x1x1x1)
  // %arg1: conv.weight (16x3x3x3x3)
  // %arg2: conv.bias (16)
  // %arg3: input (6x3x16x7x7)

  // Step 1: Convolution
  // conv3d with:
  // input: %arg3 (N=6, C_in=3, D=16, H=7, W=7)
  // filter: %arg1 (C_out=16, C_in=3, KD=3, KH=3, KW=3)
  // bias: %arg2 (16)
  // stride=1, padding=0, dilation=1, groups=1
  // output shape: (6,16,14,5,5) because:
  // D_out = (16 - 3 + 0*2)/1 + 1 = 14
  // H_out = (7 - 3 + 0*2)/1 + 1 = 5
  // W_out = (7 - 3 + 0*2)/1 + 1 = 5

  %cst_zero = stablehlo.constant 0 : index
  %cst_one = stablehlo.constant 1 : index

  %conv = stablehlo.convolution %arg3, %arg1 {
    window_strides = [1, 1, 1],
    padding = [0, 0, 0, 0, 0, 0],
    dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2, 3, 4],
      kernel_output_feature_dimension = 0,
      kernel_input_feature_dimension = 1,
      kernel_spatial_dimensions = [2, 3, 4],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2, 3, 4]
    },
    feature_group_count = 1,
    batch_group_count = 1,
    lhs_dilate = [],
    rhs_dilate = []
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x14x5x5xf32>

  // Add bias: broadcast bias (16) to (6x16x14x5x5)
  %bias_broadcast = stablehlo.broadcast_in_dim %arg2 : tensor<16xf32> to tensor<6x16x14x5x5xf32> broadcast_dimensions=[1]
  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x16x14x5x5xf32>

  // Step 2: Multiply by multiplier
  // multiplier shape: 16x1x1x1, broadcast to 6x16x14x5x5
  %mult_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<16x1x1x1xf32> to tensor<6x16x14x5x5xf32> broadcast_dimensions=[1,2,3,4]
  %mul1 = stablehlo.multiply %conv_bias, %mult_broadcast : tensor<6x16x14x5x5xf32>

  // Step 3: InstanceNorm3d
  // InstanceNorm3d normalizes per-instance per-channel over spatial dims (D,H,W)
  // For each sample n and channel c:
  // mean = reduce_mean over dims [2,3,4]
  // var = reduce_mean of (x - mean)^2 over dims [2,3,4]
  // normalized = (x - mean) / sqrt(var + eps)
  // eps = 1e-5 (typical default)
  // No affine transform (weight/bias) since not given

  %eps = stablehlo.constant 1.00000001e-5 : f32

  // Compute mean over spatial dims [2,3,4]
  %mean = stablehlo.reduce %mul1, %cst_zero {
    body {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x16xf32>
  // Divide by number of elements in spatial dims: 14*5*5=350
  %divisor = stablehlo.constant 350.0 : f32
  %mean_scaled = stablehlo.divide %mean, %divisor : tensor<6x16xf32>

  // Broadcast mean back to (6x16x14x5x5)
  %mean_broadcast = stablehlo.broadcast_in_dim %mean_scaled : tensor<6x16xf32> to tensor<6x16x14x5x5xf32> broadcast_dimensions=[0,1]

  // Compute (x - mean)
  %diff = stablehlo.subtract %mul1, %mean_broadcast : tensor<6x16x14x5x5xf32>

  // Compute squared difference
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x16x14x5x5xf32>

  // Compute variance = mean of squared difference over spatial dims
  %var = stablehlo.reduce %diff_sq, %cst_zero {
    body {
      %a = stablehlo.add %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x16xf32>
  %var_scaled = stablehlo.divide %var, %divisor : tensor<6x16xf32>

  // Add eps to variance
  %var_eps = stablehlo.add %var_scaled, %eps : tensor<6x16xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x16xf32>

  // Broadcast stddev to (6x16x14x5x5)
  %stddev_broadcast = stablehlo.broadcast_in_dim %stddev : tensor<6x16xf32> to tensor<6x16x14x5x5xf32> broadcast_dimensions=[0,1]

  // Normalize: (x - mean) / stddev
  %norm = stablehlo.divide %diff, %stddev_broadcast : tensor<6x16x14x5x5xf32>

  // Step 4: Clamp between -1.0 and 1.0
  %clamp_min = stablehlo.constant -1.0 : f32
  %clamp_max = stablehlo.constant 1.0 : f32
  %clamp_min_broadcast = stablehlo.broadcast %clamp_min : tensor<f32> to tensor<6x16x14x5x5xf32>
  %clamp_max_broadcast = stablehlo.broadcast %clamp_max : tensor<f32> to tensor<6x16x14x5x5xf32>
  %clamped_min = stablehlo.maximum %norm, %clamp_min_broadcast : tensor<6x16x14x5x5xf32>
  %clamped = stablehlo.minimum %clamped_min, %clamp_max_broadcast : tensor<6x16x14x5x5xf32>

  // Step 5: Multiply by multiplier again
  %mul2 = stablehlo.multiply %clamped, %mult_broadcast : tensor<6x16x14x5x5xf32>

  // Step 6: torch.max over dim=1 (channel dimension)
  // Reduce max over dimension 1
  %init_min = stablehlo.constant -3.4028235e+38 : f32
  %max = stablehlo.reduce %mul2, %init_min {
    body {
      %a = stablehlo.maximum %arg0, %arg1 : f32
      stablehlo.return %a : f32
    }
  } : (tensor<6x16x14x5x5xf32>, tensor<f32>) -> tensor<6x14x5x5xf32>

  // Return result
  stablehlo.return %max : tensor<6x14x5x5xf32>
}

