  // %arg0 shape: [16], broadcast on dim 1
  %bias_broadcast2 = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %swish_bias = stablehlo.add %swish, %bias_broadcast2 : tensor<16x16xf32>

  // Step 5: GroupNorm with num_groups=16, channels=16, input shape [N=16, C=16]
  // GroupNorm reshapes input to [N, G, C//G, ...] = [16,16,1]
  // Then computes mean and variance over axes [2] (the channel per group dimension)
  // Then normalizes: (x - mean) / sqrt(var + eps)
  // Then applies affine transform: * weight + bias (weight and bias shape [C=16])
  // Here, eps = 1e-5 (typical default)

  // Reshape input [16x16] -> [16x16x1]
  %swish_bias_reshaped = stablehlo.reshape %swish_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over axis 2 (C//G dimension)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_f32_bcast = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16x16x1xf32>
  %mean = "stablehlo.reduce"(%swish_bias_reshaped, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // mean shape: [16x16]

  // Compute variance: mean of squared differences
  // First compute (x - mean) broadcasted back to [16x16x1]
  // Broadcast mean from [16x16] to [16x16x1]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %diff = stablehlo.subtract %swish_bias_reshaped, %mean_bcast : tensor<16x16x1xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>

  // Compute variance = mean of diff_sq over axis 2
  %var = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // var shape: [16x16]

  // Divide var by group size (C//G = 1)
  // Since group size is 1, variance is sum over 1 element, so var is already mean

  // Add epsilon for numerical stability
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<16x16xf32>

  // Compute rsqrt(var + eps)
  %rsqrt = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // Normalize: (x - mean) * rsqrt
  %diff_bcast2 = "stablehlo.broadcast_in_dim"(%diff) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<16x16x1xf32>) -> tensor<16x16x1xf32> // redundant, keep as is
  // Actually diff is already [16x16x1], no need to broadcast again
  // Broadcast rsqrt from [16x16] to [16x16x1]
  %rsqrt_bcast = "stablehlo.broadcast_in_dim"(%rsqrt) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>
  %normalized = stablehlo.multiply %diff, %rsqrt_bcast : tensor<16x16x1xf32>

  // Reshape normalized back to [16x16]
  %normalized_reshaped = stablehlo.reshape %normalized : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply affine transform: normalized * weight + bias
  // weight and bias shape: [16], broadcast on dim 1
  %weight_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_gn_bcast = "stablehlo.broadcast_in_dim"(%arg4) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %normalized_reshaped, %weight_bcast : tensor<16x16xf32>
  %out = stablehlo.add %scaled,

