func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x6x2x2xf32> {
  // Convolution parameters
  // input: %arg2 shape [6,7,6,6]
  // weight: %arg0 shape [6,7,3,3]
  // bias: %arg1 shape [6]
  // conv dimension numbers: input [b, f, h, w], kernel [o, i, kh, kw], output [b, f, h, w]
  // PyTorch Conv2d default stride=1, padding=0, dilation=1, groups=1
  // We want output shape [6,6,4,4] after conv (6 batch, 6 out_channels, 4x4 spatial)
  // But input spatial 6x6, kernel 3x3, stride 1, padding 0 => output spatial = 6-3+1=4
  // So output shape after conv is [6,6,4,4]

  // Perform convolution
  %conv = stablehlo.convolution %arg2, %arg0 {
    window_strides = [1, 1],
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = [1, 1],
    rhs_dilation = [1, 1],
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Add bias: broadcast bias from [6] to [6,6,4,4] on feature dim
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1 : tensor<6xf32> to tensor<6x6x4x4xf32> dimensions = [1]

  %conv_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x6x4x4xf32>

  // Subtract 0.5 (subtract1_value)
  %cst_0_5 = stablehlo.constant 0.5 : tensor<f32>
  %cst_0_5_broadcast = stablehlo.broadcast_in_dim %cst_0_5 : tensor<f32> to tensor<6x6x4x4xf32> dimensions = []

  %sub1 = stablehlo.subtract %conv_bias, %cst_0_5_broadcast : tensor<6x6x4x4xf32>

  // Apply tanh
  %tanh = stablehlo.tanh %sub1 : tensor<6x6x4x4xf32>

  // Subtract 0.2 (subtract2_value)
  %cst_0_2 = stablehlo.constant 0.2 : tensor<f32>
  %cst_0_2_broadcast = stablehlo.broadcast_in_dim %cst_0_2 : tensor<f32> to tensor<6x6x4x4xf32> dimensions = []

  %sub2 = stablehlo.subtract %tanh, %cst_0_2_broadcast : tensor<6x6x4x4xf32>

  // Average Pooling with kernel_size_pool=2, stride=2 (default for AvgPool2d)
  // AvgPool2d kernel=2, stride=2, no padding
  // Output spatial dims: floor((4 - 2)/2 + 1) = 2
  // So output shape: [6,6,2,2]

  // We implement average pooling as reduce_window with sum and then divide by window size (4)
  %init = stablehlo.constant 0.0 : tensor<f32>

  %sum_pool = stablehlo.reduce_window %sub2, %init {
