  // So output shape after conv is [6,6,4,4]

  // stablehlo.convolution expects dimension_numbers attribute:
  // dimension_numbers = #stablehlo.conv<[b, i, h, w]x[o, i, kh, kw]->[b, o, h, w]>
  // But input is [b, f, h, w] with f=input channels, kernel [o, i, kh, kw]
  // So dimension_numbers = [b, f, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]

  // Define dimension numbers attribute
