  // input: [b, f, h, w] = [0,1,2,3]
  // kernel: [o, i, kh, kw] = [0,1,2,3]
  // output: [b, o, h, w] = [0,1,2,3]
  // So dimension_numbers = #stablehlo.conv<[0,1,2,3]x[0,1,2,3]->[0,1,2,3]>
  // This matches the default.

  // Convolution with stride=1, padding=0, dilation=1
