  %cst_0_5_tensor = stablehlo.broadcast_in_dim %cst_0_5 : tensor<f32> to tensor<6x6x4x4xf32> broadcast_dimensions = []

  %sub1 = stablehlo.subtract %conv_bias, %cst_0_5_tensor : tensor<6x6x4x4xf32>

  // Apply tanh
  %tanh = stablehlo.tanh %sub1 : tensor<6x6x4x4xf32>

  // Subtract 0.2 (subtract2_value)
  %cst_0_2 = stablehlo.constant 0.2 : f32
  %cst_0_2_tensor = stablehlo.broadcast_in_dim %cst_0_2 : tensor<f32> to tensor<6x6x4x4xf32> broadcast_dimensions = []

  %sub2 = stablehlo.subtract %tanh, %cst_0_2_tensor : tensor<6x6x4x4xf32>

