  %hardswish = stablehlo.divide %mul, %cst_6_broadcast : tensor<6x6x4x4xf32>

  // MaxPool2d with kernel size 2, stride 2, no padding
  // Using reduce_window max with window dims [1, 1, 2, 2] on hardswish output (6x6x4x4)
  %maxpool = stablehlo.reduce_window %hardswish {
    window_dimensions = [1, 1, 2, 2],
    window_strides = [1, 1, 2, 2],
