  %log = stablehlo.log %exp_plus_one : tensor<6x6x2x2xf32>
  %tanh = stablehlo.tanh %log : tensor<6x6x2x2xf32>
  %mish = stablehlo.multiply %maxpool, %tanh : tensor<6x6x2x2xf32>

  stablehlo.return %mish : tensor<6x6x2x2xf32>
}

