func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x6x2x2xf32> {
  // Convolution parameters:
  // input: %arg2 (N=6, C=7, H=6, W=6)
  // filter: %arg0 (O=6, I=7, KH=3, KW=3)
  // bias: %arg1 (O=6)
  // stride=1, padding=0, dilation=1, groups=1
  // dimension_numbers: input [N, C, H, W], kernel [O, I, KH, KW], output [N, O, H_out, W_out]
  // output shape: N=6, O=6, H_out=6-3+1=4, W_out=6-3+1=4 (but we want 6x6 output, so we need padding)
  // The PyTorch Conv2d default padding=0, so output spatial dims = (6-3+1)=4
  // But the task output shape is 6x6x2x2, so the final output shape is 6x6x2x2
  // The conv output shape is 6x6x4x4 (N=6, O=6, H=4, W=4)
  // The maxpool with kernel=2 reduces 4x4 to 2x2
  // So the output shape matches 6x6x2x2

  // So the conv output shape is 6x6x4x4, which matches the conv output shape.

  // We will do convolution with no padding, stride=1.

  // Step 1: convolution
  %conv = stablehlo.convolution %arg2, %arg0 {
    window_strides = dense<1, 1> : tensor<2xi64>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = dense<1, 1> : tensor<2xi64>,
    rhs_dilation = dense<1, 1> : tensor<2xi64>,
    dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Step 2: subtract 0.5 (broadcasted)
  %cst_sub = stablehlo.constant 0.5 : tensor<f32>
  %cst_sub_broadcast = stablehlo.broadcast_in_dim %cst_sub : tensor<f32> to tensor<6x6x4x4xf32> broadcast_dimensions = [] : tensor<0xi64>

  %sub = stablehlo.subtract %conv, %cst_sub_broadcast : tensor<6x6x4x4xf32>

  // Step 3: HardSwish activation
  // HardSwish(x) = x * relu6(x + 3) / 6
  // relu6(x) = min(max(x, 0), 6)

  %three = stablehlo.constant 3.0 : tensor<f32>
  %six = stablehlo.constant 6.0 : tensor<f32>
  %six_broadcast = stablehlo.broadcast_in_dim %six : tensor<f32> to tensor<6x6x4x4xf32> broadcast_dimensions = [] : tensor<0xi64>
  %zero = stablehlo.constant 0.0 : tensor<f32>
  %zero_broadcast = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<6x6x4x4xf32> broadcast_dimensions = [] : tensor<0xi64>

  %add3 = stablehlo.add %sub, %three : tensor<6x6x4x4xf32>
  %max0 = stablehlo.maximum %add3, %zero_broadcast : tensor<6x6x4x4xf32>
  %min6 = stablehlo.minimum %max0, %six_broadcast : tensor<6x6x4x4xf32>
  %div6 = stablehlo.divide %min6, %six_broadcast : tensor<6x6x4x4xf32>
  %hardswish = stablehlo.multiply %sub, %div6 : tensor<6x6x4x4xf32>

  // Step 4: MaxPool2d with kernel=2, stride=2, no padding
  // Use reduce_window with maximum
  %init = stablehlo.constant -3.4028235e+38 : tensor<f32>  // smallest float32
  %init_broadcast = stablehlo.broadcast_in_dim %init : tensor<f32> to tensor<6x6x4x4xf32> broadcast_dimensions = [] : tensor<0xi64>

  %maxpool = stablehlo.reduce_window %hardswish, %init_broadcast {
    window_dimensions = dense<1, 1, 2, 2> : tensor<4xi64>,
    window_strides = dense<1, 1, 2, 2> : tensor<4xi64>,
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %max : tensor<f32>
  }) : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6x2x2xf32>

  // Step 5: Mish activation
  // Mish(x) = x * tanh(softplus(x))
  // softplus(x) = log(1 + exp(x))

  %exp = stablehlo.exponential %maxpool : tensor<6x6x2x2xf32>
  %one = stablehlo.constant 1.0 : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<6x6x2x2xf32> broadcast_dimensions = [] : tensor<0xi64>
  %exp_plus_one = stablehlo.add %exp, %one_broadcast : tensor<6x6x2x2xf32>
  %softplus = stablehlo.log %exp_plus_one : tensor<6x6x2x2xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x6x2x2xf32>
  %mish = stablehlo.multiply %maxpool, %tanh_softplus : tensor<6x6x2x2xf32>

  // Return result
  func.return %mish : tensor<6x6x2x2xf32>
}

