  } : (tensor<6x6x6x6xf32>, tensor<f32>) -> tensor<6x6x3x3xf32>

  // Mish activation: x * tanh(softplus(x)) = x * tanh(log(1 + exp(x)))
  %exp_x = stablehlo.exponential %maxpool : tensor<6x6x3x3xf32>
