  %const_6 = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
  %const_6_broadcast = "stablehlo.broadcast_in_dim"(%const_6) {
    broadcast_dimensions = dense<> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %relu6 = "stablehlo.minimum"(%max_x_plus_3_0, %const_6

