  } : (tensor<6x1x1x1xf32>) -> tensor<6x6x4x4xf32>

  // Add bias
  %conv_plus_bias = "stablehlo.add"(%conv, %bias_broadcast) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

