  %const_0_5 = "stablehlo.constant"() {value = dense<0.5> : tensor<f32>} : () -> tensor<f32>
  %sub_broadcast = "stablehlo.broadcast_in_dim"(%const_0_5) {
    broadcast_dimensions = dense<> : tensor<0xi64>
  } : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %subtracted = "stablehlo.subtract"(%conv_plus_bias, %sub_broadcast) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

  // HardSwish: x * relu6(x + 3) / 6
  // relu6(x) = min(max(x, 0), 6)
  %const_3 = "stablehlo.constant"() {value = dense<3.0> : tensor<f32>} : () -> tensor<f32>
  %const_3_broadcast = "stablehlo.broadcast_in_dim"(%const_3) {
