  } : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %x_plus_3 = "stablehlo.add"(%subtracted, %const_3_broadcast) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

  %const_0 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %const_0_broadcast = "stablehlo.broadcast_in_dim"(%const_0) {
    broadcast_dimensions = dense<> : tensor<0xi64>
