  } : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %relu6 = "stablehlo.minimum"(%max_x_plus_3_0, %const_6_broadcast) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

  %mul = "stablehlo.multiply"(%subtracted, %relu6) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

  %const_6_div = "stablehlo.constant"() {value = dense<6.0> : tensor<f32>} : () -> tensor<f32>
  %const_6_div_broadcast = "stablehlo.broadcast_in_dim"(%const_6_div) {
