    window_strides = dense<1, 1, 2, 2> : tensor<4xi64>,
    padding = dense<0, 0, 0, 0, 0, 0, 0, 0> : tensor<4x2xi64>,
    base_dilation = dense<1, 1, 1, 1> : tensor<4xi64>,
    window_dilation = dense<1, 1, 1, 1> : tensor<4xi64>,
    computation = "stablehlo.maximum"
  } : (tensor<6x6x4x4xf32>) -> tensor<6x6x2x2xf32>

  // Mish activation: x * tanh(softplus(x)) where softplus(x) = log(1 + exp(x))
  // Compute softplus(maxpool)
  %exp = "stablehlo.exponential"(%maxpool) : (tensor<6x6x2x2xf32>) -> tensor<6x6x2x2xf32>
