  // mean = reduce mean over batch dimension (dim 0)
  // var = reduce variance over batch dimension (dim 0)
  // eps = 1e-5 (typical default)
  // weight and bias are batch_norm.weight and batch_norm.bias

  // Compute mean over batch dim 0: shape (7)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%gemm_out, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // mean = sum / 6
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_bcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean_div = stablehlo.divide %mean, %six_bcast : tensor<7xf32>

