  %bias_bn_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %batch_norm_out = stablehlo.add %scaled, %bias_bn_bcast : tensor<6x7xf32>

