  // x * gelu_factor
  %gelu_out = stablehlo.multiply %batch_norm_out, %gelu_factor : tensor<6x7xf32>

  // ReLU: max(0, x)
  %zero_bcast = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast_6x7 = "stablehlo.broadcast_in_dim"(%zero_bcast) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x7xf32>
  %relu_out = stablehlo.maximum %gelu_out, %zero_bcast_6x7 : tensor<6x7xf32>

  "stablehlo.return"(%relu_out) : tensor<6x7xf32>
}

