func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0: gemm.weight (7x7)
  // %arg1: gemm.bias (7)
  // %arg2: batch_norm.weight (7)
  // %arg3: batch_norm.bias (7)
  // %arg4: input (6x7)

  // GEMM: x = %arg4 * %arg0^T + %arg1
  // We want to do: output = x @ W^T + b
  // %arg0 is weight of shape (7x7) (out_features x in_features)
  // Input shape: (6x7)
  // So we do dot_general with contracting dims: input dim 1 and weight dim 1
  // But weight is (7x7), we want to multiply input (6x7) by weight^T (7x7)
  // So we transpose weight to (7x7) (same shape), but we want to contract input dim 1 with weight dim 0
  // So dot_general lhs_batching_dims = [0] (batch), lhs_contracting_dims = [1]
  // rhs_batching_dims = [], rhs_contracting_dims = [0]
  // Result shape: (6x7)

  %0 = stablehlo.transpose %arg0 {permutation = dense<[1, 0]>} : tensor<7x7xf32> -> tensor<7x7xf32>
  %1 = stablehlo.dot_general %arg4, %0 {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
