  // Broadcast bias to (6x7)
  %2 = stablehlo.broadcast_in_dim %arg1 : tensor<7xf32> to tensor<6x7xf32> {broadcast_dimensions = dense<[1]>}
  %3 = stablehlo.add %1, %2 : tensor<6x7xf32>

  // BatchNorm1d in training mode:
  // y = weight * (x - mean) / sqrt(var + eps) + bias
  // mean and var computed per feature (dim 0 is batch)
  // Compute mean over batch dim 0: reduce over dim 0 with add, then divide by batch_size=6

  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c6 = stablehlo.constant dense<6.0> : tensor<f32>

  // Reduce sum over dim 0 (batch) to get sum per feature (7)
  %4 = stablehlo.reduce %3, %c0 {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = dense<[0]>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

