  %5 = stablehlo.divide %4, %c6 : tensor<7xf32>

  // Broadcast mean to (6x7)
  %6 = stablehlo.broadcast_in_dim %5 : tensor<7xf32> to tensor<6x7xf32> {broadcast_dimensions = dense<[1]>}

  // x_centered = x - mean
  %7 = stablehlo.subtract %3, %6 : tensor<6x7xf32>

  // Compute variance: mean of squared differences
  %8 = stablehlo.multiply %7, %7 : tensor<6x7xf32>

  // Reduce sum of squared diffs over batch dim 0
  %9 = stablehlo.reduce %8, %c0 {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = dense<[0]>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // variance = sum / 6
  %10 = stablehlo.divide %9, %c6 : tensor<7xf32>

  // Broadcast variance to (6x7)
  %11 = stablehlo.broadcast_in_dim %10 : tensor<7xf32> to tensor<6x7xf32> {broadcast_dimensions = dense<[1]>}

