  // batch_norm(x) = (x - mean) / sqrt(var + eps) * weight + bias
  // mean and var computed over batch dimension (dim 0) for each feature (dim 1)
  // eps = 1e-5 (typical default)
  // weight and bias are %arg2 and %arg3 respectively (both shape 7)

  // Compute mean over dim 0 (batch)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<7xf32>
