  %inv_std_bcast_reshaped = "stablehlo.broadcast_in_dim"(%inv_std_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %x_norm = stablehlo.multiply %x_centered, %inv_std_bcast_reshaped : tensor<6x7x4x4xf32>

