  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 0} : (tensor<7xf32>) -> tensor<7xf32>
  %bn_weight_bcast_reshaped = "stablehlo.broadcast_in_dim"(%bn_weight_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
