  // %arg1: gemm.bias (7)
  // %arg2: input (6x7)

  // Compute gemm: x @ W^T + b
  // %arg0 is weight (out_features x in_features) = 7x7
  // %arg2 is input (batch_size x in_features) = 6x7
  // We want: (6x7) @ (7x7)^T = (6x7) @ (7x7) = (6x7)
  // So dot_general with contracting dims: input dim 1 and weight dim 1
  // But weight is 7x7, we want to contract input dim 1 with weight dim 1 (the second dim)
  // Actually, weight is (out_features x in_features) = (7x7)
  // We want to do input (6x7) @ weight^T (7x7) = (6x7)
  // So dot_general contracting input dim 1 and weight dim 0 (to do input * weight^T)
  // So contract input dim 1 and weight dim 0, batch dims none
  // Result shape: (6x7)

  %0 = "stablehlo.dot_general"(%arg2, %arg0) {
    lhs_batching_dimensions = [],
    rhs_batching_dimensions = [],
    lhs_contracting_dimensions = [1],
    rhs_contracting_dimensions = [0]
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

