  %5 = stablehlo.reduce %4, %cst_0 : tensor<6x1xf32>, tensor<f32> {
    dimensions = [1],
    body = {
      %a = stablehlo.parameter 0 : tensor<f32>
      %b = stablehlo.parameter 1 : tensor<f32>
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
    }
