  // %arg1: conv.bias: [7]
  // %arg2: input: [batch=6, in_channels=6, height=8, width=8]

  // Perform convolution
  // convolution expects input NHWC or NCHW? StableHLO convolution expects input in NCHW format by default.
  // Our input is [6,6,8,8] (N,C,H,W)
  // weight is [7,6,3,3] (O,I,H,W)
  // We want output shape: [6,7,6,6] (N,O,H_out,W_out)
  // Stride=1, padding=0, dilation=1, feature_group_count=1

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
