  %bias_broadcast_reshaped = "stablehlo.broadcast_in_dim"(%bias_broadcast) {
    broadcast_dimensions = array<i64: 0, 1, 2, 3>
  } : (tensor<1x7x1x1xf32>) -> tensor<6x7x6x6xf32>

