  %softplus1 = "stablehlo.log"(%exp1_plus_one) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %tanh1 = "stablehlo.tanh"(%softplus1) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %mish1 = "stablehlo.multiply"(%conv_bias, %tanh1) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

