  %exp2 = "stablehlo.exponential"(%mish1) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %exp2_plus_one = "stablehlo.add"(%exp2, %one_broadcast) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %softplus2 = "stablehlo.log"(%exp2_plus_one) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %tanh2 = "stablehlo.tanh"(%softplus2) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>
  %mish2 = "stablehlo.multiply"(%mish1, %tanh2) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  return %mish2 : tensor<6x7x6x6xf32>
}

