func.func @main(%bias: tensor<1xf32>, %weight: tensor<7x7xf32>, %matmul_bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
