func.func @main(%arg0: tensor<1xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = bias (tensor<1xf32>)
  // %arg1 = matmul.weight (tensor<7x7xf32>)
  // %arg2 = matmul.bias (tensor<7xf32>)
  // %arg3 = bn.weight (tensor<7xf32>)
  // %arg4 = bn.bias (tensor<7xf32>)
  // %arg5 = input (tensor<6x7xf32>)

  // Step 1: matmul: x = %arg5 * %arg1^T + %arg2
  // Note: PyTorch Linear does x*W^T + b, so we do dot_general with contracting dims [1] and [1] but transpose weight first.
  // But weight shape is (7x7), so we can do dot_general with lhs: (6x7), rhs: (7x7), contracting dims: lhs=1, rhs=0
  // Result shape: (6x7)
  %matmul = "stablehlo.dot_general"(%arg5, %arg1) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

