  %bias_broadcast_6 = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = [0,1]} : tensor<1x7xf32> -> tensor<6x7xf32>
  %matmul_bias = stablehlo.add %matmul, %bias_broadcast_6 : tensor<6x7xf32>

  // Step 2: BatchNorm1d forward (training mode)
  // BatchNorm1d formula (training):
  // mean = reduce_mean(x, dim=0)
  // var = reduce_mean((x - mean)^2, dim=0)
  // x_norm = (x - mean) / sqrt(var + eps)
  // y = weight * x_norm + bias

  // Compute mean over batch dim 0: reduce sum then divide by 6
  %zero = stablehlo.constant 0.0 : f32
  %init_mean = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = []} : tensor<f32> -> tensor<f32>
  %sum = stablehlo.reduce(%matmul_bias, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  }) {dimensions = [0]} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<7xf32>

  // Divide sum by 6 to get mean
  %six = stablehlo.constant 6.0 : f32
  %six_broadcast = stablehlo.broadcast_in_dim %six {broadcast_dimensions = []} : tensor<f32> -> tensor<f32>
  %mean = stablehlo.divide %sum, %six_broadcast : tensor<7xf32>

  // Broadcast mean to shape (6x7)
  %mean_broadcast = stablehlo.broadcast_in_dim %mean {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<1x7xf32>
  %mean_broadcast_6 = stablehlo.broadcast_in_dim %mean_broadcast {broadcast_dimensions = [0,1]} : tensor<1x7xf32> -> tensor<6x7xf32>

  // Compute (x - mean)
  %x_centered = stablehlo.subtract %matmul_bias, %mean_broadcast_6 : tensor<6x7xf32>

  // Compute squared difference (x - mean)^2
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x7xf32>

  // Compute variance: reduce mean of squared difference over batch dim 0
  %init_var = stablehlo.broadcast_in_dim %zero {broadcast_dimensions = []} : tensor<f32> -> tensor<f32>
