  %stddev_broadcast = stablehlo.broadcast_in_dim %stddev {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<1x7xf32>
  %stddev_broadcast_6 = stablehlo.broadcast_in_dim %stddev_broadcast {broadcast_dimensions = [0,1]} : tensor<1x7xf32> -> tensor<6x7xf32>

  // Normalize: x_norm = (x - mean) / stddev
  %x_norm = stablehlo.divide %x_centered, %stddev_broadcast_6 : tensor<6x7xf32>

