  %bn_weight_broadcast = stablehlo.broadcast_in_dim %arg3 {broadcast_dimensions = [1]} : tensor<7xf32> -> tensor<1x7xf32>
  %bn_weight_broadcast_6 = stablehlo.broadcast_in_dim %bn_weight_broadcast {broadcast_dimensions = [0,1]} : tensor<1x7xf32> -> tensor<6x7xf32>
