  %bn_out = stablehlo.add %bn_scaled, %bn_bias_broadcast_6 : tensor<6x7xf32>

  // Step 3: Add bias (parameter %arg0, shape 1xf32) broadcasted to (6x7)
  %bias_broadcast_1 = stablehlo.broadcast_in_dim %arg0 {broadcast_dimensions = [1]} : tensor<1xf32> -> tensor<1x1xf32>
  %bias_broadcast_6x7 = stablehlo.broadcast_in_dim %bias_broadcast_1 {broadcast_dimensions = [0,1]} : tensor<1x1xf32> -> tensor<6x7xf32>
  %add_bias = stablehlo.add %bn_out, %bias_broadcast_6x7 : tensor<6x7xf32>

  // Step 4: Divide by divide_value = 1.0 (no-op, but do it for correctness)
  %div_val = stablehlo.constant 1.0 : f32
  %div_val_broadcast = stablehlo.broadcast_in_dim %div_val {broadcast_dimensions = []} : tensor<f32> -> tensor<f32>
  %div_val_broadcast_6x7 = stablehlo.broadcast_in_dim %div_val_broadcast {broadcast_dimensions = []} : tensor<f32> -> tensor<f32>
  // Actually broadcast to 6x7
  %div_val_broadcast_6x7 = stablehlo.broadcast_in_dim %div_val {broadcast_dimensions = []} : tensor<f32> -> tensor<f32>
  %div_val_broadcast_6x7 = stablehlo.broadcast_in_dim %div_val {broadcast_dimensions = []} : tensor<f32> -> tensor<f32>

