  // Broadcast seven_f to [6]
  %seven_f_bcast = "stablehlo.broadcast_in_dim"(%seven_f) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6xf32>
  // Divide sum by 7 to get mean
  %mean = stablehlo.divide %sum, %seven_f_bcast : tensor<6xf32>
