  // sum over dim=1 (which is size 1)
  %init_sum2 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum2 = "stablehlo.reduce"(%exp, %init_sum2) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add2 = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add2) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x1xf32>, tensor<f32>) -> tensor<6xf32>
  // Broadcast sum2 to [6x1]
