  // log
  %logsumexp = stablehlo.log %sum2_bcast : tensor<6x1xf32>

  // GELU on logsumexp
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // constants
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>  // sqrt(2)
  // Broadcast constants to [6x1]
  %half_bcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %sqrt2_bcast = "stablehlo.broadcast_in_dim"(%sqrt2) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
