func.func @main(%subtract: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Save original input for residual add
  %original_x = %input : tensor<6x7xf32>

  // GEMM: x = input @ weight^T + bias
  // weight shape: [7,7], we want to do input [6x7] * weight^T [7x7] -> [6x7]
  // So contract input dim 1 with weight dim 1, batch dims none
  %dot = "stablehlo.dot_general"(%input, %weight) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: bias shape [7], broadcast to [6x7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // Subtract: x = x - subtract
  // subtract shape [7], broadcast to [6x7]
  %subtract_broadcast = "stablehlo.broadcast_in_dim"(%subtract) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_sub = stablehlo.subtract %x, %subtract_broadcast : tensor<6x7xf32>

  // GlobalAvgPool: mean over dim=1, keepdim=True
  // mean = sum / size
  // sum over dim=1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%x_sub, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>

  // Convert sum shape [6] to [6x1] to divide
  %sum_reshape = "stablehlo.broadcast_in_dim"(%sum) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // Divide by 7 (size of dim 1)
  %seven = stablehlo.constant dense<7.0> : tensor<f32>
  %seven_broadcast = "stablehlo.broadcast_in_dim"(%seven) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<1xf32>
  %seven_6x1 = "stablehlo.broadcast_in_dim"(%seven_broadcast) {broadcast_dimensions = array<i64: 1>} : (tensor<1xf32>) -> tensor<6x1xf32>
  %mean = stablehlo.divide %sum_reshape, %seven_6x1 : tensor<6x1xf32>

  // LogSumExp over dim=1, keepdim=True
  // Input shape is [6x1], so logsumexp over dim=1 is just log(exp(x)) = x itself
  // But to follow the pattern, we do it explicitly:

  // max over dim=1 for numerical stability
  %neg_inf = stablehlo.constant dense<0xFF800000> : tensor<f32>  // -inf
  %max = "stablehlo.reduce"(%x_sub, %neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<6xf32>
  %max_reshape = "stablehlo.broadcast_in_dim"(%max) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1xf32>

  // subtract max for numerical stability
  %x_sub_max = stablehlo.subtract %x_sub, %max_reshape : tensor<6x7xf32>

  // exp(x - max)
  %exp = stablehlo.exponential %x_sub_max : tensor<6x7xf32>

  // sum exp over dim=1
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
