  %half_broadcast = "stablehlo.broadcast_in_dim"(%half) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<1xf32>
  %half_6x1 = "stablehlo.broadcast_in_dim"(%half_broadcast) {broadcast_dimensions = array<i64: 1>} : (tensor<1xf32>) -> tensor<6x1xf32>

  %gelu = stablehlo.multiply %half_6x1, %logsumexp : tensor<6x1xf32>
  %gelu = stablehlo.multiply %gelu, %one_plus_erf : tensor<6x1xf32>

  // Residual add: x = gelu + original_x
  // gelu shape [6x1], original_x shape [6x7], broadcast gelu to [6x7]
  %gelu_broadcast = "stablehlo.broadcast_in_dim"(%gelu) {broadcast_dimensions = array<i64: 0>} : (tensor<6x1xf32>) -> tensor<6x7xf32>
  %residual = stablehlo.add %gelu_broadcast, %original_x : tensor<6x7xf32>

  return %residual : tensor<6x7xf32>
}

