func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg0 = add_value (tensor<7xf32>)
  // %arg1 = matmul.weight (tensor<7x7xf32>)
  // %arg2 = matmul.bias (tensor<7xf32>)
  // %arg3 = input x (tensor<6x7xf32>)

  // Perform matmul: x @ weight^T
  // matmul.weight shape: [7,7], input shape: [6,7]
  // We want to do dot_general with contracting dims: input dim 1 and weight dim 1 (weight second dim)
  // But weight is [7x7], we want to multiply input [6x7] with weight^T [7x7]^T = [7x7]
  // So we transpose weight to get [7x7] -> [7x7] (actually symmetric shape, but we must transpose)
  %weight_t = "stablehlo.transpose"(%arg1) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

  // dot_general: lhs = %arg3 (6x7), rhs = %weight_t (7x7)
  // Contract lhs dim 1 with rhs dim 0
  %matmul = "stablehlo.dot_general"(%arg3, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: %arg2 shape [7], broadcast to [6x7]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %matmul_bias = stablehlo.add %matmul, %bias_broadcast : tensor<6x7xf32>

  // Add add_value: %arg0 shape [7], broadcast to [6x7]
  %add_value_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x_add = stablehlo.add %matmul_bias, %add_value_broadcast : tensor<6x7xf32>

  // Swish: x * sigmoid(x)
  // sigmoid(x) = logistic(x)
  %sigmoid = stablehlo.math.logistic %x_add : tensor<6x7xf32>
  %swish = stablehlo.multiply %x_add, %sigmoid : tensor<6x7xf32>

  // Tanh
  %tanh = stablehlo.math.tanh %swish : tensor<6x7xf32>

  // GELU: x * 0.5 * (1 + erf(x / sqrt(2)))
  // Compute x / sqrt(2)
  %const_sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>
  %const_sqrt2_broadcast = "stablehlo.broadcast_in_dim"(%const_sqrt2) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<1xf32>
  // Broadcast to [6x7]
  %const_sqrt2_6x7 = "stablehlo.broadcast_in_dim"(%const_sqrt2) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>
  // Actually simpler: just constant scalar and divide tensor by scalar
  %inv_sqrt2 = stablehlo.divide %tanh, %const_sqrt2_6x7 : tensor<6x7xf32>

  // Compute erf(x / sqrt(2))
  %erf = "chlo.erf"(%inv_sqrt2) : (tensor<6x7xf32>) -> tensor<6x7xf32>

  // Compute 1 + erf(...)
  %const_one = stablehlo.constant dense<1.0> : tensor<f32>
  %const_one_6x7 = "stablehlo.broadcast_in_dim"(%const_one) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>
  %one_plus_erf = stablehlo.add %const_one_6x7, %erf : tensor<6x7xf32>

  // Multiply by 0.5
  %const_half = stablehlo.constant dense<0.5> : tensor<f32>
  %const_half_6x7 = "stablehlo.broadcast_in_dim"(%const_half) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>
  %half_times = stablehlo.multiply %const_half_6x7, %one_plus_erf : tensor<6x7xf32>

  // GELU output: x * 0.5 * (1 + erf(x / sqrt(2)))
  %gelu = stablehlo.multiply %tanh, %half_times : tensor<6x7xf32>

  // Hardtanh with min_val=-1, max_val=1
  %const_min = stablehlo.constant dense<-1.0> : tensor<f32>
  %const_min_6x7 = "stablehlo.broadcast_in_dim"(%const_min) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>
  %const_max = stablehlo.constant dense<1.0> : tensor<f32>
  %const_max_6x7 = "stablehlo.broadcast_in_dim"(%const_max) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<6x7xf32>

  // clamp: max(min(x, max_val), min_val)
  %min_clamped = stablehlo.minimum %gelu, %const_max_6x7 : tensor<6x7xf32>
  %hardtanh = stablehlo.maximum %min_clamped, %const_min_6x7 : tensor<6x7xf32>

  return %hardtanh : tensor<6x7xf32>
}

