    dimension_numbers = {input_batch_dimension = 0 : i64, input_feature_dimension = 1 : i64, input_spatial_dimensions = [2, 3] : array<i64, 2>, kernel_output_feature_dimension = 0 : i64, kernel_input_feature_dimension = 1 : i64, kernel_spatial_dimensions = [2, 3] : array<i64, 2>, output_batch_dimension = 0 : i64, output_feature_dimension = 1 : i64, output_spatial_dimensions = [2, 3] : array<i64, 2>},
