func.func @main(%bias: tensor<16x1x1xf32>, %scale: tensor<16x1x1xf32>, %conv_weight: tensor<16x8x3x3xf32>, %conv_bias: tensor<16xf32>, %gn_weight: tensor<16xf32>, %gn_bias: tensor<16xf32>, %input: tensor<16x8x16x16xf32>) -> tensor<16x16x14x14xf32> {
  // conv: conv2d with stride=1, padding=0, no dilation, dimension_numbers [NCHW]x[OIHW]->[NCHW]
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<16x8x16x16xf32>, tensor<16x8x3x3xf32>) -> tensor<16x16x14x14xf32>

  // Add bias: broadcast bias from [16x1x1] to [16x16x14x14]
  // bias shape: [16x1x1], conv output shape: [16x16x14x14]
  // broadcast bias on dims: batch=0, channel=1, height=2, width=3
  // bias has dims: [C, 1, 1], conv output dims: [N, C, H, W]
  // Need to broadcast bias to [N, C, H, W], so broadcast dims = [1, 0, 2, 3] is invalid because bias has no batch dim
  // Actually bias is [16x1x1], so batch dim is missing, so we broadcast bias on dims [1, 2, 3] with batch dim 0 in conv output
  // So broadcast dims = array<i64: 1, 2, 3>
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<16x1x1xf32>) -> tensor<16x16x14x14xf32>
  %add_bias = stablehlo.add %conv, %bias_bcast : tensor<16x16x14x14xf32>

  // Multiply by scale: scale shape [16x1x1], broadcast to [16x16x14x14]
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<16x1x1xf32>) -> tensor<16x16x14x14xf32>
  %scaled = stablehlo.multiply %add_bias, %scale_bcast : tensor<16x16x14x14xf32>

  // Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg_scaled = stablehlo.negate %scaled : tensor<16x16x14x14xf32>
  %exp_neg = stablehlo.exponential %neg_scaled : tensor<16x16x14x14xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_tensor = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x16x14x14xf32>
  %one_plus_exp = stablehlo.add %one_tensor, %exp_neg : tensor<16x16x14x14xf32>
  %sigmoid = stablehlo.divide %one_tensor, %one_plus_exp : tensor<16x16x14x14xf32>

  // GroupNorm: input shape [16x16x14x14], num_groups=8, channels=16
  // GroupNorm reshapes input to [N, G, C//G, H, W] = [16, 8, 2, 14, 14]
  // Then computes mean and variance over axes [2,3,4] (C//G, H, W)
  // Then normalizes: (x - mean) / sqrt(var + eps)
  // Then applies affine transform: output = normalized * gn_weight + gn_bias
  // gn_weight and gn_bias shape: [16], need to broadcast to [16x16x14x14]

  // Reshape input to [16, 8, 2, 14, 14]
  %reshape_gn = stablehlo.reshape %sigmoid : (tensor<16x16x14x14xf32>) -> tensor<16x8x2x14x14xf32>

  // Compute mean over axes [2,3,4]
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%reshape_gn, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<16x8x2x14x14xf32>, tensor<f32>) -> tensor<16x8xf32>

  // Compute number of elements reduced: 2*14*14 = 392
  %count = stablehlo.constant dense<392.0> : tensor<f32>
  // Broadcast count to mean shape for division
  %count_bcast = "stablehlo.broadcast_in_dim"(%count) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x8xf32>
  %mean_val = stablehlo.divide %mean, %count_bcast : tensor<16x8xf32>

  // Broadcast mean_val to input shape [16x8x2x14x14]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_val) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<16x8xf32>) -> tensor<16x8x2x14x14xf32>

  // Compute variance: mean of squared differences
  %diff = stablehlo.subtract %reshape_gn, %mean_bcast : tensor<16x8x2x14x14xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x8x2x14x14xf32>
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var = "stablehlo.reduce"(%diff_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<16x8x2x14x14xf32>, tensor<f32>) -> tensor<16x8xf32>
  %var_val = stablehlo.divide %var, %count_bcast : tensor<16x8xf32>

  // Add epsilon for numerical stability
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x8xf32>
  %var_eps = stablehlo.add %var_val, %eps_bcast : tensor<16x8xf32>

  // Compute rsqrt(var + eps)
  %rsqrt_var = stablehlo.rsqrt %var_eps : tensor<16x8xf32>

  // Broadcast rsqrt_var to input shape
  %rsqrt_bcast = "stablehlo.broadcast_in_dim"(%rsqrt_var) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<16x8xf32>) -> tensor<16x8x2x14x14xf32>

  // Normalize: (x - mean) * rsqrt(var + eps)
  %normalized = stablehlo.multiply %diff, %rsqrt_bcast : tensor<16x8x2x14x14xf32>

  // Reshape normalized back to [16x16x14x14]
  %normalized_reshaped = stablehlo.reshape %normalized : (tensor<16x8x2x14x14xf32>)

func.func @main(%bias: tensor<16x1x1xf32>, %scale: tensor<16x1x1xf32>, %conv_weight: tensor<16x8x3x3xf32>, %conv_bias: tensor<16xf32>, %gn_weight: tensor<16xf32>, %gn_bias: tensor<16xf32>, %input: tensor<16x8x16x16xf32>) -> tensor<16x16x14x14xf32> {
  // Convolution with dimension_numbers: lhs [N, C, H, W], rhs [O, I, KH, KW], output [N, O, OH, OW]
  %conv = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[0, 1, 2, 3]x[0, 1, 2, 3]->[0, 1, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<16x8x16x16xf32>, tensor<16x8x3x3xf32>) -> tensor<16x16x14x14xf32>

  // Broadcast bias [16x1x1] to [16x16x14x14] on dims [1, 2, 3]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<16x1x1xf32>) -> tensor<16x16x14x14xf32>
  %add_bias = stablehlo.add %conv, %bias_bcast : tensor<16x16x14x14xf32>

  // Broadcast scale [16x1x1] to [16x16x14x14] on dims [1, 2, 3]
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<16x1x1xf32>) -> tensor<16x16x14x14xf32>
  %scaled = stablehlo.multiply %add_bias, %scale_bcast : tensor<16x16x14x14xf32>

  // Sigmoid: 1 / (1 + exp(-x))
  %neg_scaled = stablehlo.negate %scaled : tensor<16x16x14x14xf32>
  %exp_neg = stablehlo.exponential %neg_scaled : tensor<16x16x14x14xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x16x14x14xf32>
  %denominator = stablehlo.add %one_bcast, %exp_neg : tensor<16x16x14x14xf32>
  %sigmoid = stablehlo.divide %one_bcast, %denominator : tensor<16x16x14x14xf32>

  // GroupNorm parameters
  // Reshape input [16x16x14x14] to [16, 8, 2, 14, 14] (N, G, C//G, H, W)
  %reshape_gn = stablehlo.reshape %sigmoid : (tensor<16x16x14x14xf32>) -> tensor<16x8x2x14x14xf32>

  // Compute mean over axes [2, 3, 4]
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%reshape_gn, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<16x8x2x14x14xf32>, tensor<f32>) -> tensor<16x8xf32>

  // Divide by number of elements reduced: 2*14*14=392
  %count = stablehlo.constant dense<392.0> : tensor<f32>
  %count_bcast = "stablehlo.broadcast_in_dim"(%count) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x8xf32>
  %mean_val = stablehlo.divide %mean, %count_bcast : tensor<16x8xf32>

  // Broadcast mean_val to [16x8x2x14x14]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_val) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<16x8xf32>) -> tensor<16x8x2x14x14xf32>

  // Compute variance: mean of squared differences
  %diff = stablehlo.subtract %reshape_gn, %mean_bcast : tensor<16x8x2x14x14xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x8x2x14x14xf32>
  %var_sum = "stablehlo.reduce"(%diff_sq, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3, 4>} : (tensor<16x8x2x14x14xf32>, tensor<f32>) -> tensor<16x8xf32>
  %var_val = stablehlo.divide %var_sum, %count_bcast : tensor<16x8xf32>

  // Add epsilon 1e-5 for numerical stability
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x8xf32>
  %var_eps = stablehlo.add %var_val, %eps_bcast : tensor<16x8xf32>

  // Compute rsqrt(var + eps)
  %rsqrt_var = stablehlo.rsqrt %var_eps : tensor<16x8xf32>

  // Broadcast rsqrt_var to [16x8x2x14x14]
  %rsqrt_bcast = "stablehlo.broadcast_in_dim"(%rsqrt_var) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4>} : (tensor<16x8xf32>) -> tensor<16x8x2x14x14xf32>

  // Normalize: (x - mean) * rsqrt(var + eps)
  %normalized = stablehlo.multiply %diff, %rsqrt_bcast : tensor<16x8x2x14x14xf32>

  // Reshape normalized back to [16x16x14x14]
  %normalized_reshaped = stablehlo.reshape %normalized : (tensor<16x8x2x14x14xf32>) -> tensor<16x16x14x14xf32>

  // Broadcast gn_weight [16] to [16x16x14x14] on dims [1]
  %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%gn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16x14x14xf32>
  // Broadcast gn_bias [16] to [16x16x14x14] on dims [1]
  %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%gn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16x14x14xf32>

  // Apply affine transform: normalized * weight + bias
  %scaled_norm = stablehlo.multiply %normalized_reshaped, %gn_weight_bcast : tensor<16x16x14x14xf32>
  %output = stablehlo.add %scaled_norm, %gn_bias_bcast : tensor<16x16x14x14xf32>

  func.return %output : tensor<16x16x14x14xf32>
}

