  %slope_broadcast = "stablehlo.broadcast_in_dim"(%slope) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<6x1xf32>
  %scaled_min1 = stablehlo.multiply %min_part1, %slope_broadcast : tensor<6x1xf32>
  %leaky1 = stablehlo.add %max_part1, %scaled_min1 : tensor<6x1xf32>
