  // weight: %arg1 (7x7x3x3) with dimension_numbers for ConvTranspose2d
  // stride=2, padding=1, output_padding=1
  // dimension_numbers: input [b,f,h,w], kernel [i,o,h,w], output [b,f,h,w]
  // For ConvTranspose2d, swap lhs and rhs dims accordingly:
  // Here, stablehlo.convolution expects dimension_numbers = #stablehlo.conv<[b,f,0,1]x[o,i,0,1]->[b,f,0,1]>
  // But for transposed conv, we use rhs_dilation=stride and window_strides=1, padding adjusted.
  // Using the standard trick: transposed conv = conv with rhs_dilation=stride, window_strides=1, padding adjusted.

  // Set rhs_dilation = stride = [2,2]
  // window_strides = [1,1]
  // padding = [[padding_lo, padding_hi], [padding_lo, padding_hi]] = [[1,1],[1,1]]
  // output_padding handled by adjusting padding_hi by output_padding (1)
  // So padding_hi = padding + output_padding = 1 + 1 = 2

  // So padding = [[1,2],[1,2]]

  %c_window_strides = stablehlo.constant dense<1, 1> : tensor<2xi64>
  %c_padding = stablehlo.constant dense<[[1, 2], [1, 2]]> : tensor<2x2xi64>
  %c_lhs_dilation = stablehlo.constant dense<1, 1> : tensor<2xi64>
  %c_rhs_dilation = stablehlo.constant dense<2, 2> : tensor<2xi64>

