  // StableHLO conv expects weight shape: [out_channels, in_channels, kH, kW]
  // So we need to transpose %arg1 from [7,7,3,3] to [7,7,3,3] swapping first two dims
  // Actually, in PyTorch ConvTranspose2d weight shape is (in_channels, out_channels, kH, kW)
  // StableHLO conv expects weight shape [out_channels, in_channels, kH, kW]
  // So we transpose first two dims: (1,0,2,3)

  %weight_transposed = stablehlo.transpose %arg1 : tensor<7x7x3x3xf32> to tensor<7x7x3x3xf32> {permutation = [1, 0, 2, 3]}

  // ConvTranspose2d parameters:
  // stride=2, padding=1, output_padding=1
  // Input shape: [6,7,6,6]
  // Output shape: [6,7,12,12] (given)
  // We use stablehlo.convolution with dimension_numbers:
  // input: NCHW = [batch, in_channels, height, width]
  // kernel: OIHW = [out_channels, in_channels, kernel_h, kernel_w]
  // output: NCHW
  // For transposed convolution, stablehlo.convolution supports "window reversal" and "lhs dilation"
  // We implement ConvTranspose2d as a convolution with lhs dilation=stride, padding=padding, and output_padding=output_padding
  // lhs_dilation = stride = [2,2]
  // padding = [1,1]
  // output_padding = 1 means output size is increased by 1 in height and width compared to normal conv transpose formula
  // stablehlo.convolution does not have output_padding param, so we adjust padding accordingly:
  // We set padding low=padding, high=padding + output_padding
  // So padding low = 1, padding high = 2

  // Define dimension numbers for convolution:
  // input: NCHW -> batch=0, feature=1, spatial=[2,3]
  // kernel: OIHW -> output_feature=0, input_feature=1, spatial=[2,3]
  // output: NCHW -> batch=0, feature=1, spatial=[2,3]

  %conv = stablehlo.convolution %arg3, %weight_transposed {
    window_strides = [1, 1],
    padding = [[1, 2], [1, 2]],
    lhs_dilation = [2, 2],
    dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2, 3],
      kernel_output_feature_dimension = 0,
      kernel_input_feature_dimension = 1,
      kernel_spatial_dimensions = [2, 3],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2, 3]
    }
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Add bias: %arg0 shape is [7,1,1], broadcast to [6,7,12,12]
  // Broadcast bias to output shape:
  %bias_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<7x1x1xf32> to tensor<6x7x12x12xf32> broadcast_dimensions = [1, 0, 2, 3]

