  // We want to broadcast bias over batch dim (0) and spatial dims (2,3)
  // So bias dims correspond to output dims: batch=0, channel=1, height=2, width=3
  // But bias dims are (7,1,1) so dims are (channel=0, height=1, width=2)
  // So broadcast_dimensions = [1, 2, 3] would be wrong because output dim 0 is batch
  // We must insert batch dim in output, so bias dims map to output dims [1,2,3]
  // stablehlo.broadcast_in_dim requires broadcast_dimensions to be the dims of the input that map to output dims
  // So input dims 0,1,2 map to output dims 1,2,3 respectively
  // So broadcast_dimensions = [1,2,3]

  %bias_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<7x1x1xf32> to tensor<6x7x12x12xf32> broadcast_dimensions = [1, 2, 3]

  %add = stablehlo.add %conv, %bias_broadcast : tensor<6x7x12x12xf32>

  // Clamp between 0.0 and 1.0
  %zero = stablehlo.constant 0.0 : f32
