  %zero_tensor = stablehlo.broadcast %zero : tensor<f32> to tensor<6x7x12x12xf32>
  %one_tensor = stablehlo.broadcast %one : tensor<f32> to tensor<6x7x12x12xf32>

  %clamp_min = stablehlo.maximum %add, %zero_tensor : tensor<6x7x12x12xf32>
  %clamp_max = stablehlo.minimum %clamp_min, %one_tensor : tensor<6x7x12x12xf32>

  // Multiply by scaling_factor=2.0 (constant)
  %scale = stablehlo.constant 2.0 : f32
  %scale_tensor = stablehlo.broadcast %scale : tensor<f32> to tensor<6x7x12x12xf32>
  %scaled = stablehlo.multiply %clamp_max, %scale_tensor : tensor<6x7x12x12xf32>

  // Clamp again between 0.0 and 1.0
  %clamp2_min = stablehlo.maximum %scaled, %zero_tensor : tensor<6x7x12x12xf32>
  %clamp2_max = stablehlo.minimum %clamp2_min, %one_tensor : tensor<6x7x12x12xf32>

  // Divide by scaling_factor=2.0
  %result = stablehlo.divide %clamp2_max, %scale_tensor : tensor<6x7x12x12xf32>

  func.return %result : tensor<6x7x12x12xf32>
}

