  %clamp2_max = stablehlo.minimum %clamp2_min, %one_tensor : tensor<6x7x12x12xf32>

  // Divide by scaling_factor
  %result = stablehlo.divide %clamp2_max, %scale_tensor : tensor<6x7x12x12xf32>

