  // output shape: (6, 7, 12, 12)

  %stride = array<i64: 1, 1> : array<i64>
  %lhs_dilation = array<i64: 2, 2> : array<i64>  // stride=2 dilation on lhs
  %rhs_dilation = array<i64: 1, 1> : array<i64>
