  // rhs: o=0, i=1, spatial=2,3
  // output: b=0, f=1, spatial=2,3
  // So dimension_numbers = #stablehlo.conv<[0,1,2,3]x[0,1,2,3]->[0,1,2,3]>
  // But the problem states the example uses #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>
  // So we use the same pattern:
  // lhs: b=0, f=1, h=2, w=3
  // rhs: o=0, i=1, kh=2, kw=3
  // output: b=0, f=1, h=2, w=3
  // So dimension_numbers = #stablehlo.conv<[0,1,2,3]x[0,1,2,3]->[0,1,2,3]>

  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = %stride,
    padding = %padding,
    lhs_dilation = %lhs_dilation,
    rhs_dilation = %rhs_dilation,
    dimension_numbers = #stablehlo.conv<[0,1,2,3]x[0,1,2,3]->[0,1,2,3]>,
    feature_group_count = %feature_group_count,
    batch_group_count = %batch_group_count
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Step 2: Add bias (7x1x1) to conv output (6x7x12x12)
