  // Note: We must broadcast bias from (7x1x1) to (6x7x12x12)
  // The batch dimension 6 is new, so we broadcast batch dimension 0 to 6
  // stablehlo.broadcast_in_dim requires input dims to be mapped to output dims
  // Input dims: 0=7,1=1,2=1
  // Output dims: 0=6,1=7,2=12,3=12
  // So broadcast_dimensions = [1,2,3] means input dim 0->output dim 1, input dim 1->output dim 2, input dim 2->output dim 3
  // batch dim 0 is broadcasted

  %add_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x12x12xf32>

  // Step 3: Clamp between 0.0 and 1.0
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64:  } : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64:  } : (tensor<f32>) -> tensor<6x7x12x12xf32>
