  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x7x12x12xf32>
  // The syntax requires array<i64: > with no elements, so array<i64:> is empty array

  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>

  %clamp_min = stablehlo.maximum %add_bias, %zero_broadcast : tensor<6x7x12x12xf32>
  %clamp = stablehlo.minimum %clamp_min, %one_broadcast : tensor<6x7x12x12xf32>

  // Step 4: Multiply by scaling_factor=2.0
  %scale_val = stablehlo.constant dense<2.0> : tensor<f32>
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale_val) {broadcast_dimensions = array<i64:>} : (tensor<f32>) -> tensor<6x7x12x12xf32>
  %scaled = stablehlo.multiply %clamp, %scale_broadcast : tensor<6x7x12x12xf32>

  // Step 5: Clamp again between 0.0 and 1.0
  %clamp2_min = stablehlo.maximum %scaled, %zero_broadcast : tensor<6x7x12x12xf32>
  %clamp2 = stablehlo.minimum %clamp2_min, %one_broadcast : tensor<6x7x12x12xf32>

  // Step 6: Divide by scaling_factor=2.0
  %divided = stablehlo.divide

func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<7x7x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
  // Perform transposed convolution with conv_transpose.weight (%arg1) and input %arg3
  // conv_transpose.weight shape: [7,7,3,3] (out_channels, in_channels, kernel_h, kernel_w)
  // input shape: [6,7,6,6] (batch, in_channels, h, w)
  // output shape: [6,7,12,12] (batch, out_channels, h_out, w_out)
  // Parameters for convolution:
  // window_strides = [1,1] (for transposed conv, stride is handled by lhs_dilation)
  // lhs_dilation = stride = [2,2]
  // rhs_dilation = [1,1]
  // padding = padding = 1 on each side
  // output_padding = 1 (handled by padding or output shape, but StableHLO convolution does not have output_padding attribute)
  // We handle output_padding by adjusting padding or input shape accordingly.
  // According to PyTorch docs, output_padding adds extra pixels to output shape.
  // In StableHLO, output_padding is not explicit, so we adjust padding accordingly:
  // For transposed conv, output spatial size formula:
  // output = (input - 1) * stride - 2*padding + kernel + output_padding
  // Here stride=2, padding=1, kernel=3, output_padding=1
  // So output size = (6-1)*2 - 2*1 + 3 + 1 = 10 - 2 + 3 + 1 = 12
  // So output shape matches 12x12 as expected.
  // We set padding to [1,1] for convolution op.
  // dimension_numbers: input [b,f,0,1], kernel [o,i,0,1], output [b,f,0,1]
  // feature_group_count = 1, batch_group_count = 1

  %one = stablehlo.constant dense<1> : tensor<i64>
  %stride = stablehlo.constant dense<2> : tensor<i64>
  %padding = stablehlo.constant dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>
  %window_strides = stablehlo.constant dense<array<i64: 1, 1>> : tensor<2xi64>
  %lhs_dilation = stablehlo.constant dense<array<i64: 2, 2>> : tensor<2xi64>
  %rhs_dilation = stablehlo.constant dense<array<i64: 1, 1>> : tensor<2xi64>

  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Add bias: %arg0 shape [7x1x1], broadcast to [6x7x12x12]
  // Broadcast bias to output shape:
  // bias shape: [7,1,1] -> broadcast dims: [1,2,3] in output [6,7,12,12]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<7x1x1xf32>) -> tensor<6x7x12x12xf32>

  %add_bias = stablehlo.add %conv, %bias_broadcast : tensor<6x7x12x12xf32>

  // Clamp between 0.0 and 1.0
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one_f = stablehlo.constant dense<1.0> : tensor<f32>
  %clamp_min = stablehlo.maximum %add_bias, %zero : tensor<6x7x12x12xf32>
  %clamp = stablehlo.minimum %clamp_min, %one_f : tensor<6x7x12x12xf32>

  // Multiply by scaling_factor = 2.0 (constant)
  %scale = stablehlo.constant dense<2.0> : tensor<f32>
  %scaled = stablehlo.multiply %clamp, %scale : tensor<6x7x12x12xf32>

  // Clamp again between 0.0 and 1.0
  %clamp2_min = stablehlo.maximum %scaled, %zero : tensor<6x7x12x12xf32>
  %clamp2 = stablehlo.minimum %clamp2_min, %one_f : tensor<6x7x12x12xf32>

  // Divide by scaling_factor
  %result = stablehlo.divide %clamp2, %scale : tensor<6x7x12x12xf32>

  return %result : tensor<6x7x12x12xf32>
}

func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<7x7x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
