  // output_padding=1 means output size is increased by 1 in each spatial dim

  // We set window_strides = [2,2]
  // dilations = [1,1]
  // feature_group_count = 1

  // Create constant for scaling_factor = 2.0
  %cst_scaling = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>

  // Convolution transpose
  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = [2, 3],
      kernel_output_feature_dimension = 0,
      kernel_input_feature_dimension = 1,
      kernel_spatial_dimensions = [2, 3],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2, 3]
    },
    window_strides = array<i64: 2, 2>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    feature_group_count = 1,
    batch_group_count = 1,
    precision_config = {},
    // transpose convolution attribute
    // OpenXLA uses "transpose" attribute for conv_transpose
    // But stablehlo spec does not mention it explicitly, so we simulate conv_transpose by swapping lhs_dilation and rhs_dilation
    // Actually, stablehlo convolution op does not have transpose attribute, so we simulate conv_transpose by setting lhs_dilation = stride and window_strides = 1
    // So we swap window_strides and lhs_dilation to simulate conv_transpose:
    window_strides = array<i64: 1, 1>,
    lhs_dilation = array<i64: 2, 2>
