  %bias_reshaped = "stablehlo.reshape"(%arg0) : (tensor<7x1x1xf32>) -> tensor<7x1x1xf32>
  // Broadcast bias to [6,7,12,12]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias_reshaped) {broadcast_dimensions = array<i64: 1, 2, 3>, output_shape = [6,7,12,12]} : (tensor<7x1x1xf32>) -> tensor<6x7x12x12xf32>

  // Add bias to conv output
  %add_bias = "stablehlo.add"(%conv, %bias_broadcast) : (tensor<6x7x12x12xf32>, tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xf32>

  // Clamp min=0.0 max=1.0
  %cst_zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %cst_one = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %clamp_min = "stablehlo.maximum"(%add_bias, %cst_zero) : (tensor<6x7x12x12xf32>, tensor<f32>) -> tensor<6x7x12x12xf32>
  %clamp = "stablehlo.minimum"(%clamp_min, %cst_one) : (tensor<6x7x12x12xf32>, tensor<f32>) -> tensor<6x7x12x12xf32>

