  %scaled = "stablehlo.multiply"(%clamp, %cst_scaling) : (tensor<6x7x12x12xf32>, tensor<f32>) -> tensor<6x7x12x12xf32>

  // Clamp again min=0.0 max=1.0
  %clamp2_min = "stablehlo.maximum"(%scaled, %cst_zero) : (tensor<6x7x12x12xf32>, tensor<f32>) -> tensor<6x7x12x12xf32>
  %clamp2 = "stablehlo.minimum"(%clamp2_min, %cst_one) : (tensor<6x7x12x12xf32>, tensor<f32>) -> tensor<6x7x12x12xf32>

  // Divide by scaling_factor (2.0)
  %result = "stablehlo.divide"(%clamp2, %cst_scaling) : (tensor<6x7x12x12xf32>, tensor<f32>) -> tensor<6x7x12x12xf32>

  return %result : tensor<6x7x12x12xf32>
}

func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<7x7x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x7x6x6xf32>) -> tensor<6x7x12x12xf32> {
