  // Average Pool 3D with kernel_size=2, stride=2, no padding
  // Implemented as reduce_window with sum and then divide by 8 (2*2*2)
  // window_dimensions = [1,1,2,2,2] to pool spatial dims only (batch and channel dims window=1)
  // window_strides = [1,1,2,2,2]
