    padding = %padding_pool
  } : (tensor<6x16x15x6x6xf32>, tensor<f32>) -> tensor<6x16x7x3x3xf32>

  // Divide by 8.0 (2*2*2) to get average
  %eight = stablehlo.constant dense<8.0> : tensor<f32>
  %eight_bcast = "stablehlo.broadcast_in_dim"(%eight) {broadcast_dimensions = dense<[ ]> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x16x7x3x3xf32>
  %avg_pool = stablehlo.divide %sum_pool, %eight_bcast : tensor<6x16x7x3x3xf32>

