  // Broadcast bias to [6,16,7,3,3]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bias_reshape) {broadcast_dimensions = stablehlo.constant dense<[0, 1, 2, 3, 4]> : tensor<5xi64>} : (tensor<1x16x1x1x1xf32>) -> tensor<6x16x7x3x3xf32>

  %biased = stablehlo.add %avg_pool, %bias_bcast : tensor<6x16x7x3x3xf32>

  // Multiply by scale2 (scalar tensor<f32>)
  // Broadcast scale2 to [6,16,7,3,3]
  %scale2_bcast = "stablehlo.broadcast_in_dim"(%scale2) {broadcast_dimensions = dense<[ ]> : tensor<0xi64>} : (tensor<f32>) -> tensor<6x16x7x3x3xf32>
