  // broadcast max_per_row to shape (6,6,7,7)
  %max_per_row_b = "stablehlo.broadcast_in_dim"(%max_per_row) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x6x7xf32>) -> tensor<6x6x7x7xf32>

  // subtract max for numerical stability
  %shifted = stablehlo.subtract %scaled_qk, %max_per_row_b : tensor<6x6x7x7xf32>

  // exp(shifted)
  %exp_shifted = stablehlo.exponential %shifted : tensor<6x6x7x7xf32>

  // sum exp over last dim (dim=3)
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_shifted, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
