  %sum_exp_b = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x6x7xf32>) -> tensor<6x6x7x7xf32>

  // divide exp_shifted by sum_exp to get softmax
  %softmax = stablehlo.divide %exp_shifted, %sum_exp_b : tensor<6x6x7x7xf32>

  // dot_general softmax and V
  // softmax shape: (6,6,7,7), V shape: (6,6,7,8)
  // batch dims: 0,1; contracting dims: softmax last dim 3 and V dim 2
  %out = "stablehlo.dot_general"(%softmax, %arg2) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0, 1],
      rhs_batching_dimensions = [0, 1],
      lhs_contracting_dimensions = [3],
      rhs_contracting_dimensions = [2]>
  } : (tensor<6x6x7x7xf32>, tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32>

  "stablehlo.return"(%out) : tensor<6x6x7x8xf32>
}

