func.func @main(%arg0: tensor<6x6x7x8xf32>, %arg1: tensor<6x6x7x8xf32>, %arg2: tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32> {
  // %arg0 = Q, %arg1 = K, %arg2 = V
  // scaled_dot_product_attention(Q, K, V) = softmax(QK^T / sqrt(d_k)) V
  // d_k = embedding_dimension = 8

  // Step 1: Compute QK^T
  // Q shape: [6,6,7,8], K shape: [6,6,7,8]
  // We want to do a batched matmul over batch and heads (dims 0 and 1),
  // contracting embedding dimension (dim 3 of Q) with embedding dimension (dim 3 of K),
  // but K needs to be transposed on last two dims (7 and 8) to get K^T on last two dims.
  // So we transpose K from [6,6,7,8] to [6,6,8,7].
  %k_transposed = stablehlo.transpose %arg1 : tensor<6x6x7x8xf32> to tensor<6x6x8x7xf32> {permutation = [0, 1, 3, 2]}

  // Dot general dimensions:
  // batch dims: [0,1] for both
  // contracting dims: Q dim 3 (embedding), K dim 2 (embedding after transpose)
  // result dims: Q dim 2 (sequence length), K dim 3 (sequence length after transpose)
  %qk = stablehlo.dot_general %arg0, %k_transposed {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0, 1],
      rhs_batching_dimensions = [0, 1],
      lhs_contracting_dimensions = [3],
      rhs_contracting_dimensions = [2]
    >
  } : (tensor<6x6x7x8xf32>, tensor<6x6x8x7xf32>) -> tensor<6x6x7x7xf32>

  // Step 2: Scale by sqrt(d_k) = sqrt(8)
  %scale = stablehlo.constant 2.828427f32 : f32
  %scale_tensor = stablehlo.broadcast_in_dim %scale : tensor<f32> to tensor<6x6x7x7xf32> broadcast_dimensions = [] 
  // Actually, broadcast_in_dim with empty broadcast_dimensions broadcasts scalar to all dims.
  // But stablehlo.broadcast_in_dim requires broadcast_dimensions to be a subset of dims of output.
  // For scalar to tensor, broadcast_dimensions = [] is correct.

  %scaled_qk = stablehlo.divide %qk, %scale_tensor : tensor<6x6x7x7xf32>

  // Step 3: Compute softmax over last dimension (dim 3, the key sequence length)
  // softmax(x) = exp(x - max(x)) / sum(exp(x - max(x)))
  // We do this per batch, head, and query position (dims 0,1,2), over dim 3.

  // Compute max over dim 3
  %init_max = stablehlo.constant -3.4028235e+38 : f32  // -inf approx
  %init_max_tensor = stablehlo.broadcast_in_dim %init_max : tensor<f32> to tensor<6x6x7x1xf32> broadcast_dimensions = [0,1,2]
  %max = stablehlo.reduce %scaled_qk, %init_max_tensor (
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  ) {dimensions = dense<[3]>} : (tensor<6x6x7x7xf32>, tensor<6x6x7x1xf32>) -> tensor<6x6x7x1xf32>

