  %max_broadcast = stablehlo.broadcast_in_dim %max : tensor<6x6x7x1xf32> to tensor<6x6x7x7xf32> broadcast_dimensions = [0,1,2]

  // Subtract max for numerical stability
  %shifted = stablehlo.subtract %scaled_qk, %max_broadcast : tensor<6x6x7x7xf32>

  // Exponentiate
  %exp = stablehlo.exponential %shifted : tensor<6x6x7x7xf32>

  // Compute sum over dim 3
  %init_zero = stablehlo.constant 0.0 : f32
  %init_zero_tensor = stablehlo.broadcast_in_dim %init_zero : tensor<f32> to tensor<6x6x7x1xf32> broadcast_dimensions = [0,1,2]
  %sum_exp = stablehlo.reduce %exp, %init_zero_tensor (
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
