  %exp = stablehlo.exponential %shifted : tensor<6x6x7x7xf32>

  // 5) sum of exp over last dim
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7xf32>

  // 6) broadcast sum_exp for division
  %sum_exp_b = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 1, 2>} : (tensor<6x6x7xf32>) -> tensor<6x6x7x7xf32>

  // 7) divide exp by sum_exp to get softmax
  %softmax = stablehlo.divide %exp, %sum_exp_b : tensor<6x6x7x7xf32>

  // Multiply softmax weights by V
  // Dot product over sequence_length dimension (dim=2)
  // softmax shape: [6,6,7,7], V shape: [6,6,7,8]
  // Contract softmax dim 3 with V dim 2
  // Batch dims: 0 and 1
  %out = "stablehlo.dot_general"(%softmax, %arg2) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [0, 1],
      rhs_batching_dimensions = [0, 1],
      lhs_contracting_dimensions = [3],
      rhs_contracting_dimensions = [2]>
  } : (tensor<6x6x7x7xf32>, tensor<6x6x7x8xf32>) -> tensor<6x6x7x8xf32>

  "stablehlo.return"(%out) : tensor<6x6x7x8xf32>
}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // Fully connected layer: x @ fc.weight^T + fc.bias
  // %arg0 = fc.weight (16x16), %arg1 = fc.bias (16), %arg4 = input (16x16)
  // We need to do dot_general with lhs = input (batch_size=16, input_size=16)
  // rhs = weight (hidden_size=16, input_size=16), but weight needs to be transposed to (input_size=16, hidden_size=16)
  // So transpose fc.weight to (16,16) (actually same shape), but we want to contract input's last dim (1) with weight's last dim (1)
  // Actually, PyTorch Linear does x @ weight.T + bias, so weight is (out_features, in_features)
  // So we do dot_general with lhs_contracting=1, rhs_contracting=1, lhs_batching=0, rhs_batching=0
  // But weight needs to be transposed to (in_features, out_features) for dot_general contracting last dim of lhs and first dim of rhs
  // So transpose weight from (16x16) to (16x16) with permutation [1,0]
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %fc_out = "stablehlo.dot_general"(%arg4, %weight_t) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [0], rhs_batching_dimensions = [0], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  // Add bias: broadcast bias (16) to (16x16)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %fc_out_bias = stablehlo.add %fc_out, %bias_bcast : tensor<16x16xf32>

  // GroupNorm with num_groups=16, num_channels=16, eps=1e-5
  // Input shape: (N=16, C=16)
  // GroupNorm reshapes input to (N, G, C//G), computes mean and variance over (C//G) dim, normalizes, then applies affine transform
  // Here G=16, C=16, so C//G=1
  // Reshape input to (16,16,1)
  %gn_reshape = stablehlo.reshape %fc_out_bias : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over axis=2 (last dim)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0,1>} : (tensor<f32>) -> tensor<16x16xf32>
  %mean = "stablehlo.reduce"(%gn_reshape, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // mean shape: (16,16)
  // Divide by size=1 (C//G=1), so mean is sum/1 = sum
  // So mean is already correct

  // Broadcast mean back to (16,16,1)
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0,1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute variance: mean of (x - mean)^2 over axis=2
  %diff = stablehlo.subtract %gn_reshape, %mean_bcast : tensor<16x16x1xf32>
  %sq_diff = stablehlo.multiply %diff, %diff : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%sq_diff, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>
  // variance shape: (16,16)
  // Divide by 1 (C//G=1), so var is sum/1 = sum

  // Broadcast variance back to (16,16,1)
  %var_bcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 0,1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // eps constant
  %eps = stablehlo.constant dense<1.000000e-05> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  // Broadcast eps to (16,16,1)
  %eps_bcast3 = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  %eps_bcast_3d = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  // Instead, broadcast eps to (16,16,1)
  %eps_bcast_3d = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  // To avoid confusion, broadcast eps to (16,16,1)
  %eps_bcast_3d = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0,1,2>} : (tensor<f32>) -> tensor<16x16x1xf32>

  // variance + eps
  %var_eps = stablehlo.add %var_bcast, %eps_bcast_3d : tensor<16x16x1xf32>

  // rsqrt(variance + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16x1xf32>

  // Normalize: (x - mean) * inv_std
  %norm = stablehlo.multiply %diff, %inv_std : tensor<16x16x1xf32>

  // Reshape norm to (16,16)
  %norm_2d = stablehlo.reshape %norm : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply affine transform: norm * gn.weight + gn.bias
  // %arg2 = gn.weight (16), %arg3 = gn.bias (16)
  // Broadcast gn.weight and gn.bias to (16x16)
  %gn_weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %gn_bias_bcast = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %scaled = stablehlo.multiply %norm_2d, %gn_weight_bcast : tensor<16x16xf32>
  %gn_out = stablehlo.add %scaled, %gn_bias_bcast : tensor<16x16xf32>

  // LeakyReLU with negative_slope=0.01
  // leaky_relu(x) = max(0,x) + negative_slope * min(0,x)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: 0,1>} : (tensor<f32>) -> tensor<16x16xf32>
  %gt_zero = "stablehlo.compare"(%gn_out, %zero_bcast) {comparison_direction = #stablehlo<comparison_direction GT>, compare_type = #stablehlo<comparison_type FLOAT>}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
