  %sum = "stablehlo.reduce"(%input_reshaped, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3, 4, 5>} : (tensor<14x8x2x16x16x16xf32>, tensor<f32>) -> tensor<14x8xf32>

  // Number of elements reduced: 2*16*16*16 = 8192
  %num_elements = stablehlo.constant dense<8192.0> : tensor<f32>

