      "stablehlo.return"(%add2) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3, 4, 5>} : (tensor<14x8x2x16x16x16xf32>, tensor<f32>) -> tensor<14x8xf32>
