  %inv_std_bcast = "stablehlo.broadcast_in_dim"(%inv_std_reshaped) {broadcast_dimensions = array<i64: 0, 1, 2, 3, 4, 5}} : (tensor<14x8x1x1x1x1xf32>) -> tensor<14x8x2x16x16x16xf32>

