  // For transposed conv, output shape is computed as:
  // output_size = stride * (input_size - 1) + kernel_size - 2 * padding
  // Given stride=2, padding=1, kernel=3, input sizes = (6,7,8)
  // output depth = 2*(6-1)+3-2*1 = 2*5+3-2=10+3-2=11
  // output height= 2*(7-1)+3-2=12+3-2=13
  // output width= 2*(8-1)+3-2=14+3-2=15

