  // input: [batch, feature, depth, height, width] = [b, f, d, h, w]
  // kernel: [out_feature, in_feature, kd, kh, kw] = [o, i, kd, kh, kw]
  // output: [batch, feature, depth, height, width] = [b, f, d, h, w]
  // For convolution, dimension_numbers attribute is #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>
  // But stablehlo expects dimension_numbers in a specific format:
