  // So rewrite the broadcast_in_dim ops for scalar broadcast without broadcast_dimensions attribute.

  // Rewriting the program with that fix:

  // Compute difference: diff = predictions - targets
  %diff = stablehlo.subtract %arg0, %arg1 : tensor<6x6xf32>

  // abs_diff = abs(diff)
  %abs_diff = stablehlo.abs %diff : tensor<6x6xf32>

  // constant 1.0 for comparison
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>

  // Broadcast c1 to shape 6x6 (scalar broadcast, omit broadcast_dimensions)
  %c1_b = "stablehlo.broadcast_in_dim"(%c1) : (tensor<f32>) -> tensor<6x6xf32>

  // Compare abs_diff < 1.0
  %cmp = "stablehlo.compare"(%abs_diff, %c1_b) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xi1>

  // Compute 0.5 * diff^2
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x6xf32>
  %c0_5 = stablehlo.constant dense<0.5> : tensor<f32>

  // Broadcast 0.5 to shape 6x6 (scalar broadcast, omit broadcast_dimensions)
  %c0_5_b = "stablehlo.broadcast_in_dim"(%c0_5) : (tensor<f32>) -> tensor<6x6xf32>

  %half_diff_sq = stablehlo.multiply %c0_5_b, %diff_sq : tensor<6x6xf32>

  // Compute abs_diff - 0.5
  %abs_diff_minus_half = stablehlo.subtract %abs_diff, %c0_5_b : tensor<6x6xf32>

  // Select: if abs_diff < 1.0 then 0.5*diff^2 else abs_diff - 0.5
  %loss_per_element = "stablehlo.select"(%cmp, %half_diff_sq, %abs_diff_minus_half) : (tensor<6x6xi1>, tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Sum all elements to get scalar loss
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %loss_sum = "stablehlo.reduce"(%loss_per_element, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>, tensor<f32>) -> tensor<f32>

  return %loss_sum : tensor<f32>
}

