  // MaxPool with kernel size 4, stride 4, no padding
  %init = "stablehlo.constant"() {value = dense<-inf> : tensor<f32>} : () -> tensor<f32>
  %maxpool = "stablehlo.reduce_window"(%biased, %init) ({
