func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<7x8x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x8x8x8xf32>) -> tensor<6x7x1x1xf32> {
  // %arg3: input tensor with shape [6,8,8,8] (N, C_in, H, W)
  // %arg1: conv.weight with shape [7,8,3,3] (C_out, C_in, KH, KW)
  // %arg2: conv.bias with shape [7]
  // %arg0: bias with shape [7,1,1]

  // Convolution: NCHW layout assumed by PyTorch conv2d, but input is NHWC in StableHLO.
  // We need to transpose input from NHWC to NCHW for convolution, then transpose back.
  // However, StableHLO convolution expects input in NCHW format.
  // So first transpose input from NHWC (6x8x8x8) to NCHW (6x8x8x8) - actually input is 6x8x8x8, but given shape is 6x8x8x8, so input is NHWC or NCHW?
  // The input shape is 6x8x8x8, which matches NCHW (N=6, C=8, H=8, W=8).
  // So no transpose needed.

  // Convolution parameters:
  // strides = [1,1]
  // padding = 0 (valid)
  // dilations = 1
  // feature_group_count = 1

  %conv = "stablehlo.convolution"(%arg3, %arg1) {
    window_strides = [1, 1],
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = [1, 1],
    rhs_dilation = [1, 1],
    dimension_numbers = {
      lhs_batch_dimension = 0,
      lhs_feature_dimension = 1,
      lhs_spatial_dimensions = [2, 3],
      rhs_output_feature_dimension = 0,
      rhs_input_feature_dimension = 1,
      rhs_spatial_dimensions = [2, 3],
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = [2, 3]
    },
    feature_group_count = 1
  } : (tensor<6x8x8x8xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x6x6xf32>

  // Add conv.bias (%arg2) to conv output (%conv)
  // conv.bias shape: [7], conv output shape: [6,7,6,6]
  // Broadcast conv.bias to [6,7,6,6]
  %conv_bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = [1]} : (tensor<7xf32>) -> tensor<6x7x6x6xf32>

  %conv_plus_bias = "stablehlo.add"(%conv, %conv_bias_bcast) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Apply tanh activation
  %tanh = "stablehlo.tanh"(%conv_plus_bias) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Scaling factor is 2.0 (f32 scalar)
  %scale = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>

  // Broadcast scale to [6,7,6,6]
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = []} : (tensor<f32>) -> tensor<6x7x6x6xf32>

  // Multiply tanh output by scaling factor
  %scaled = "stablehlo.multiply"(%tanh, %scale_bcast) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Add bias (%arg0) with shape [7,1,1] to scaled output [6,7,6,6]
  // Broadcast bias to [6,7,6,6]
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = [1, 2, 3]} : (tensor<7x1x1xf32>) -> tensor<6x7x6x6xf32>

  %biased = "stablehlo.add"(%scaled, %bias_bcast) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // MaxPool2d with kernel size 4, stride 4, no padding
  // Window dimensions = [4,4]
  // Strides = [4,4]
  // Padding = 0
  // Input shape: [6,7,6,6]
  // Output shape: floor((6-4)/4)+1 = 1 for spatial dims, so output shape [6,7,1,1]

  %pool = "stablehlo.reduce_window"(%biased) ( {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max = "stablehlo.maximum"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%max) : (tensor<f32>) -> ()
  }) {
    window_dimensions = [1, 1, 4, 4],
    window_strides = [1, 1, 4, 4],
    base_dilations = [1, 1, 1, 1],
    window_dilations = [1, 1, 1, 1],
    padding = dense<[[0, 0], [0, 0], [0, 0], [0, 0]]> : tensor<4x2xi64>
  } : (tensor<6x7x6x6xf32>) -> tensor<6x7x1x1xf32>

  return %pool : tensor<6x7x1x1xf32>
}

func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<7x8x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<6x8x8x8xf32>) -> tensor<6x7x1x1xf32> {
