  // Define the dimension numbers attribute inline here:
  // input: [batch, feature, height, width] = [0,1,2,3]
  // kernel: [output_feature, input_feature, height, width] = [0,1,2,3]
  // output: [batch, feature, height, width] = [0,1,2,3]
  // So dimension_numbers = #stablehlo.conv<[0,1,2,3]x[0,1,2,3]->[0,1,2,3]>

  // We must define this attribute in-place as a dictionary attribute.

  %dim_nums = {
