  %conv_bias_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = [1]} : (tensor<7xf32>) -> tensor<6x7x6x6xf32>

  %conv_plus_bias = "stablehlo.add"(%conv, %conv_bias_bcast) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

