  %tanh = "stablehlo.tanh"(%conv_plus_bias) : (tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

  // Scaling factor constant 2.0
  %scale = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>

  // Broadcast scale to [6,7,6,6]
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = []} : (tensor<f32>) -> tensor<6x7x6x6xf32>

  %scaled = "stablehlo.multiply"(%tanh, %scale_bcast) : (tensor<6x7x6x6xf32>, tensor<6x7x6x6xf32>) -> tensor<6x7x6x6xf32>

