  } : (tensor<6x7x6x6xf32>) -> tensor<6x7x1x1xf32>

  return %pool : tensor<6x7x1x1xf32>
}

func.func @main(%arg0: tensor<6x6xf32>, %arg1: tensor<6x6xf32>) -> tensor<f32> {
  // Compute diff = predictions - targets
  %diff = stablehlo.subtract %arg0, %arg1 : tensor<6x6xf32>

  // Compute abs_diff = abs(diff)
  %abs_diff = stablehlo.abs %diff : tensor<6x6xf32>

  // constant 1.0 for comparison
  %c1 = stablehlo.constant dense<1.000000e+00> : tensor<f32>
  %c1_bcast = "stablehlo.broadcast_in_dim"(%c1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>

  // Compare abs_diff < 1.0
  %cond = "stablehlo.compare"(%abs_diff, %c1_bcast) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xi1>

  // Compute 0.5 * diff^2
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x6xf32>
  %c0_5 = stablehlo.constant dense<5.000000e-01> : tensor<f32>
  %c0_5_bcast = "stablehlo.broadcast_in_dim"(%c0_5) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6xf32>
  %half_diff_sq = stablehlo.multiply %c0_5_bcast, %diff_sq : tensor<6x6xf32>

  // Compute abs_diff - 0.5
  %abs_diff_minus_half = stablehlo.subtract %abs_diff, %c0_5_bcast : tensor<6x6xf32>

