  %bias_broadcast = stablehlo.broadcast_in_dim %arg0 : tensor<7x1x1xf32> to tensor<16x7x1x1xf32> broadcast_dimensions = [1, 2, 3]
  %add_bias = stablehlo.add %mean, %bias_broadcast : tensor<16x7x1x1xf32>

