    }
  } : (tensor<16x7x1x1xf32>, tensor<f32>) -> tensor<16x1x1x1xf32>
  %logsumexp = stablehlo.log %sum_exp : tensor<16x1x1x1xf32>

  // sum over dims (2,3) (spatial dims), no keepdim
  %sum_final = stablehlo.reduce %logsumexp, %c0f {
