func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<6x7x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<16x6x8x8xf32>) -> tensor<16x1xf32> {
  // %arg0: bias parameter of shape [7,1,1]
  // %arg1: conv_transpose.weight of shape [6,7,3,3] (PyTorch ConvTranspose2d weight shape)
  // %arg2: conv_transpose.bias of shape [7]
  // %arg3: input tensor of shape [16,6,8,8]

  // Step 1: Perform ConvTranspose2d
  // PyTorch ConvTranspose2d weight shape: [in_channels, out_channels, kH, kW] = [6,7,3,3]
  // StableHLO convolution expects kernel shape: [o, i, ...]
  // So we need to transpose weight from [6,7,3,3] to [7,6,3,3]
  %weight_transposed = stablehlo.reshape %arg1 : tensor<6x7x3x3xf32> -> tensor<6x7x9xf32>
  %weight_reshaped = stablehlo.reshape %weight_transposed : tensor<6x7x9xf32> -> tensor<7x6x3x3xf32>

  // Convolution dimension numbers for ConvTranspose2d:
  // Input: [N, C_in, H_in, W_in] = [16,6,8,8]
  // Kernel: [C_in, C_out, kH, kW] in PyTorch, but StableHLO expects [o, i, ...] = [C_out, C_in, kH, kW]
  // We have weight_reshaped as [7,6,3,3] which matches [o,i,kH,kW]
  // For ConvTranspose2d, we use convolution with rhs_dilation = kernel dilation, lhs_dilation = 1, window_strides = 1
  // To implement ConvTranspose2d, we use convolution with rhs_dilation = 1, lhs_dilation = 1, window_strides = 1, but with padding and output shape adjusted.
  // However, StableHLO convolution is a forward convolution, so to do ConvTranspose2d, we swap lhs and rhs and use lhs_dilation.
  // The standard way to implement ConvTranspose2d is to do a convolution with lhs_dilation = stride, rhs_dilation = 1, and swap lhs and rhs.
  // Here stride=1, so lhs_dilation=1, so we can do convolution with lhs and rhs swapped and lhs_dilation=1.
  // So we do convolution(%arg3, %weight_reshaped) with lhs_dilation = 1, rhs_dilation = 1, window_strides = 1, padding = 1 (to get output size 10x10)
  // But PyTorch ConvTranspose2d with stride=1 and padding=0 outputs size = (input-1)*stride - 2*padding + kernel_size = (8-1)*1 - 0 + 3 = 10
  // So output spatial dims are 10x10
  // So we set padding = 1 on each side to get output 10x10

  // But since PyTorch ConvTranspose2d weight shape is [in_channels, out_channels, kH, kW], we must swap lhs and rhs in convolution:
  // lhs = input: [16,6,8,8]
  // rhs = weight: [7,6,3,3] but convolution expects rhs shape [o,i,kH,kW], so weight_reshaped is [7,6,3,3]
  // For ConvTranspose2d, we do convolution with lhs = input, rhs = weight_reshaped, lhs_dilation = 1, rhs_dilation = 1, window_strides = 1, padding = 1
  // dimension_numbers = [b, i, h, w] x [o, i, kh, kw] -> [b, o, h, w]

  // So dimension_numbers attribute:
  // input dims: b=0, i=1, h=2, w=3
  // kernel dims: o=0, i=1, kh=2, kw=3
  // output dims: b=0, o=1, h=2, w=3
  // #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>

  // Padding: 1 on all sides for height and width
  %padding = stablehlo.constant dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>
  %window_strides = array<i64: 1, 1>
  %lhs_dilation = array<i64: 1, 1>
  %rhs_dilation = array<i64: 1, 1>
  %feature_group_count = 1 : i64
  %batch_group_count = 1 : i64

  %conv = "stablehlo.convolution"(%arg3, %weight_reshaped) {
    window_strides = %window_strides,
    padding = %padding,
    lhs_dilation = %lhs_dilation,
    rhs_dilation = %rhs_dilation,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>,
    feature_group_count = %feature_group_count,
    batch_group_count = %batch_group_count
  } : (tensor<16x6x8x8xf32>, tensor<7x6x3x3xf32>) -> tensor<16x7x10x10xf32>

  // Step 2: Global average pooling over spatial dims (2,3)
  // mean over dims 2 and 3, keepdim=True
  // mean = sum / (dim2_size * dim3_size) = sum / 100
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %init_tensor = stablehlo.broadcast_in_dim %init_zero
    {broadcast_dimensions = array<i64: >} : () -> tensor<f32> // scalar zero for reduce init

  // Reduce sum over dims 2 and 3
  %sum_2 = "stablehlo.reduce"(%conv, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x7x10x10xf32>, tensor<f32>) -> tensor<16x7x10xf32>

