func.func @main(%bias: tensor<7x1x1xf32>, %conv_transpose_weight: tensor<6x7x3x3xf32>, %conv_transpose_bias: tensor<7xf32>, %input: tensor<16x6x8x8xf32>) -> tensor<16x1xf32> {
