  // Use lhs_dilation = strides of 1 (no dilation)
  // rhs_dilation = 1 (no dilation)
  // window_strides = 1 (stride 1)
  // padding = 1 on all sides (to keep output size 8x8)
  // dimension_numbers for NCHW: input [b, f, h, w], kernel [o, i, kh, kw], output [b, f, h, w]
