  %bias_broadcast_full = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x7x1x1xf32>) -> tensor<16x7x8x8xf32>

  %conv_bias_added = stablehlo.add %conv, %bias_broadcast_full : tensor<16x7x8x8xf32>

