  }) {dimensions = array<i64: 1>} : (tensor<16x7x1x1xf32>, tensor<f32>) -> tensor<16x1x1x1xf32>

  // Compute log(sum_exp)
  %log_sum_exp = stablehlo.log %sum_exp : tensor<16x1x1x1xf32>

  // Step 4: sum over dims (2,3) (spatial dims)
  // sum over dims 2 and 3 (both size 1, so sum is identity)
  // But to follow spec, do reduce sum over dims 2 and 3
  %init_zero_log = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_log = "stablehlo.reduce"(%log_sum_exp, %init_zero_log) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<16x1x1x1xf32>, tensor<f32>) -> tensor<16x1xf32>

  // Step 5: multiply by 10.0
  %const_10 = stablehlo.constant dense<10.0> : tensor<f32>
  %const_10_broadcast = "stablehlo.broadcast_in_dim"(%const_10) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>  // scalar broadcast no dims

