func.func @main(%arg0: tensor<7x1x1xf32>, %arg1: tensor<6x7x3x3xf32>, %arg2: tensor<7xf32>, %arg3: tensor<16x6x8x8xf32>) -> tensor<16x1xf32> {
  // Transpose conv: input %arg3 shape [16,6,8,8], weight %arg1 shape [6,7,3,3]
  // StableHLO convolution expects weight shape [out_channels, in_channels, H, W]
  // We have conv_transpose.weight shape [6,7,3,3], so we need to transpose to [7,6,3,3]
  %weight_transposed = "stablehlo.transpose"(%arg1) {permutation = dense<[1,0,2,3]> : tensor<4xi64>} : (tensor<6x7x3x3xf32>) -> tensor<7x6x3x3xf32>

  // ConvTranspose2d is a backward convolution with stride=1, padding=0, dilation=1, output_padding=0
  // We implement ConvTranspose2d as a convolution with the input and weight swapped and appropriate padding.
  // The output shape is [16,7,10,10] because:
  // output_height = (input_height - 1) * stride - 2*padding + dilation*(kernel_size-1) + output_padding + 1
  // Here stride=1, padding=0, dilation=1, output_padding=0
  // So output_height = (8-1)*1 - 0 + 1*(3-1) + 0 + 1 = 7 + 2 + 1 = 10
  // But PyTorch ConvTranspose2d default padding=0, stride=1, dilation=1, output_padding=0
  // So output shape is [16,7,10,10]

  // We use convolution with dimension_numbers:
  // input: NCHW = [16,6,8,8]
  // kernel: OIHW = [7,6,3,3]
  // output: NCHW = [16,7,10,10]
  // For conv_transpose, the convolution is done with input and kernel swapped and padding adjusted.
  // In StableHLO, conv_transpose can be done by convolution with the weight flipped spatially and swapped in/out channels.
  // We flip kernel spatial dims 2 and 3:
  %weight_flipped_1 = "stablehlo.reverse"(%weight_transposed) {dimensions = dense<[2]> : tensor<1xi64>} : (tensor<7x6x3x3xf32>) -> tensor<7x6x3x3xf32>
  %weight_flipped = "stablehlo.reverse"(%weight_flipped_1) {dimensions = dense<[3]> : tensor<1xi64>} : (tensor<7x6x3x3xf32>) -> tensor<7x6x3x3xf32>

  // Now do convolution with input %arg3 and weight_flipped, with padding = [kernel_size-1, kernel_size-1] = [2,2]
  // Because conv_transpose padding = 0 means conv padding = kernel_size - 1
  %conv = "stablehlo.convolution"(%arg3, %weight_flipped) {
    window_strides = dense<[1,1]> : tensor<2xi64>,
    padding = dense<[[2,2],[2,2]]> : tensor<2x2xi64>,
    dimension_numbers = {
      input_batch_dimension = 0,
      input_feature_dimension = 1,
      input_spatial_dimensions = dense<[2,3]> : tensor<2xi64>,
      kernel_output_feature_dimension = 0,
      kernel_input_feature_dimension = 1,
      kernel_spatial_dimensions = dense<[2,3]> : tensor<2xi64>,
      output_batch_dimension = 0,
      output_feature_dimension = 1,
      output_spatial_dimensions = dense<[2,3]> : tensor<2xi64>
    }
  } : (tensor<16x6x8x8xf32>, tensor<7x6x3x3xf32>) -> tensor<16x7x10x10xf32>

  // Global average pooling over spatial dims (2,3) keepdim=True
  %avg = "stablehlo.reduce"(%conv) ( {
    ^bb0(%a: f32, %b: f32):
      %sum = "stablehlo.add"(%a, %b) : (f32, f32) -> f32
      "stablehlo.return"(%sum) : (f32) -> ()
  }) {dimensions = dense<[2,3]> : tensor<2xi64>, keep_dims = true, initial_values = dense<0.0> : tensor<f32>} : (tensor<16x7x10x10xf32>) -> tensor<16x7x1x1xf32>

  // Add bias %arg0 shape [7,1,1] broadcasted to [16,7,1,1]
  // Broadcast bias to [16,7,1,1]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = dense<[1,2,3]> : tensor<3xi64>} : (tensor<7x1x1xf32>) -> tensor<16x7x1x1xf32>

  %add_bias = "stablehlo.add"(%avg, %bias_broadcast) : (tensor<16x7x1x1xf32>, tensor<16x7x1x1xf32>) -> tensor<16x7x1x1xf32>

  // LogSumExp over dim=1 keepdim=True
  // logsumexp(x) = log(sum(exp(x)))
  // Compute exp
  %exp = "stablehlo.exponential"(%add_bias) : (tensor<16x7x1x1xf32>) -> tensor<16x7x1x1xf32>

  // Sum over dim=1 keepdim=True
  %sum_exp = "stablehlo.reduce"(%exp) ( {
    ^bb0(%a: f32, %b: f32):
      %sum = "stablehlo.add"(%a, %b) : (f32, f32) -> f32
      "stablehlo.return"(%sum) : (f32) -> ()
  }) {dimensions = dense<[1]> : tensor<1xi64>, keep_dims = true, initial_values = dense<0.0> : tensor<f32>} : (tensor<16x7x1x1xf32>) -> tensor<16x1x1x1xf32>

  // Log of sum
  %logsumexp = "stablehlo.log"(%sum_exp) : (tensor<16x1x1x1xf32>) -> tensor<16x1x1x1xf32>

  // Sum over dims (2,3) (spatial dims) - these dims are size 1, so sum is identity but we do it to match spec
  %sum_final = "stablehlo.reduce"(%logsumexp) ( {
    ^bb0(%a: f32, %b: f32):
      %sum = "stablehlo.add"(%a, %b) : (f32, f32) -> f32
      "stablehlo.return"(%sum) : (f32) -> ()
  }) {dimensions = dense<[2,3]> : tensor<2xi64>, keep_dims = false, initial_values = dense<0.0> : tensor<f32>} : (tensor<16x1x1x1xf32>) -> tensor<16x1xf32>

  // Multiply by 10.0
