  // Compute x^2 elementwise
  %x_squared = "stablehlo.multiply"(%x, %x) : (tensor<3x8xf32>, tensor<3x8xf32>) -> tensor<3x8xf32>

  // Create zero constant for reduction init
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>

  // Reduce sum of squares along dimension 1 (columns), result shape: tensor<3xf32>
  %sum_squares = "stablehlo.reduce"(%x_squared, %c0) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<3x8xf32>, tensor<f32>) -> tensor<3xf32>

  // Compute sqrt of sum_squares to get L2 norm per row
  %l2_norm = "stablehlo.sqrt"(%sum_squares) : (tensor<3xf32>) -> tensor<3xf32>

  // Broadcast l2_norm to shape 3x8 for division
  %l2_norm_broadcast = "stablehlo.broadcast_in_dim"(%l2_norm) {broadcast_dimensions = array<i64: 0>} : (tensor<3xf32>) -> tensor<3x8xf32>

  // Divide x by broadcasted l2 norm to normalize rows
  %out = "stablehlo.divide"(%x, %l2_norm_broadcast) : (tensor<3x8xf32>, tensor<3x8xf32>) -> tensor<3x8xf32>

  return %out : tensor<3x8xf32>
}

