  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7x5x6x6xf32>
  %biased = stablehlo.add %conv, %bias_broadcast : tensor<6x7x5x6x6xf32>

  // Now apply torch.min along dim=2 (depth dimension of conv output)
  // Input shape: [6,7,5,6,6]
  // Reduce dimension: 2 (depth)
  // Result shape: [6,7,6,6]

  // stablehlo.reduce requires an init value and a body computing minimum
  %init = stablehlo.constant dense<0x7F800000> : tensor<f32>  // +inf for minimum init

