  %shifted = stablehlo.subtract %min, %max_broadcast : tensor<6x7x6x6xf32>

  // Step 3: exp(shifted)
  %exp = stablehlo.exponential %shifted : tensor<6x7x6x6xf32>

  // Step 4: sum exp along dim=1
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1}} : (tensor<6x7x6x6xf32>, tensor<f32>) -> tensor<6x1x6x6xf32>

  // Step 5: divide exp by sum_exp (broadcast sum_exp)
  %sum_exp_broadcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x6x6xf32>) -> tensor<6x7x6x6xf32>
  %softmax = stablehlo.divide %exp, %sum_exp_broadcast : tensor<6x7x6x6xf32>

  // Return result
  return %softmax : tensor<6x7x6x6xf32>
}

