  // dot_general with contracting dims: input last dim 1, weight first dim 0
  %x1 = "stablehlo.dot_general"(%input, %weight) {dot_dimension_numbers = #stablehlo.dot<lhs_batching_dimensions = [], rhs_batching_dimensions = [], lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // multiply by scale (7,) broadcasted to (6x7)
  %scale_broadcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x2 = stablehlo.multiply %x1, %scale_broadcast : tensor<6x7xf32>

  // add bias (7,) broadcasted to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x3 = stablehlo.add %x2, %bias_broadcast : tensor<6x7xf32>

  // batch norm forward (training mode):
  // compute mean over batch dim 0: mean shape (7,)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x3, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // divide mean by batch size 6.0
  %six_f32 = stablehlo.constant dense<6.0> : tensor<f32>
  %six_broadcast = "stablehlo.broadcast_in_dim"(%six_f32) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean_scaled = stablehlo.divide %mean, %six_broadcast : tensor<7xf32>

  // compute variance: mean of squared differences
  // (x3 - mean) broadcast mean to (6x7)
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %x3, %mean_broadcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>
  %zero_f32_var = stablehlo.constant dense<0.0> : tensor<f32>
  %variance = "stablehlo.reduce"(%diff_sq, %zero_f32_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>
  // divide variance sum by 6.0
  %variance_scaled = stablehlo.divide %variance, %six_broadcast : tensor<7xf32>

  // add eps (1e-5) to variance
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %variance_eps = stablehlo.add %variance_scaled, %eps_broadcast : tensor<7xf32>

  // compute rsqrt(variance + eps)
  %inv_std = stablehlo.rsqrt %variance_eps : tensor<7xf32>

  // normalize: (x3 - mean) * inv_std
  %inv_std_broadcast = "stablehlo.broadcast_in_dim"(%inv_std) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %normalized = stablehlo.multiply %diff, %inv_std_broadcast : tensor<6x7xf32>

  // scale and shift: normalized * bn_weight + bn_bias
  %bn_weight_broadcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %normalized, %bn_weight_broadcast : tensor<6x7xf32>
  %bn_bias_broadcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %out = stablehlo.add %scaled, %bn_bias_broadcast : tensor<6x7xf32>

  return %out : tensor<6x7xf32>
}

func.func @main(%scale: tensor<7xf32>, %weight: tensor<7x7xf32>, %bias: tensor<7xf32>, %bn_weight: tensor<7xf32>, %bn_bias: tensor<7xf32>, %input: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %x1 = gemm: input @ tensor<6x7xf32> dot weight @ tensor<7x7xf32> -> tensor<6x7xf32>
  // dot_general with contracting dims: input last dim 1, weight first dim 0
  %x1 = "stablehlo.dot_general"(%input, %weight) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]
    >
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // %x2 = multiply by scale (broadcast scale from [7] to [6x7])
  %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x2 = stablehlo.multiply %x1, %scale_bcast : tensor<6x7xf32>

  // %x3 = add bias (broadcast bias from [7] to [6x7])
  %bias_bcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %x3 = stablehlo.add %x2, %bias_bcast : tensor<6x7xf32>

  // BatchNorm1d forward (training mode):
  // Compute mean over batch dimension (dim 0)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x3, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // mean = mean / 6 (batch size)
  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %six_bcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>
  %mean_scaled = stablehlo.divide %mean, %six_bcast : tensor<7xf32>

  // Compute variance: mean of (x3 - mean)^2 over batch dim 0
  // Broadcast mean to [6x7]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_scaled) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %diff = stablehlo.subtract %x3, %mean_bcast : tensor<6x7xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<6x7xf32>

  %var_sum = "stablehlo.reduce"(%diff_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0>} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // variance = var_sum / 6
  %var = stablehlo.divide %var_sum, %six_bcast : tensor<7xf32>

  // eps = 1e-5 constant
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<7xf32>

  // var + eps
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<7xf32>

  // rsqrt(var + eps)
  %rsqrt_var_eps = stablehlo.rsqrt %var_eps : tensor<7xf32>

  // Normalize: (x3 - mean) * rsqrt_var_eps
  %norm = stablehlo.multiply %diff, "stablehlo.broadcast_in_dim"(%rsqrt_var_eps) {broadcast_dimensions = array<i64: 1>} : (tensor<6x7xf32>, tensor<7xf32>) -> tensor<6x7xf32>

  // Scale and shift: norm * bn_weight + bn_bias
  %bn_weight_bcast = "stablehlo.broadcast_in_dim"(%bn_weight) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %bn_bias_bcast = "stablehlo.broadcast_in_dim"(%bn_bias) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %scaled = stablehlo.multiply %norm, %bn_weight_bcast : tensor<6x7xf32>
  %shifted = stablehlo.add %scaled, %bn_bias_bcast : tensor<6x7xf32>

  return %shifted : tensor<6x7xf32>
}

