func.func @main(%arg0: tensor<7xf32>, %arg1: tensor<7x7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<7xf32>, %arg5: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // %arg5: input tensor (6x7)
  // %arg1: gemm.weight (7x7)
  // %arg2: gemm.bias (7)
  // %arg0: scale (7)
  // %arg3: bn.weight (7)
  // %arg4: bn.bias (7)

  // Step 1: gemm: x = %arg5 @ %arg1^T + %arg2
  // Note: PyTorch Linear uses weight shape (out_features, in_features)
  // Here %arg1 is (7x7), input is (6x7), so we do dot_general with contracting dims [1] and [1]
  // But to do x @ W^T, we transpose %arg1 to (7x7) -> (7x7) (transpose dims [1,0])
  %weight_t = stablehlo.transpose %arg1 : tensor<7x7xf32> to tensor<7x7xf32> {permutation = [1, 0]}
  %dot = stablehlo.dot_general %arg5, %weight_t {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [1]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_bcast = stablehlo.broadcast_in_dim %arg2 : tensor<7xf32> to tensor<6x7xf32> {broadcast_dimensions = [1]}
  %x1 = stablehlo.elementwise.add %dot, %bias_bcast : tensor<6x7xf32>

  // Step 2: multiply by scale (7)
  // Broadcast scale (7) to (6x7)
  %scale_bcast = stablehlo.broadcast_in_dim %arg0 : tensor<7xf32> to tensor<6x7xf32> {broadcast_dimensions = [1]}
  %x2 = stablehlo.elementwise.multiply %x1, %scale_bcast : tensor<6x7xf32>

  // Step 3: batch norm forward (training mode)
  // Compute mean over batch dimension (dim 0), result shape (7)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = stablehlo.reduce %x2, %zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.elementwise.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = [0]} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // Compute variance: mean of (x - mean)^2 over batch dim 0
  // Broadcast mean to (6x7)
  %mean_bcast = stablehlo.broadcast_in_dim %mean : tensor<7xf32> to tensor<6x7xf32> {broadcast_dimensions = [1]}
  %diff = stablehlo.elementwise.subtract %x2, %mean_bcast : tensor<6x7xf32>
  %diff_sq = stablehlo.elementwise.multiply %diff, %diff : tensor<6x7xf32>
  %var = stablehlo.reduce %diff_sq, %zero {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.elementwise.add %a, %b : tensor<f32>
      stablehlo.return %sum : tensor<f32>
  } {dimensions = [0]} : (tensor<6x7xf32>, tensor<f32>) -> tensor<7xf32>

  // Divide sums by batch size (6) to get mean and variance
  %batch_size = stablehlo.constant dense<6.0> : tensor<f32>
  %batch_size_bcast = stablehlo.broadcast_in_dim %batch_size : tensor<f32> to tensor<7xf32> {broadcast_dimensions = []}
  %mean_final = stablehlo.elementwise.divide %mean, %batch_size_bcast : tensor<7xf32>
  %var_final = stablehlo.elementwise.divide %var, %batch_size_bcast : tensor<7xf32>

  // Compute invstd = 1 / sqrt(var + eps)
  %eps = stablehlo.constant dense<1.00000001e-5> : tensor<f32>
  %var_eps = stablehlo.elementwise.add %var_final, %eps : tensor<7xf32>
  %sqrt_var = stablehlo.elementwise.sqrt %var_eps : tensor<7xf32>
  %invstd = stablehlo.elementwise.divide %batch_size, %sqrt_var : tensor<7xf32> // incorrect, fix below

  // Correction: invstd = 1 / sqrt(var + eps)
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_bcast = stablehlo.broadcast_in_dim %one : tensor<f32> to tensor<7xf32> {broadcast_dimensions = []}
  %invstd = stablehlo.elementwise.divide %one_bcast, %sqrt_var : tensor<7xf32>

  // Normalize: (x - mean) * invstd
  %invstd_bcast = stablehlo.broadcast_in_dim %invstd : tensor<7xf32> to tensor<6x7xf32> {broadcast_dimensions = [1]}
  %x_centered = stablehlo.elementwise.subtract %x2, %mean_bcast : tensor<6x7xf32>
  %x_norm = stablehlo.elementwise.multiply %x_centered, %invstd_bcast : tensor<6x7xf32>

  // Scale and shift with bn.weight and bn.bias
  // Broadcast bn.weight and bn.bias to (6x7)
  %bn_weight_bcast = stablehlo.broadcast_in_dim %arg3 : tensor<7xf32> to tensor<6x7xf32> {broadcast_dimensions = [1]}
  %bn_bias_bcast = stablehlo.broadcast_in_dim %arg4 : tensor<7xf32> to tensor<6x7xf32> {broadcast_dimensions = [1]}
  %x_scaled = stablehlo.elementwise.multiply %x_norm, %bn_weight_bcast : tensor<6x7xf32>
  %x_out = stablehlo.elementwise.add %x_scaled, %bn_bias_bcast : tensor<6x7xf32>

  func.return %x_out : tensor<6x7xf32>
