  }) {dimensions = dense<[1]> : tensor<1xi64>} : (tensor<6x7xf32>) -> tensor<6xf32>

  // Broadcast max_logits back to shape 6x7 for subtraction
  %max_logits_bcast = "stablehlo.broadcast_in_dim"(%max_logits) {broadcast_dimensions = dense<[0]> : tensor<1xi64>} : (tensor<6xf32>) -> tensor<6x7xf32>

