  %exp_logits = "stablehlo.exponential"(%logits_stable) : (tensor<6x7xf32>) -> tensor<6x7xf32>

  // Sum of exponentials over classes (dim=1)
  %sum_exp = "stablehlo.reduce"(%exp_logits) ({
    ^bb0(%a: f32, %b: f32):
      %c = "stablehlo.add"(%a, %b) : (f32, f32) -> f32
      "stablehlo.return"(%c) : (f32) -> ()
  }) {dimensions = dense<[1]> : tensor<1xi64>} : (tensor<6x7xf32>) -> tensor<6xf32>

  // Broadcast sum_exp back to shape 6x7 for division
  %sum_exp_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {broadcast_dimensions = dense<[0]> : tensor<1xi64>} : (tensor<6xf32>) -> tensor<6x7xf32>

