  %neg_log = "stablehlo.negate"(%log_target_probs) : (tensor<6xf32>) -> tensor<6xf32>

  // Sum over batch dimension to get total loss
  %loss_sum = "stablehlo.reduce"(%neg_log) ({
    ^bb0(%a: f32, %b: f32):
      %c = "stablehlo.add"(%a, %b) : (f32, f32) -> f32
      "stablehlo.return"(%c) : (f32) -> ()
  }) {dimensions = dense<[0]> : tensor<1xi64>} : (tensor<6xf32>) -> tensor<f32>

