func.func @main(%arg0: tensor<6x7xf32>, %arg1: tensor<6xi64>) -> tensor<f32> {
  // Cross entropy loss calculation:
  // input: %arg0 = predictions logits (6x7)
  // target: %arg1 = class indices (6)
  // Steps:
  // 1) Compute log_softmax of predictions along dim=1
  // 2) Gather log probabilities of the true classes
  // 3) Compute negative mean of these log probabilities

  // Step 1: Compute max logits per row for numerical stability
  %cst_neg_inf = stablehlo.constant dense<-inf> : tensor<f32>
  %max_init = stablehlo.broadcast_in_dim %cst_neg_inf : tensor<f32> to tensor<6x1xf32> {broadcast_dimensions = [0,1]}
  %max_logits = stablehlo.reduce %arg0, %max_init {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.maximum %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  } {dimensions = [1]} : (tensor<6x7xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>

  // Step 2: Subtract max logits for numerical stability
  %max_logits_bcast = stablehlo.broadcast_in_dim %max_logits : tensor<6x1xf32> to tensor<6x7xf32> {broadcast_dimensions = [0,1]}
  %logits_stable = stablehlo.subtract %arg0, %max_logits_bcast : tensor<6x7xf32>

  // Step 3: Exponentiate stable logits
  %exp_logits = stablehlo.exponential %logits_stable : tensor<6x7xf32>

  // Step 4: Sum exp logits along dim=1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_init = stablehlo.broadcast_in_dim %zero : tensor<f32> to tensor<6x1xf32> {broadcast_dimensions = [0,1]}
  %sum_exp = stablehlo.reduce %exp_logits, %sum_init {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  } {dimensions = [1]} : (tensor<6x7xf32>, tensor<6x1xf32>) -> tensor<6x1xf32>

  // Step 5: Compute log(sum_exp)
  %log_sum_exp = stablehlo.math.log %sum_exp : tensor<6x1xf32>

  // Step 6: Broadcast log_sum_exp to shape 6x7
  %log_sum_exp_bcast = stablehlo.broadcast_in_dim %log_sum_exp : tensor<6x1xf32> to tensor<6x7xf32> {broadcast_dimensions = [0,1]}

  // Step 7: Compute log_softmax = logits_stable - log_sum_exp_bcast
  %log_softmax = stablehlo.subtract %logits_stable, %log_sum_exp_bcast : tensor<6x7xf32>

  // Step 8: Gather log probabilities of true classes
  // We need to gather log_softmax[i, target[i]] for i in [0..5]
  // Create iota for batch indices
  %iota_6 = stablehlo.iota : tensor<6xi64> {iota_dimension = 0}

  // Convert targets to i64 (already i64)
  %targets = %arg1

  // We will gather by flattening log_softmax to 1D and computing indices = i * 7 + target[i]
  %seven = stablehlo.constant dense<7> : tensor<i64>
  %i_mul_7 = stablehlo.multiply %iota_6, %seven : tensor<6xi64>
  %indices = stablehlo.add %i_mul_7, %targets : tensor<6xi64>

  // Flatten log_softmax to 1D tensor<42xf32>
  %log_softmax_flat = stablehlo.reshape %log_softmax : tensor<6x7xf32> to tensor<42xf32>

  // Gather elements at indices
  // StableHLO does not have a gather op, but we can do a reduce with compare to select elements
  // Instead, we can do a select with compare for each index, but that is complicated.
  // Instead, we can do a loop with reduce to sum only the matching index.
  // But since we have no loops, we can do a trick:
  // Create a 42x6 mask where mask[i,j] = (i == indices[j])
  // Then multiply log_softmax_flat[i] * mask[i,j] and reduce sum over i to get the j-th gathered element.

  // Create iota for 42 elements
  %iota_42 = stablehlo.iota : tensor<42xi64> {iota_dimension = 0}

  // Broadcast iota_42 to 42x6
  %iota_42_bcast = stablehlo.broadcast_in_dim %iota_42 : tensor<42xi64> to tensor<42x6xi64> {broadcast_dimensions = [0]}
  // Broadcast indices to 42x6
  %indices_bcast = stablehlo.broadcast_in_dim %indices : tensor<6xi64> to tensor<42x6xi64> {broadcast_dimensions = [1]}

  // Compare iota_42_bcast == indices_bcast -> mask 42x6xi1
  %mask = stablehlo.compare %iota_42_bcast, %indices_bcast {comparison_direction = #stablehlo<comparison_direction EQ>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<42x6xi64>, tensor<42x6xi64>) -> tensor<42x6xi1>

  // Convert mask to f32
  %mask_f32 = stablehlo.convert %mask : tensor<42x6xi1> to tensor<42x6xf32>

  // Broadcast log_softmax_flat 42xf32 to 42x6xf32
  %log_softmax_flat_bcast = stablehlo.broadcast_in_dim %log_softmax_flat : tensor<42xf32> to tensor<42x6xf32> {broadcast_dimensions = [0]}

  // Multiply log_softmax_flat_bcast * mask_f32
  %masked = stablehlo.multiply %log_softmax_flat_bcast, %mask_f32 : tensor<42x6xf32>

  // Reduce sum over dimension 0 (42) to get gathered log probabilities per batch element (6)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_init_6 = stablehlo.broadcast_in_dim %zero_f32 : tensor<f32> to tensor<6xf32> {broadcast_dimensions = [0]}
  %gathered_log_probs = stablehlo.reduce %masked, %sum_init_6 {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  } {dimensions = [0]} : (tensor<42x6xf32>, tensor<6xf32>) -> tensor<6xf32>

  // Step 9: Compute negative log likelihood = - gathered_log_probs
  %neg_log_probs = stablehlo.negate %gathered_log_probs : tensor<6xf32>

  // Step 10: Compute mean over batch dimension (6)
  %sum_init_scalar = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_neg_log_probs = stablehlo.reduce %neg_log_probs, %sum_init_scalar {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      stablehlo.return %c : tensor<f32>
  } {dimensions = [0]} : (tensor<6xf32>, tensor<f32>) -> tensor<f32>

  %six = stablehlo.constant dense<6.0> : tensor<f32>
  %mean_loss = stablehlo.divide %sum_neg_log_probs, %six : tensor<f32>

  stablehlo.return %mean_loss : tensor<f32>
}

