func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x6x4x4xf32> {
  // %arg0 = conv.weight: [out_channels=6, in_channels=7, kernel_h=3, kernel_w=3]
  // %arg1 = conv.bias: [out_channels=6]
  // %arg2 = input: [batch=6, in_channels=7, height=6, width=6]

  // 1) Convolution
  // dimension_numbers = [b, f, h, w] x [o, i, kh, kw] -> [b, f, ho, wo]
  // batch=0, feature=1, spatial=2,3 for input
  // output batch=0, feature=1, spatial=2,3
  // window_strides=1, padding=0, dilation=1, groups=1
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 2, 3]x[o, i, 2, 3]->[b, f, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // 2) Add bias: broadcast bias from [6] to [6x6x4x4]
  // Broadcast bias on feature dimension (dim=1)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<6xf32>) -> tensor<6x6x1x1xf32>
  // Broadcast to full spatial dims 4x4
  %bias_broadcast_full = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x6x1x1xf32>) -> tensor<6x6x4x4xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast_full : tensor<6x6x4x4xf32>

  // 3) InstanceNorm2d forward (training mode)
  // InstanceNorm normalizes per-sample, per-channel over spatial dims (H,W)
  // Compute mean over dims 2,3 (spatial dims)
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<f32> // dummy init for reduce
  %mean = "stablehlo.reduce"(%conv_bias, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // Compute divisor = H*W = 4*4=16 as float constant
  %divisor = stablehlo.constant dense<16.0> : tensor<f32>
  // Broadcast divisor to mean shape [6x6]
  // mean shape is [6x6], no broadcast needed for division
  %mean_div = stablehlo.divide %mean, %divisor : tensor<6x6xf32>

  // Broadcast mean to [6x6x4x4] for subtraction
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x1x1xf32>
  %mean_broadcast_full = "stablehlo.broadcast_in_dim"(%mean_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x6x1x1xf32>) -> tensor<6x6x4x4xf32>

  // Subtract mean
  %x_centered = stablehlo.subtract %conv_bias, %mean_broadcast_full : tensor<6x6x4x4xf32>

  // Compute variance: mean of squared differences
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x6x4x4xf32>
  %var_sum = "stablehlo.reduce"(%x_centered_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>
  %var = stablehlo.divide %var_sum, %divisor : tensor<6x6xf32>

  // Add epsilon for numerical stability (epsilon=1e-5)
  %epsilon = stablehlo.constant dense<0.00001> : tensor<f32>
  %var_eps = stablehlo.add %var, %epsilon : tensor<6x6xf32>

  // sqrt(variance + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x6xf32>

  // Broadcast stddev to [6x6x4x4]
  %stddev_broadcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x1x1xf32>
  %stddev_broadcast_full = "stablehlo.broadcast_in_dim"(%stddev_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x6x1x1xf32>) -> tensor<6x6x4x4xf32>

  // Normalize: (x - mean) / stddev
  %x_norm = stablehlo.divide %x_centered, %stddev_broadcast_full : tensor<6x6x4x4xf32>

  // 4) Divide by constant 2.0
  %const_two = stablehlo.constant dense<2.0> : tensor<f32>
  // Broadcast 2.0 to output shape [6x6x4x4]
  %const_two_broadcast = "stablehlo.broadcast_in_dim"(%const_two) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %output = stablehlo.divide %x_norm, %const_two_broadcast : tensor<6x6x4x4xf32>

  return %output : tensor<6x6x4x4xf32>
}

