func.func @main(%arg0: tensor<6x7x3x3xf32>, %arg1: tensor<6xf32>, %arg2: tensor<6x7x6x6xf32>) -> tensor<6x6x4x4xf32> {
  // %arg0: conv.weight (6 out_channels, 7 in_channels, 3x3 kernel)
  // %arg1: conv.bias (6 out_channels)
  // %arg2: input tensor (batch=6, in_channels=7, height=6, width=6)

  // Perform convolution: output shape = [6, 6, 4, 4]
  // dimension_numbers format: #stablehlo.conv<[b, i, h, w]x[o, i, kh, kw]->[b, o, oh, ow]>
  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, i, 2, 3]x[o, i, 2, 3]->[b, o, 2, 3]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Add bias: broadcast bias from [6] to [6,6,4,4] on feature dimension (dim=1)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = dense<[1]> : tensor<1xi64>, output_shape = tensor<6x6x4x4xf32>} : (tensor<6xf32>) -> tensor<6x6x4x4xf32>
  %conv_bias = "stablehlo.add"(%conv, %bias_broadcast) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

  // InstanceNorm2d forward (training mode):
  // For each sample and channel, compute mean and variance over spatial dims (4x4)
  // mean = reduce mean over dims [2,3]
  %init_zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %init_zero_tensor = "stablehlo.broadcast_in_dim"(%init_zero) {broadcast_dimensions = dense<> : tensor<0xi64>, output_shape = tensor<6x6xf32>} : (tensor<f32>) -> tensor<6x6xf32>

  // Sum over spatial dims 2 and 3
  %sum = "stablehlo.reduce"(%conv_bias, %init_zero_tensor) ( {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = dense<[2, 3]> : tensor<2xi64>} : (tensor<6x6x4x4xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Compute mean = sum / 16 (4*4=16)
  %const_16 = "stablehlo.constant"() {value = dense<16.0> : tensor<f32>} : () -> tensor<f32>
  %const_16_bcast = "stablehlo.broadcast_in_dim"(%const_16) {broadcast_dimensions = dense<> : tensor<0xi64>, output_shape = tensor<6x6xf32>} : (tensor<f32>) -> tensor<6x6xf32>
  %mean = "stablehlo.divide"(%sum, %const_16_bcast) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // Compute variance:
  // variance = mean of (x - mean)^2 over spatial dims
  // First broadcast mean to shape [6,6,4,4]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = dense<[0,1]> : tensor<2xi64>, output_shape = tensor<6x6x4x4xf32>} : (tensor<6x6xf32>) -> tensor<6x6x4x4xf32>

  // Compute (x - mean)
  %diff = "stablehlo.subtract"(%conv_bias, %mean_bcast) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

  // Square (x - mean)
  %diff_sq = "stablehlo.multiply"(%diff, %diff) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

  // Sum squared differences over spatial dims [2,3]
  %init_zero_var = "stablehlo.broadcast_in_dim"(%init_zero) {broadcast_dimensions = dense<> : tensor<0xi64>, output_shape = tensor<6x6xf32>} : (tensor<f32>) -> tensor<6x6xf32>
  %sum_sq = "stablehlo.reduce"(%diff_sq, %init_zero_var) ( {
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = "stablehlo.add"(%a, %b) : (tensor<f32>, tensor<f32>) -> tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = dense<[2, 3]> : tensor<2xi64>} : (tensor<6x6x4x4xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // variance = sum_sq / 16
  %variance = "stablehlo.divide"(%sum_sq, %const_16_bcast) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // epsilon for numerical stability
  %epsilon = "stablehlo.constant"() {value = dense<1e-5> : tensor<f32>} : () -> tensor<f32>
  %epsilon_bcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = dense<> : tensor<0xi64>, output_shape = tensor<6x6xf32>} : (tensor<f32>) -> tensor<6x6xf32>

  // variance + epsilon
  %var_eps = "stablehlo.add"(%variance, %epsilon_bcast) : (tensor<6x6xf32>, tensor<6x6xf32>) -> tensor<6x6xf32>

  // rsqrt(variance + epsilon)
  %rsqrt = "stablehlo.rsqrt"(%var_eps) : (tensor<6x6xf32>) -> tensor<6x6xf32>

  // Broadcast rsqrt to [6,6,4,4]
  %rsqrt_bcast = "stablehlo.broadcast_in_dim"(%rsqrt) {broadcast_dimensions = dense<[0,1]> : tensor<2xi64>, output_shape = tensor<6x6x4x4xf32>} : (tensor<6x6xf32>) -> tensor<6x6x4x4xf32>

  // Normalize: (x - mean) * rsqrt
  %norm = "stablehlo.multiply"(%diff, %rsqrt_bcast) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

  // Divide by constant 2.0 (divide_by)
  %const_divide_by = "stablehlo.constant"() {value = dense<2.0> : tensor<f32>} : () -> tensor<f32>
  %const_divide_by_bcast = "stablehlo.broadcast_in_dim"(%const_divide_by) {broadcast_dimensions = dense<> : tensor<0xi64>, output_shape = tensor<6x6x4x4xf32>} : (tensor<f32>) -> tensor<6x6x4x4xf32>
  %output = "stablehlo.divide"(%norm, %const_divide_by_bcast) : (tensor<6x6x4x4xf32>, tensor<6x6x4x4xf32>) -> tensor<6x6x4x4xf32>

  return %output : tensor<6x6x4x4xf32>
}

func.func @main(%conv_weight: tensor<6x7x3x3xf32>, %conv_bias: tensor<6xf32>, %input: tensor<6x7x6x6xf32>) -> tensor<6x6x4x4xf32> {
  // Convolution:
  // conv.weight: [6,7,3,3], input: [6,7,6,6], output: [6,6,4,4]
  // PyTorch Conv2d default stride=1, padding=0, dilation=1
  // dimension_numbers: input [b,f,0,1], kernel [o,i,0,1], output [b,f,0,1]
  %conv_out = "stablehlo.convolution"(%input, %conv_weight) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<6x7x3x3xf32>) -> tensor<6x6x4x4xf32>

  // Add bias: broadcast bias from [6] to [6x6x4x4]
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%conv_bias) {broadcast_dimensions = array<i64: 0>} : (tensor<6xf32>) -> tensor<6x1x1x1xf32>
  %bias_broadcast_reshaped = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x1x1x1xf32>) -> tensor<6x6x4x4xf32>
  %conv_out_biased = stablehlo.add %conv_out, %bias_broadcast_reshaped : tensor<6x6x4x4xf32>

  // InstanceNorm2d:
  // For each sample (b) and channel (c), normalize over spatial dims (h,w)
  // mean = reduce over dims [2,3] (h,w)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%conv_out_biased, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // Compute divisor for mean: 4*4=16 as f32 constant
  %const_16 = stablehlo.constant dense<16.0> : tensor<f32>
  // Broadcast const_16 to [6x6] for division
  %const_16_bcast = "stablehlo.broadcast_in_dim"(%const_16) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6xf32> // Actually no broadcast needed, scalar divides each element

  // mean = sum / 16
  %mean_div = stablehlo.divide %mean, %const_16 : tensor<6x6xf32>

  // Broadcast mean to [6x6x4x4] for subtraction
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x4x4xf32>

  // x_centered = x - mean
  %x_centered = stablehlo.subtract %conv_out_biased, %mean_bcast : tensor<6x6x4x4xf32>

  // Compute variance:
  // var = reduce over dims [2,3] of (x_centered^2)
  %x_centered_sq = stablehlo.multiply %x_centered, %x_centered : tensor<6x6x4x4xf32>
  %var_sum = "stablehlo.reduce"(%x_centered_sq, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // var = var_sum / 16
  %var = stablehlo.divide %var_sum, %const_16 : tensor<6x6xf32>

  // Add epsilon for numerical stability: epsilon=1e-5
  %epsilon = stablehlo.constant dense<0.00001> : tensor<f32>
  %epsilon_bcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6xf32> // scalar broadcast not needed

  %var_eps = stablehlo.add %var, %epsilon : tensor<6x6xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<6x6xf32>

  // Broadcast stddev to [6x6x4x4]
  %stddev_bcast = "stablehlo.broadcast_in_dim"(%stddev) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<6x6xf32>) -> tensor<6x6x4x4xf32>

  // Normalize: x_norm = x_centered / stddev
  %x_norm = stablehlo.divide %x_centered, %stddev_bcast : tensor<6x6x4x4xf32>

  // Divide by constant divide_by=2.0
  %divide_by = stablehlo.constant dense<2.0> : tensor<f32>
  %divide_by_bcast = "stablehlo.broadcast_in_dim"(%divide_by) {broadcast_dimensions = array<i64: } : (tensor<f32>) -> tensor<6x6x4x4xf32> // scalar broadcast not needed

  %output = stablehlo.divide %x_norm, %divide_by : tensor<6x6x4x4xf32>

  return %output : tensor<6x6x4x4xf32>
}

