func.func @main(%arg0: tensor<3x16x3x3x3xf32>, %arg1: tensor<16xf32>, %arg2: tensor<6x3x16x7x7xf32>) -> tensor<6x16x1x1x1xf32> {
  // Transpose weight from [3,16,3,3,3] to [16,3,3,3,3]
  %weight_transposed = stablehlo.transpose %arg0 : tensor<3x16x3x3x3xf32> to tensor<16x3x3x3x3xf32> {permutation = [1, 0, 2, 3, 4]}

  // Attributes for convolution
  %window_strides = stablehlo.constant dense<1, 1, 1> : tensor<3xi64>
