  // to (out_channels=16, in_channels=3, D=3, H=3, W=3)
  %w_transposed = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<3x16x3x3x3xf32>) -> tensor<16x3x3x3x3xf32>

  // Perform ConvTranspose3d as a convolution with rhs_dilation=stride=2, padding=1
