func.func @main(%arg0: tensor<3x16x3x3x3xf32>, %arg1: tensor<16xf32>, %arg2: tensor<6x3x16x7x7xf32>) -> tensor<6x16x1x1x1xf32> {
  // %arg0: conv_transpose.weight (3,16,3,3,3)
  // %arg1: conv_transpose.bias (16)
  // %arg2: input (6,3,16,7,7)

  // We want to perform ConvTranspose3d with:
  // in_channels=3, out_channels=16, kernel=3, stride=2, padding=1
  // The input shape is (batch=6, channels=3, depth=16, height=7, width=7)
  // The weight shape is (in_channels=3, out_channels=16, kernel=3,3,3)
  // But stablehlo.convolution expects kernel shape [o,i,...], so we must transpose weight dims.

  // Transpose weight from (3,16,3,3,3) to (16,3,3,3,3)
  %weight_transposed = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0, 2, 3, 4>} : (tensor<3x16x3x3x3xf32>) -> tensor<16x3x3x3x3xf32>

