  // Define padding tensor: 3 spatial dims, each with [1,1]
  %padding = dense<[[1, 1], [1, 1], [1, 1]]> : tensor<3x2xi64>

  // Perform convolution with lhs_dilation=stride=2, rhs_dilation=1
  %conv = "stablehlo.convolution"(%arg2, %weight_transposed) {
    window_strides = array<i64: 1, 1, 1>,
    padding = %padding,
    lhs_dilation = array<i64: 2, 2, 2>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = %dim_numbers,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x3x16x7x7xf32>, tensor<16x3x3x3x3xf32>) -> tensor<6x16x33x15x15xf32>

  // Add bias: broadcast bias %arg1 (16) to conv output shape (6,16,33,15,15)
  // Broadcast bias to shape (1,16,1,1,1)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<1x16x1x1x1xf32>

