  }) {dimensions = array<i64 2, 3, 4>} : (tensor<6x16x16x7x7xf32>, tensor<f32>) -> tensor<6x16xf32>

  // Divide sum by 784.0 to get mean
  %divisor = "stablehlo.constant"() {value = dense<784.0> : tensor<f32>} : () -> tensor<f32>
  %divisor_broadcast = "stablehlo.broadcast_in_dim"(%divisor) {broadcast_dimensions = array<i64 >} : (tensor<f32>) -> tensor<6x16xf32>
  %mean = "stablehlo.divide"(%sum, %divisor_broadcast) : (tensor<6x16xf32>, tensor<6x16xf32>) -> tensor<6x16xf32>

  // Reshape mean from (6,16) to (6,16,1,1,1)
  %mean_reshaped = "stablehlo.reshape"(%mean) : (tensor<6x16xf32>) -> tensor<6x16x1x1x1xf32>

  // Clamp output between 0 and 1
  %zero_clamp = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %one_clamp = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %zero_broadcast = "stablehlo.broadcast_in_dim"(%zero_clamp) {broadcast_dimensions = array<i64 0, 1, 2, 3, 4>} : (tensor<f32>) -> tensor<6x16x1x1x1xf32>
  %one_broadcast = "stablehlo.broadcast_in_dim"(%one_clamp) {broadcast_dimensions = array<i64 0, 1, 2, 3, 4>} : (tensor<f32>) -> tensor<6x16x1x1x1xf32>
  %clamped_min = "stablehlo.maximum"(%mean_reshaped, %zero_broadcast) : (tensor<6x16x1x1x1xf32>, tensor<6x16x1x1x1xf32>) -> tensor<6x16x1x1x1xf32>
  %clamped = "stablehlo.minimum"(%clamped_min, %one_broadcast) : (tensor<6x16x1x1x1xf32>, tensor<6x16x1x1x1xf32>) -> tensor<6x16x1x1x1xf32>

  return %clamped : tensor<6x16x1x1x1xf32>
}

func.func @main(%arg0: tensor<3x16x3x3x3xf32>, %arg1: tensor<16xf32>, %arg2: tensor<6x3x16x7x7xf32>) -> tensor<6x16x1x1x1xf32> {
