func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x7xf32> {
  // Compute gemm: %arg2 * %arg0^T + %arg1
  // %arg0 is weight: tensor<7x7xf32>, need to transpose to 7x7 for dot_general contracting dims
  %t0 = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>
  // dot_general: lhs %arg2 (6x7), rhs %t0 (7x7), contract lhs dim 1 and rhs dim 0
  %t1 = "stablehlo.dot_general"(%arg2, %t0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>
  // add bias %arg1 broadcasted to (6x7)
  %t2 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %t3 = stablehlo.add %t1, %t2 : tensor<6x7xf32>

  // Save original gemm output for residual add
  %original = %t3 : tensor<6x7xf32>

  // Apply sigmoid: sigmoid(x) = 1 / (1 + exp(-x))
  %neg = stablehlo.negate %t3 : tensor<6x7xf32>
