func.func @main(%arg0: tensor<7x7xf32>, %arg1: tensor<7xf32>, %arg2: tensor<6x7xf32>) -> tensor<6x1xf32> {
  // Linear layer: y = x * W^T + b
  // %arg0: weight (7x7), %arg1: bias (7), %arg2: input (6x7)
  // We want: (6x7) dot (7x7)^T = (6x7) dot (7x7) -> (6x7)
  // So transpose weight to (7x7) (actually same shape), but we want to contract input dim 1 with weight dim 1
  // We'll do dot_general with lhs_contracting_dimensions=[1], rhs_contracting_dimensions=[1]
  // But weight is (7x7), input is (6x7), so to do x * W^T, we transpose weight first

  // Transpose weight to get W^T: (7x7) -> (7x7) (swap dims 0 and 1)
  %weight_t = "stablehlo.transpose"(%arg0) {permutation = array<i64: 1, 0>} : (tensor<7x7xf32>) -> tensor<7x7xf32>

  // Dot product: (6x7) dot (7x7) -> (6x7)
  %dot = "stablehlo.dot_general"(%arg2, %weight_t) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<6x7xf32>, tensor<7x7xf32>) -> tensor<6x7xf32>

  // Add bias: broadcast bias (7) to (6x7)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<7xf32>) -> tensor<6x7xf32>
  %linear_out = stablehlo.add %dot, %bias_broadcast : tensor<6x7xf32>

  // sum over dim=1 keepdim=True: reduce sum over dim 1 -> shape (6x1)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%linear_out, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
