func.func @main(%bias: tensor<16xf32>, %gemm_weight: tensor<16x16xf32>, %gemm_bias: tensor<16xf32>, %groupnorm_weight: tensor<16xf32>, %groupnorm_bias: tensor<16xf32>, %input: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // %x = gemm(input, gemm_weight) + gemm_bias
  %x_gemm = "stablehlo.dot_general"(%input, %gemm_weight) {
    dot_dimension_numbers = #stablehlo.dot<
      lhs_batching_dimensions = [],
      rhs_batching_dimensions = [],
      lhs_contracting_dimensions = [1],
      rhs_contracting_dimensions = [0]>
  } : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>
  %x = stablehlo.add %x_gemm, %gemm_bias : tensor<16x16xf32>

  // x = x + bias (broadcast bias from [16] to [16x16])
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %x_bias = stablehlo.add %x, %bias_broadcast : tensor<16x16xf32>

  // Hardtanh: clamp x between 0 and 1
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %zero_bcast = "stablehlo.broadcast_in_dim"(%zero) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x16xf32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x16xf32>
  %x_clamped_low = stablehlo.maximum %x_bias, %zero_bcast : tensor<16x16xf32>
  %x_hardtanh = stablehlo.minimum %x_clamped_low, %one_bcast : tensor<16x16xf32>

  // Mish activation: x * tanh(ln(1 + exp(x)))
  %x_exp = stablehlo.exponential %x_hardtanh : tensor<16x16xf32>
  %one_bcast = "stablehlo.broadcast_in_dim"(%one) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16x16xf32> // reuse one_bcast
  %x_exp_plus_one = stablehlo.add %x_exp, %one_bcast : tensor<16x16xf32>
  %x_log = stablehlo.log %x_exp_plus_one : tensor<16x16xf32>
  %x_tanh = stablehlo.tanh %x_log : tensor<16x16xf32>
  %x_mish = stablehlo.multiply %x_hardtanh, %x_tanh : tensor<16x16xf32>

  // GroupNorm:
  // input: x_mish [16x16], num_groups=16, so each group has 1 channel (channel dim = 1)
  // GroupNorm per group: normalize over group channels (here each group is 1 channel), so mean and var over group channels dimension only
  // But since group size=1, mean and var are just the value itself, so output = weight * (x - mean) / sqrt(var + eps) + bias
  // However, we must implement the general formula:
  // mean = reduce_mean over group channels dimension (dim=1)
  // var = reduce_mean of (x - mean)^2 over group channels dimension (dim=1)
  // normalized = (x - mean) / sqrt(var + eps)
  // output = normalized * weight + bias

  // Compute mean over dim=1 (channels)
  %init_zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%x_mish, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>

  // mean /= 16 (channels)
  %channels_count = stablehlo.constant dense<16.0> : tensor<f32>
  %channels_count_bcast = "stablehlo.broadcast_in_dim"(%channels_count) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16xf32>
  %mean_div = stablehlo.divide %mean, %channels_count_bcast : tensor<16xf32>

  // Broadcast mean to [16x16]
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean_div) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>

  // Compute variance: reduce_mean((x - mean)^2) over dim=1
  %x_minus_mean = stablehlo.subtract %x_mish, %mean_bcast : tensor<16x16xf32>
  %x_minus_mean_sq = stablehlo.multiply %x_minus_mean, %x_minus_mean : tensor<16x16xf32>
  %var_sum = "stablehlo.reduce"(%x_minus_mean_sq, %init_zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<16x16xf32>, tensor<f32>) -> tensor<16xf32>
  %var = stablehlo.divide %var_sum, %channels_count_bcast : tensor<16xf32>

  // Broadcast var to [16x16]
  %var_bcast = "stablehlo.broadcast_in_dim"(%var) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x16xf32>

  // eps = 1e-5
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16x16xf32>

  // var + eps
  %var_eps = stablehlo.add %var_bcast, %eps_bcast : tensor<16x16xf32>

  // rsqrt(var + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // normalized = (x - mean) * inv_std
  %normalized = stablehlo.multiply %x_minus_mean, %inv_std : tensor<16x16xf32>

  // Broadcast groupnorm_weight and groupnorm_bias from [16] to [16x16]
