  // StableHLO convolution expects kernel shape [out_features, in_features, spatial...]
  // So we must transpose conv_transpose_weight from [6,7,3,3] to [7,6,3,3]
  // We'll do this by reshaping and transposing.

  // Reshape conv_transpose_weight to 4D tensor (6,7,3,3) -> (6,7,3*3)
  %w_reshape = stablehlo.reshape %conv_transpose_weight : (tensor<6x7x3x3xf32>) -> tensor<6x7x9xf32>
  // Transpose to (7,6,9)
  %w_transpose = "stablehlo.transpose"(%conv_transpose_weight) {permutation = array<i64: 1, 0, 2, 3>} : (tensor<6x7x3x3xf32>) -> tensor<7x6x3x3xf32>

  // Use %w_transpose directly as kernel with shape [7,6,3,3]

  // Convolution parameters for ConvTranspose:
  // lhs_dilation = stride = [2,2]
  // padding = [kernel_size - 1 - padding, kernel_size - 1 - padding] = [3-1-1, 3-1-1] = [1,1]
  // output_padding handled by adjusting padding or output shape, but StableHLO convolution does not have output_padding attribute.
  // The output shape is computed automatically.
  // window_strides = [1,1]
  // rhs_dilation = [1,1]
  // dimension_numbers = [b, f, 0, 1] x [o, i, 0, 1] -> [b, f, 0, 1]
  // feature_group_count = 1
  // batch_group_count = 1

  %conv = "stablehlo.convolution"(%input, %w_transpose) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<16x6x7x7xf32>, tensor<7x6x3x3xf32>) -> tensor<16x7x14x14xf32>

  // Step 2: torch.min(x, dim=1, keepdim=True)[0]
  // Reduce min along dim=1 (channel dimension), keepdim=True means output shape [16x1x14x14]
  // Use stablehlo.reduce with init = +inf and min operation

  %inf = stablehlo.constant dense<0x7F800000> : tensor<f32>  // +inf scalar
  %inf_tensor = stablehlo.broadcast_in_dim %inf {broadcast_dimensions = array<i64: {}} : (tensor<f32>) -> tensor<16x7x14x14xf32>
  %min_reduce = "stablehlo.reduce"(%conv, %inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %min = stablehlo.minimum %a, %b : tensor<f32>
      "stablehlo.return"(%min) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1}} : (tensor<16x7x14x14xf32>, tensor<f32>) -> tensor<16x14x14xf32>

  // Add back the reduced dimension as size 1 to keepdim=True
  %min_keepdim = stablehlo.reshape %min_reduce : (tensor<16x14x14xf32>) -> tensor<16x1x14x14xf32>

  // Step 3: torch.sum(x, dim=2, keepdim=True)
  // Sum along height dimension (dim=2), keepdim=True
  // Use stablehlo.reduce with init=0 and add operation

  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_reduce = "stablehlo.reduce"(%min_keepdim, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2}} : (tensor<16x1x14x14xf32>, tensor<f32>) -> tensor<16x1x1x14xf32>

  // Step 4: GELU activation
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Implement GELU elementwise

  %sqrt2 = stablehlo.constant dense<1.4142135381698608> : tensor<f32>  // sqrt(2)
  %sqrt2_broadcast = stablehlo.broadcast_in_dim %sqrt2 {broadcast_dimensions = array<i64: {}} : (tensor<f32>) -> tensor<16x1x1x14xf32>
  %x_div_sqrt2 = stablehlo.divide %sum_reduce, %sqrt2_broadcast : tensor<16x1x1x14xf32>
  %erf = chlo.erf %x_div_sqrt2 : tensor<16x1x1x14xf32> -> tensor<16x1x1x14xf32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>
  %one_broadcast = stablehlo.broadcast_in_dim %one {broadcast_dimensions = array<i64: {}} : (tensor<f32>) -> tensor<16x1x1x14xf32>
  %one_plus_erf = stablehlo.add %one_broadcast, %erf : tensor<16x1x1x14xf32>
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %half_broadcast = stablehlo.broadcast_in_dim %half {broadcast_dimensions = array<i64: {}} : (tensor<f32>) -> tensor<16x1x1x14xf32>
  %mul1 = stablehlo.multiply %half_broadcast, %sum_reduce : tensor<16x1x1x14xf32>
  %gelu = stablehlo.multiply %mul1, %one_plus_erf : tensor<16x1x1x14xf32>

  // Step 5: Add bias (shape 1x1x1xf32) broadcasted to output shape (16x1x1x14)
  // Broadcast bias to (16x1x1x14)
  %bias_broadcast = "stablehlo.broadcast_in_dim"(%bias) {broadcast_dimensions = array<i64: 3>} : (tensor<1x1x1xf32>) -> tensor<16x1x1x14xf32>

  %result = stablehlo.add %gelu, %bias_broadcast : tensor<16x1x1x14xf32>

  return %result : tensor<16x1x1x14xf32>
}

