  // Reduce minimum along channel dimension (dim=1), keepdim=True
  // stablehlo.reduce with initial value +inf

  %inf = stablehlo.constant dense<0x7F800000> : tensor<f32>  // +inf float32 bit pattern
  %init_min = stablehlo.broadcast_in_dim %inf {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<f32>
  // Broadcast +inf to shape of conv along dim=1 for reduce init
  // Actually, reduce init must be scalar tensor of element type, so just use %inf as scalar tensor

  %min = "stablehlo.reduce"(%conv, %inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.minimum %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1>} : (tensor<16x7x14x14xf32>, tensor<f32>) -> tensor<16x1x14x14xf32>

  // Step 3: torch.sum(x, dim=2, keepdim=True)
  // Sum along height dimension (dim=2), keepdim=True
  // stablehlo.reduce with initial value 0.0

  %zero = stablehlo.constant dense<0.0> : tensor<f32>

  %sum = "stablehlo.reduce"(%min, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x1x14x14xf32>, tensor<f32>) -> tensor<16x1x1x14xf32>

  // Step 4: GELU activation
  // GELU(x) = 0.5 * x * (1 + erf(x / sqrt(2)))
  // Implement with stablehlo ops and chlo.erf

  %c0_5 = stablehlo.constant dense<0.5> : tensor<f32>
  %c1 = stablehlo.constant dense<1.0> : tensor<f32>
  %sqrt2 = stablehlo.constant dense<1.4142135623730951> : tensor<f32>  // sqrt(2)
  %inv_sqrt2 = stablehlo.divide %c1, %sqrt2 : tensor<f32>  // 1/sqrt(2)

  %x_div_sqrt2 = stablehlo.multiply %sum, %inv_sqrt2 : tensor<16x1x1x14xf32>

  %erf_x = "chlo.erf"(%x_div_sqrt2) : (tensor<16x1x1x14xf32>) -> tensor<16x1x1x14xf32>

  %one_plus_erf = stablehlo.add %c1, %erf_x : tensor<16x1x1x14xf32>

  %gelu = stablehlo.multiply %sum, %one_plus_erf : tensor<16x1x1x14xf32>

  %gelu_scaled = stablehlo.multiply %c0_5, %gelu : tensor<16x1x1x14xf32>

  // Step 5: Add bias (self.bias) to gelu output
  // bias shape: (1,1,1,f32) but output shape is (16,1,1,14)
  // Broadcast bias to output shape

  %bias_broadcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 3>} : (tensor<1x1x1xf32>) -> tensor<16x1x1x14xf32>

  %out = stablehlo.add %gelu_scaled, %bias_broadcast : tensor<16x1x1x14xf32>

  return %out : tensor<16x1x1x14xf32>
}

