  %bias_broadcast_4d = "stablehlo.broadcast_in_dim"(%bias_broadcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<1x7x1x1xf32>) -> tensor<16x7x15x15xf32>
  %conv_bias = stablehlo.add %conv, %bias_broadcast_4d : tensor<16x7x15x15xf32>

