      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<16x7x15x15xf32>, tensor<f32>) -> tensor<16x7xf32>

  %divisor0 = stablehlo.constant dense<225.0> : tensor<f32>
  %divisor0_broadcast = "stablehlo.broadcast_in_dim"(%divisor0) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x7xf32>
  %mean0 = stablehlo.divide %sum0, %divisor0_broadcast : tensor<16x7xf32>

