      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<16x7x1x1xf32>, tensor<f32>) -> tensor<16x7xf32>

  %divisor1 = stablehlo.constant dense<1.0> : tensor<f32>
  %divisor1_broadcast = "stablehlo.broadcast_in_dim"(%divisor1) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x7xf32>
  %mean1 = stablehlo.divide %sum1, %divisor1_broadcast : tensor<16x7xf32>

  // Reshape mean1 to (16,7,1,1)
  %mean1_reshaped = stablehlo.reshape %mean1 : (tensor<16x7xf32>) -> tensor<16x7x1x1xf32>

