func.func @main(%arg0: tensor<6x6x3x7xf32>, %arg1: tensor<8x6x7x7xf32>) -> tensor<8x6x9x13xf32> {
  // %arg0: conv_transpose2d.weight with shape [in_channels=6, out_channels=6, kernel_h=3, kernel_w=7]
  // %arg1: input tensor with shape [batch=8, in_channels=6, height=7, width=7]

