  // swapping input/output channels dims, and adjusting strides, padding, and output shape accordingly.

  // Step 1: Reverse the kernel spatial dimensions (height and width)
  %rev_kernel = "stablehlo.reverse"(%arg0) {dimensions = dense<[2, 3]> : tensor<2xi64>} : (tensor<6x6x3x7xf32>) -> tensor<6x6x3x7xf32>

