  // mean = reduce mean over dims 2,3
  %zero_f32 = stablehlo.constant dense<0.0> : tensor<f32>
  %init_mean = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16xf32>
  %init_var = "stablehlo.broadcast_in_dim"(%zero_f32) {broadcast_dimensions = array<i64: 0} : (tensor<f32>) -> tensor<16xf32>

  // Reduce sum over dims 2 and 3 for mean
  %sum_spatial = "stablehlo.reduce"(%conv_bias, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
