  %spatial_size = stablehlo.constant dense<196.0> : tensor<f32>  // 14*14=196
  %spatial_size_bcast = "stablehlo.broadcast_in_dim"(%spatial_size) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
  %mean = stablehlo.divide %sum_spatial, %spatial_size_bcast : tensor<16x16xf32>

