  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x14x14xf32>

  // Compute (x - mean)^2
  %diff = stablehlo.subtract %conv_bias, %mean_bcast : tensor<16x16x14x14xf32>
  %diff_sq = stablehlo.multiply %diff, %diff : tensor<16x16x14x14xf32>

  // Reduce sum over dims 2 and 3 for variance
  %sum_var = "stablehlo.reduce"(%diff_sq, %zero_f32) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %c = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%c) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<16x16x14x14xf32>, tensor<f32>) -> tensor<16x16xf32>

  // variance = sum_var / 196
  %var = stablehlo.divide %sum_var, %spatial_size_bcast : tensor<16x16xf32>

  // Add eps=1e-5 to variance
