  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<f32>) -> tensor<16x16xf32>
  %var_eps = stablehlo.add %var, %eps_bcast : tensor<16x16xf32>

  // Compute rsqrt(var + eps)
  %inv_std = stablehlo.rsqrt %var_eps : tensor<16x16xf32>

  // Broadcast weight and bias to 16x16 for batch and channel dims
  // weight: %arg2 (16), bias: %arg3 (16)
  // Broadcast to 16x16 (batch x channel)
  %weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
