  // Apply scale and shift: norm * weight + bias
  %scaled = stablehlo.multiply %norm, %weight_bcast_4d : tensor<16x16x14x14xf32>
  %shifted = stablehlo.add %scaled, %bias_bcast_4d : tensor<16x16x14x14xf32>

