  %six_bcast = "stablehlo.broadcast_in_dim"(%six) {broadcast_dimensions = array<i64: 0>} : (tensor<f32>) -> tensor<16x16x14x14xf32>

  %x_plus_3 = stablehlo.add %tanh, %three_bcast

