  %var_sum = stablehlo.reduce %diff_sq dimensions = [2, 3] keep_dims = true {
    ^bb0(%a: f32, %b: f32):
      %sum = stablehlo.add %a, %b : f32
      stablehlo.return %sum : f32
  } : tensor<16x16x14x14xf32> to tensor<16x16x1x1xf32>

  %var = stablehlo.div %var_sum, %c196_bcast : tensor<16x16x1x1xf32>

  // Add eps=1e-5 to variance
  %eps = stablehlo.constant dense<0.00001> : tensor<f32>
  %eps_bcast = stablehlo.broadcast_in_dim %eps : tensor<f32> to tensor<16x16x1x1xf32> broadcast_dimensions = []

  %var_eps = stablehlo.add %var, %eps_bcast : tensor<16x16x1x1xf32>

  // sqrt(var + eps)
  %stddev = stablehlo.sqrt %var_eps : tensor<16x16x1x1xf32>

  // normalize: (x - mean) / stddev
  %stddev_bcast = stablehlo.broadcast_in_dim %stddev : tensor<16x16x1x1xf32> to tensor<16x16x14x14xf32> broadcast_dimensions = [0,1,2,3]
