  %gn_bias_bcast = stablehlo.broadcast_in_dim %arg3 : tensor<16xf32> to tensor<16x16x14x14xf32> broadcast_dimensions = [1]

  %scaled = stablehlo.multiply %x_norm, %gn_weight_bcast : tensor<16x16x14x14xf32>
  %shifted = stablehlo.add %scaled, %gn_bias_bcast : tensor<16x16x14x14xf32>

