  %c3 = stablehlo.constant dense<3.0> : tensor<f32>
  %c3_bcast = stablehlo.broadcast_in_dim %c3 : tensor<f32> to tensor<16x16x14x14xf32> broadcast_dimensions = []

  %x_plus_3 = stablehlo.add %tanh, %c3_bcast : tensor<16x16x14x14xf32>

  // max(0, x+3)
  %c0 = stablehlo.constant dense<0.0> : tensor<f32>
  %c0_bcast = stablehlo.broadcast_in_dim %c0 : tensor<f32> to tensor<16x16x14x14xf32> broadcast_dimensions = []

  %relu6_lower = stablehlo.maximum %x_plus_3, %c0_bcast : tensor<16x16x14x14xf32>

  // min(relu6_lower, 6)
  %c6 = stablehlo.constant dense<6.0> : tensor<f32>
  %c6_bcast = stablehlo.broadcast_in_dim %c6 : tensor<f32> to tensor<16x16x14x14xf32> broadcast_dimensions = []

  %relu6 = stablehlo.minimum %relu6_lower, %c6_bcast : tensor<16x16x14x14xf32>

  // relu6 / 6
  %relu6_div6 = stablehlo.div %relu6, %c6_bcast : tensor<16x16x14x14xf32>

  // x * (relu6(x+3)/6)
  %hard_swish = stablehlo.multiply %tanh, %relu6_div6 : tensor<16x16x14x14xf32>

func.func @main(%arg0: tensor<16x8x3x3xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x8x16x16xf32>) -> tensor<16x1x14x14xf32> {
